-- SOURCE: 20261005010000_traffic_detail_suggestions.sql
-- Read-only, bounded name suggestions. Uses caller privileges and existing RLS.
-- No tables, data rewrites, or privilege elevation.
create or replace function public.traffic_reference_name(p_data jsonb)
returns text language plpgsql immutable security invoker set search_path = pg_catalog as $$
declare v jsonb := p_data; s text; k text;
begin
  if jsonb_typeof(v) = 'string' then
    s := btrim(v #>> '{}');
    if left(s,1) in ('{','[') then
      begin v := s::jsonb; exception when invalid_text_representation then return s; end;
    else return s; end if;
  end if;
  foreach k in array array['Name','name','Назва','Текст','text','ПІБ'] loop
    if jsonb_typeof(v->k) in ('string','number') then
      s := btrim(v->>k);
      if s <> '' then return s; end if;
    end if;
  end loop;
  return null;
end $$;



create or replace function public.traffic_detail_suggestions(p_query text, p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path = pg_catalog, public as $$
  with matches as (
    select d.detail_id, public.traffic_reference_name(to_jsonb(d.data)) as name
    from public.details d
  ), page as (
    select detail_id, name from matches
    where name is not null and strpos(lower(name), lower(btrim(coalesce(p_query,'')))) > 0
    order by name, detail_id
    offset greatest(coalesce(p_offset,0),0) limit 21
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(to_jsonb(x)) from
      (select * from page order by name, detail_id limit 20) x), '[]'::jsonb),
    'has_more', (select count(*) > 20 from page)
  );
$$;

-- Exact case-insensitive reference lookup; historic duplicates keep their IDs.
-- Prefer exact spelling, then the oldest stable ID, matching existing lookup intent.
create or replace function public.traffic_reference_id(p_kind text, p_name text)
returns bigint language plpgsql stable security invoker set search_path = pg_catalog, public as $$
declare result bigint;
begin
  if nullif(btrim(p_name),'') is null then return null; end if;
  if p_kind = 'details' then
    select d.detail_id into result from public.details d
    where regexp_replace(lower(btrim(public.traffic_reference_name(to_jsonb(d.data)))), '[[:space:]]+', ' ', 'g') = regexp_replace(lower(btrim(p_name)), '[[:space:]]+', ' ', 'g')
    order by (public.traffic_reference_name(to_jsonb(d.data)) = btrim(p_name)) desc, d.detail_id limit 1;
  elsif p_kind = 'shops' then
    select s.shop_id into result from public.shops s
    where regexp_replace(lower(btrim(public.traffic_reference_name(to_jsonb(s.data)))), '[[:space:]]+', ' ', 'g') = regexp_replace(lower(btrim(p_name)), '[[:space:]]+', ' ', 'g')
    order by (public.traffic_reference_name(to_jsonb(s.data)) = btrim(p_name)) desc, s.shop_id limit 1;
  else raise exception 'Unsupported reference'; end if;
  return result;
end $$;

create or replace function public.traffic_reference_ids(p_items jsonb)
returns jsonb language plpgsql stable security invoker set search_path = pg_catalog, public as $$
begin
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) > 100 then
    raise exception 'Expected at most 100 names';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('kind', x->>'kind', 'name', x->>'name',
    'id', public.traffic_reference_id(x->>'kind', x->>'name'))) from jsonb_array_elements(p_items) x), '[]'::jsonb);
end $$;


-- SOURCE: 20261005100000_traffic_service_book.sql
-- Additive read-only API. Uses the caller's existing table permissions and RLS.

create or replace function public.sto_read_object_v1(p_value jsonb)
returns jsonb language plpgsql immutable security invoker
set search_path = pg_catalog
as $$
declare parsed jsonb;
begin
  if jsonb_typeof(p_value) = 'object' then return p_value; end if;
  if jsonb_typeof(p_value) = 'string' then
    begin
      parsed := (p_value #>> '{}')::jsonb;
      if jsonb_typeof(parsed) = 'object' then return parsed; end if;
    exception when invalid_text_representation then return '{}'::jsonb;
    end;
  end if;
  return '{}'::jsonb;
end;
$$;

create or replace function public.sto_service_book_search_v1(
  p_query text, p_after bigint default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with candidates as (
    select c.cars_id, c.client_id,
      public.sto_read_object_v1(c.data::jsonb) as car_data,
      public.sto_read_object_v1(cl.data::jsonb) as client_data
    from public.cars c
    left join public.clients cl on cl.client_id = c.client_id
    where c.is_deleted is not true
      and (p_after is null or c.cars_id > p_after)
  ), page as (
    select * from candidates
    where length(btrim(coalesce(p_query, ''))) > 0
      and exists (
        select 1 from unnest(array[
          car_data->>'Авто', car_data->>'Номер авто', car_data->>'Vincode',
          car_data->>'КодДВЗ', client_data->>'ПІБ', client_data->>'Телефон'
        ]) as value(text_value)
        where strpos(lower(coalesce(text_value, '')), lower(btrim(p_query))) > 0
      )
    order by cars_id limit 21
  ), visible as (select * from page order by cars_id limit 20)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'car', jsonb_build_object('cars_id', cars_id, 'client_id', client_id, 'data', car_data),
      'client', jsonb_build_object('client_id', client_id, 'data', client_data)
    ) order by cars_id) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 20 from page),
    'next_cursor', (select max(cars_id) from visible)
  );
$$;

revoke all on function public.sto_read_object_v1(jsonb) from public;
revoke all on function public.sto_service_book_search_v1(text,bigint) from public;
grant execute on function public.sto_read_object_v1(jsonb) to anon, authenticated;
grant execute on function public.sto_service_book_search_v1(text,bigint) to anon, authenticated;


-- SOURCE: 20261005110000_traffic_act_read_models.sql
-- Requires 20261005100000_traffic_service_book.sql (JSON compatibility helper).
-- Read models only: never use these partial documents for saving or offline editing.

create or replace function public.sto_act_list_data_v1(p_data jsonb)
returns jsonb language sql immutable security invoker
set search_path = pg_catalog, public
as $$
  with d as (select public.sto_read_object_v1(p_data) as value)
  select case when p_data is null or p_data in ('null'::jsonb, '""'::jsonb, 'false'::jsonb, '0'::jsonb)
    then p_data else coalesce((select jsonb_object_agg(key, value) from jsonb_each(d.value)
    where key = any(array['Номер авто','Держ. номер','Автомобіль','Авто','Марка',
      'Загальна сума','total','amount','Знижка','За деталі','За роботу','Дзвінок',
      'Примітки','Рекомендації','Причина звернення','Заморожений'])), '{}'::jsonb)
    || jsonb_build_object(
      'Роботи', coalesce((select jsonb_agg(jsonb_build_object(
        'Робота', w->'Робота', 'Назва', w->'Назва', 'Слюсар', w->'Слюсар'))
        from jsonb_array_elements(case when jsonb_typeof(d.value->'Роботи')='array'
          then d.value->'Роботи' else '[]'::jsonb end) w), '[]'::jsonb),
      'Деталі', coalesce((select jsonb_agg(jsonb_build_object(
        'Деталь', w->'Деталь', 'Назва', w->'Назва'))
        from jsonb_array_elements(case when jsonb_typeof(d.value->'Деталі')='array'
          then d.value->'Деталі' else '[]'::jsonb end) w), '[]'::jsonb)
    ) end from d;
$$;

create or replace function public.sto_act_list_page_v1(
  p_from timestamptz default null, p_to timestamptz default null,
  p_mode text default null, p_before bigint default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with page as (
    select a.* from public.acts a
    where (p_before is null or a.act_id < p_before)
      and case p_mode
        when 'open' then a.date_off is null
        when 'closed' then a.date_off is not null
        when 'frozen' then true
        else p_from is not null and p_to is not null and a.date_on >= p_from and a.date_on <= p_to
      end
    order by a.act_id desc limit 201
  ), visible as (select * from page order by act_id desc limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(
      (to_jsonb(a) - 'data' - 'info' - 'details') || jsonb_build_object(
        'data', public.sto_act_list_data_v1(a.data::jsonb),
        '__sto_projection', 'act-list-v1'
      ) || case when to_jsonb(a)->>'info' is not null then jsonb_build_object(
        'info', public.sto_act_list_data_v1(to_jsonb(a)->'info')) else '{}'::jsonb end
        || case when to_jsonb(a)->>'details' is not null then jsonb_build_object(
        'details', public.sto_act_list_data_v1(to_jsonb(a)->'details')) else '{}'::jsonb end
      order by a.act_id desc) from visible a), '[]'::jsonb),
    'has_more', (select count(*) > 200 from page),
    'next_cursor', (select min(act_id) from visible)
  );
$$;

create or replace function public.sto_previous_recommendations_v1(
  p_car_id bigint, p_exclude_act bigint, p_before bigint default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with page as (
    select a.act_id, a.cars_id, a.date_off, a.pruimalnyk,
      public.sto_read_object_v1(a.data::jsonb) as d
    from public.acts a where a.cars_id = p_car_id and a.act_id <> p_exclude_act
      and (p_before is null or a.act_id < p_before)
    order by a.act_id desc limit 201
  ), visible as (select * from page order by act_id desc limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'act_id', act_id, 'cars_id', cars_id, 'date_off', date_off, 'pruimalnyk', pruimalnyk,
      'data', jsonb_build_object('Рекомендації', d->'Рекомендації',
        'Заморожений', d->'Заморожений') || case when d ? '__workshop_v1'
          then jsonb_build_object('__workshop_v1', d->'__workshop_v1') else '{}'::jsonb end
      ) order by act_id desc) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 200 from page),
    'next_cursor', (select min(act_id) from visible)
  );
$$;

create or replace function public.sto_act_attention_page_v1(
  p_after bigint default null, p_reception text default null
) returns jsonb language sql stable security invoker
set search_path = pg_catalog, public
as $$
  with page as (
    select a.act_id, a.date_on, a.date_off, a.pruimalnyk, a."slusarsOn",
      public.sto_read_object_v1(a.data::jsonb) as d
    from public.acts a
    where (p_after is null or a.act_id > p_after)
      and (p_reception is null or a.pruimalnyk = p_reception)
    order by a.act_id limit 201
  ), visible as (select * from page order by act_id limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'act_id', act_id, 'date_on', date_on, 'date_off', date_off,
      'pruimalnyk', pruimalnyk, 'slusarsOn', "slusarsOn",
      'data', jsonb_build_object(
        'Заморожений', d->'Заморожений', '__payroll_pending', d->'__payroll_pending',
        'Роботи', coalesce((select jsonb_agg(jsonb_build_object(
          'Робота', w->'Робота', 'Слюсар', w->'Слюсар', 'Ціна', w->'Ціна'))
          from jsonb_array_elements(case when jsonb_typeof(d->'Роботи')='array'
            then d->'Роботи' else '[]'::jsonb end) w), '[]'::jsonb),
        'Деталі', coalesce((select jsonb_agg(jsonb_build_object(
          'Деталь', w->'Деталь', 'Ціна', w->'Ціна'))
          from jsonb_array_elements(case when jsonb_typeof(d->'Деталі')='array'
            then d->'Деталі' else '[]'::jsonb end) w), '[]'::jsonb)
      ) || case when d ? '__workshop_v1' then jsonb_build_object(
        '__workshop_v1', d->'__workshop_v1') else '{}'::jsonb end
    ) order by act_id) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 200 from page),
    'next_cursor', (select max(act_id) from visible)
  );
$$;

revoke all on function public.sto_act_attention_page_v1(bigint,text) from public;
grant execute on function public.sto_act_attention_page_v1(bigint,text) to anon, authenticated;
revoke all on function public.sto_act_list_data_v1(jsonb) from public;
revoke all on function public.sto_act_list_page_v1(timestamptz,timestamptz,text,bigint) from public;
revoke all on function public.sto_previous_recommendations_v1(bigint,bigint,bigint) from public;
grant execute on function public.sto_act_list_data_v1(jsonb) to anon, authenticated;
grant execute on function public.sto_act_list_page_v1(timestamptz,timestamptz,text,bigint) to anon, authenticated;
grant execute on function public.sto_previous_recommendations_v1(bigint,bigint,bigint) to anon, authenticated;


-- SOURCE: 20261005130000_traffic_reports.sql
-- Narrow accounting read contract. No tables, writes, or privilege escalation.
create or replace function public.traffic_json_object(p_value jsonb)
returns jsonb language plpgsql immutable security invoker set search_path = public
as $$
begin
  if jsonb_typeof(p_value) = 'string' then
    p_value := (p_value #>> '{}')::jsonb;
  end if;
  if jsonb_typeof(p_value) = 'object' then return p_value; end if;
  return '{}'::jsonb;
exception when invalid_text_representation then
  return '{}'::jsonb;
end;
$$;

create or replace function public.traffic_accounting_statuses(p_ids bigint[] default null, p_after bigint default null, p_limit integer default 200)
returns jsonb language sql stable security invoker set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'act_id', q.act_id, 'date_off', q.date_off, 'rosraxovano', q.rosraxovano,
    'data', jsonb_build_object('Заморожений', q.body->'Заморожений',
      '__payroll_pending', q.body->'__payroll_pending', 'Знижка', q.body->'Знижка')
  ) order by q.act_id), '[]'::jsonb)
  from (
    select a.act_id, a.date_off, a.rosraxovano,
      public.traffic_json_object(a.data::jsonb) as body
    from public.acts a
    where (p_ids is null or a.act_id = any(p_ids)) and (p_after is null or a.act_id > p_after)
    order by a.act_id limit greatest(1, least(coalesce(p_limit, 200), 200))
  ) q;
$$;
-- The existing custom employee login can use the anon database role. INVOKER
-- preserves that role's existing table grants/RLS; this does not bypass them.
revoke all on function public.traffic_accounting_statuses(bigint[],bigint,integer) from public;
grant execute on function public.traffic_accounting_statuses(bigint[],bigint,integer) to anon, authenticated;

-- Employee labels without payroll history. Caller RLS remains authoritative.
create or replace function public.traffic_employee_names()
returns jsonb language sql stable security invoker set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('slyusar_id', s.slyusar_id,
    'name', public.traffic_json_object(s.data::jsonb)->>'Name') order by s.slyusar_id), '[]'::jsonb)
  from public.slyusars s;
$$;
revoke all on function public.traffic_employee_names() from public;
grant execute on function public.traffic_employee_names() to anon, authenticated;

-- Edge authorization also supports legacy string-encoded employee JSON without
-- transferring the employee's payroll history. Service-role callers only.
create or replace function public.traffic_np_employee(p_id bigint)
returns jsonb language sql stable security invoker set search_path = public
as $$
  select jsonb_build_object('slyusar_id', s.slyusar_id,
    'name', public.traffic_json_object(s.data::jsonb)->>'Name',
    'role', public.traffic_json_object(s.data::jsonb)->>'Доступ')
  from public.slyusars s where s.slyusar_id = p_id;
$$;
revoke all on function public.traffic_np_employee(bigint) from public, anon, authenticated;
grant execute on function public.traffic_np_employee(bigint) to service_role;

-- Search before transfer; only fields actually used by Atlas lookup cards.
-- Search normalization is supplied by the existing UI parser, not guessed here.
create or replace function public.traffic_ai_lookup(
  p_names text[] default '{}', p_phone text default '', p_brand text default '',
  p_plate text default '', p_vin text default '', p_limit integer default 50)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with clients as (
    select c.client_id, public.traffic_json_object(c.data::jsonb) d from public.clients c
  ), cars as (
    select c.cars_id, c.client_id, public.traffic_json_object(c.data::jsonb) d
    from public.cars c where c.is_deleted is not true
  ), direct_clients as (
    select c.* from clients c where
      (cardinality(coalesce(p_names,'{}')) = 0 and p_phone = '' and p_brand = '' and p_plate = '' and p_vin = '') or
      exists (select 1 from unnest(p_names) n where n <> '' and
        position(lower(n) in lower(coalesce(nullif(c.d->>'ПІБ',''),c.d->>'Клієнт',''))) > 0)
      or (p_phone <> '' and (position(p_phone in regexp_replace(coalesce(c.d->>'Телефон',''),'[^0-9]','','g')) > 0
        or position(p_phone in regexp_replace(coalesce(c.d->>'Додатковий',''),'[^0-9]','','g')) > 0))
  ), matched_cars as (
    select c.* from cars c where
      (cardinality(coalesce(p_names,'{}')) = 0 and p_phone = '' and p_brand = '' and p_plate = '' and p_vin = '') or
      (p_brand <> '' and position(lower(p_brand) in lower(coalesce(c.d->>'Авто',''))) > 0)
      or (p_plate <> '' and position(p_plate in regexp_replace(translate(upper(coalesce(c.d->>'Номер авто','')),
        'АВЕКМНОРСТУХІЇ','ABEKMHOPCTYXII'),'[^A-Z0-9]','','g')) > 0)
      or (p_vin <> '' and position(p_vin in regexp_replace(translate(upper(coalesce(nullif(c.d->>'Vincode',''),c.d->>'VIN','')),
        'АВЕКМНОРСТУХІЇ','ABEKMHOPCTYXII'),'[^A-Z0-9]','','g')) > 0)
      or c.client_id in (select client_id from direct_clients)
  ), matched_clients as (
    select c.* from clients c where c.client_id in (select client_id from direct_clients)
      or c.client_id in (select client_id from matched_cars)
  ), client_page as (
    select * from matched_clients order by client_id limit greatest(1,least(coalesce(p_limit,50),200))
  ), car_page as (
    select * from matched_cars order by cars_id limit greatest(1,least(coalesce(p_limit,50),200))
  )
  select jsonb_build_object(
    'clients', coalesce((select jsonb_agg(jsonb_build_object('client_id',c.client_id,'data',
      (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(c.d)
       where key = any(array['ПІБ','Клієнт','Телефон','Джерело','Додаткові','Додатковий']))) order by c.client_id) from client_page c),'[]'::jsonb),
    'cars', coalesce((select jsonb_agg(jsonb_build_object('cars_id',c.cars_id,'client_id',c.client_id,'data',
      (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(c.d)
       where key = any(array['Авто','Номер авто','Vincode','VIN','Рік','Обʼєм','Об''єм','Пальне','КодДВЗ']))) order by c.cars_id) from car_page c),'[]'::jsonb),
    'clientCount',(select count(*) from matched_clients), 'carCount',(select count(*) from matched_cars)
  );
$$;
revoke all on function public.traffic_ai_lookup(text[],text,text,text,text,integer) from public;
grant execute on function public.traffic_ai_lookup(text[],text,text,text,text,integer) to anon, authenticated;



-- SOURCE: 20261006010000_traffic_stock_directory.sql
-- Compact stock form directories; preserves caller privileges and existing RLS.
-- Requires 20261005010000_traffic_detail_suggestions.sql. No tables or data changes.
create or replace function public.traffic_stock_staff_data(p_data jsonb)
returns jsonb language plpgsql immutable security invoker set search_path = pg_catalog as $$
declare v jsonb := p_data;
begin
  if jsonb_typeof(v) = 'string' then
    begin v := (v #>> '{}')::jsonb; exception when invalid_text_representation then return '{}'::jsonb; end;
  end if;
  return jsonb_strip_nulls(jsonb_build_object(
    'Name', v->'Name', 'name', v->'name', 'Ім''я', v->'Ім''я',
    'Доступ', v->'Доступ', 'доступ', v->'доступ'));
end $$;

create or replace function public.traffic_stock_directory(p_kind text, p_offset integer default 0)
returns jsonb language plpgsql stable security invoker set search_path = pg_catalog, public as $$
declare rows jsonb;
begin
  if p_kind = 'staff' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select s.slyusar_id, public.traffic_stock_staff_data(to_jsonb(s.data)) as data
      from public.slyusars s order by s.slyusar_id
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  elsif p_kind = 'details' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select d.detail_id, public.traffic_reference_name(to_jsonb(d.data)) as name
      from public.details d order by d.detail_id
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  elsif p_kind = 'shops' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select s.shop_id, public.traffic_reference_name(to_jsonb(s.data)) as name
      from public.shops s order by s.shop_id
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  elsif p_kind = 'catalogs' then
    select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into rows from (
      select distinct btrim(s.part_number::text) as part_number, btrim(s.name::text) as name
      from public.sclad s where nullif(btrim(s.part_number::text),'') is not null
      order by part_number, name
      offset greatest(coalesce(p_offset,0),0) limit 501
    ) x;
  else raise exception 'Unsupported stock directory'; end if;
  return jsonb_build_object('items', (select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb)
    from jsonb_array_elements(rows) with ordinality where ordinality <= 500),
    'has_more', jsonb_array_length(rows) > 500);
end $$;


-- SOURCE: 20261006020000_traffic_export_pages.sql
-- Verified export: first pass returns canonical text, second only its SHA-256.
-- SECURITY INVOKER retains the same table privileges and RLS as direct reads.

create or replace function public.traffic_export_page(
  p_table text, p_keys text[], p_offset integer default 0,
  p_limit integer default 250, p_hash_only boolean default false
) returns jsonb language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
declare ordering text; payload text; row_count integer; total bigint; k text;
begin
  if p_table is null or not (p_table = any(array[
    'acts','clients','cars','sclad','works','details','shops','slyusars','settings',
    'incomes','vutratu','faktura','post_arxiv','post_category','post_name','sms','whitelist',
    'act_changes_notifications','slusar_complete_notifications','audit_logs','ai_chats',
    'ai_messages','ai_skills','atlas_reminder_logs','atlas_reminders','atlas_telegram_users'
  ])) then raise exception 'Unsupported export table'; end if;
  if p_offset is null or p_offset < 0 or p_limit is null or p_limit < 1 or p_limit > 250 then
    raise exception 'Invalid export page';
  end if;
  if coalesce(cardinality(p_keys),0) = 0 then raise exception 'Export ordering is required'; end if;
  foreach k in array p_keys loop
    if k is null or not exists (select 1 from pg_attribute
      where attrelid = format('public.%I',p_table)::regclass and attname = k
        and attnum > 0 and not attisdropped) then raise exception 'Unknown export key'; end if;
  end loop;
  select string_agg(format('%I asc', key), ',') into ordering from unnest(p_keys) key;
  execute format(
    'with page as (select * from public.%I order by %s offset $1 limit $2)
     select coalesce(jsonb_agg(to_jsonb(page) order by %s),''[]''::jsonb)::text,
       count(*)::integer, (select count(*) from public.%I) from page',
    p_table, ordering, ordering, p_table
  ) into payload, row_count, total using p_offset, p_limit;
  return jsonb_build_object('format','sto-canonical-page-v1',
    'payload', case when p_hash_only then null else payload end,
    'count',row_count,'total',total,'hash',encode(sha256(convert_to(payload,'UTF8')),'hex'));
end;
$$;
revoke all on function public.traffic_export_page(text,text[],integer,integer,boolean) from public;
grant execute on function public.traffic_export_page(text,text[],integer,integer,boolean) to authenticated;


-- SOURCE: 20261006030000_traffic_invoice_origins.sql
create or replace function public.traffic_invoice_origins(p_origins text[])
returns jsonb language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
begin
  if coalesce(cardinality(p_origins),0) > 100 then raise exception 'Too many invoice origins'; end if;
  return coalesce((select jsonb_agg(origin) from (
    select distinct origin from unnest(p_origins) origin
    where nullif(origin,'') is not null and exists (
      select 1 from public.sclad s where strpos(coalesce(s.prumitka,''), origin) > 0
    )
  ) found), '[]'::jsonb);
end;
$$;
revoke all on function public.traffic_invoice_origins(text[]) from public;
grant execute on function public.traffic_invoice_origins(text[]) to authenticated;


-- SOURCE: 20261006040000_traffic_analytics.sql
-- Analytics reads only; existing financial formulas remain in the browser.
-- Requires 20261005130000_traffic_reports.sql. No tables or writes.
create or replace function public.traffic_analytics_acts(p_after bigint default null)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with candidates as (
    select a.act_id, to_jsonb(a) as row_data,
      public.traffic_json_object(a.data::jsonb) as body
    from public.acts a
    where p_after is null or a.act_id > p_after
    order by a.act_id limit 201
  ), page as (
    select * from candidates order by act_id limit 200
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(
      (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
       from jsonb_each(p.row_data) where key = any(array[
         'act_id','date_on','date_off','rosraxovano','avans','tupOplatu','client_id','cars_id'
       ])) || jsonb_build_object('data',
         (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
          from jsonb_each(p.body) where key = any(array[
            'За роботу','За деталі','Прибуток за роботу','Прибуток за деталі',
            'Знижка','Заморожений','Роботи','Деталі'
          ])), '__sto_projection','analytics-v1')
      order by p.act_id) from page p),'[]'::jsonb),
    'has_more', (select count(*) > 200 from candidates),
    'next_cursor', (select max(act_id) from page)
  );
$$;
revoke all on function public.traffic_analytics_acts(bigint) from public;
grant execute on function public.traffic_analytics_acts(bigint) to anon, authenticated;


-- SOURCE: 20261006050000_traffic_act_staff.sql
-- Read-only employee metadata and complete history entries for one act.
-- Never use this projection as the baseline for saving an employee document.
create or replace function public.traffic_act_staff(p_act_id bigint default null, p_after bigint default null)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with candidates as (
    select s.slyusar_id, public.traffic_json_object(s.data::jsonb) as body
    from public.slyusars s
    where p_after is null or s.slyusar_id > p_after
    order by s.slyusar_id limit 201
  ), page as (select * from candidates order by slyusar_id limit 200)
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'slyusar_id', p.slyusar_id,
      'data', (p.body - 'Історія') || jsonb_build_object('Історія',
        coalesce((select jsonb_object_agg(day.key, entries.value)
          from jsonb_each(case when jsonb_typeof(p.body->'Історія')='object'
            then p.body->'Історія' else '{}'::jsonb end) day
          cross join lateral (
            select jsonb_agg(entry.value order by entry.ordinality) as value
            from jsonb_array_elements(case when jsonb_typeof(day.value)='array'
              then day.value else '[]'::jsonb end) with ordinality entry(value,ordinality)
            where p_act_id is not null and entry.value->>'Акт' = p_act_id::text
          ) entries
          where entries.value is not null),'{}'::jsonb)),
      '__sto_projection','act-staff-v1'
    ) order by p.slyusar_id) from page p),'[]'::jsonb),
    'has_more', (select count(*) > 200 from candidates),
    'next_cursor', (select max(slyusar_id) from page)
  );
$$;
revoke all on function public.traffic_act_staff(bigint,bigint) from public;
grant execute on function public.traffic_act_staff(bigint,bigint) to anon, authenticated;


-- SOURCE: 20261007010000_traffic_stock_shop_names.sql
-- Distinct supplier filter options from the stock itself, including historical
-- names absent from the shops directory. No trimming/renaming of stored values.
create or replace function public.traffic_stock_shop_names(p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path = public
as $$
  with names as (
    select distinct to_jsonb(s.shops) as value from public.sclad s
    where s.shops is not null and s.shops::text <> ''
  ), page as (
    select value from names order by value
    offset greatest(coalesce(p_offset,0),0) limit 501
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object('shops',value) order by value)
      from (select value from page order by value limit 500) visible),'[]'::jsonb),
    'has_more', (select count(*) > 500 from page)
  );
$$;
revoke all on function public.traffic_stock_shop_names(integer) from public;
grant execute on function public.traffic_stock_shop_names(integer) to anon, authenticated;


-- SOURCE: 20261007110000_traffic_stock_pages.sql
-- Stock page contract: caller permissions/RLS, no tables or history changes.
-- Unicode letter/number ranges generated from JavaScript's L/N categories (same UI normalizer).
create or replace function public.traffic_catalog_key(p_text text)
returns text language sql immutable security invoker set search_path=pg_catalog as $$
 select regexp_replace(lower(normalize(coalesce(p_text,''),NFKC)), '[^0-9A-Za-zª²-³µ¹-º¼-¾À-ÖØ-öø-ˁˆ-ˑˠ-ˤˬˮͰ-ʹͶ-ͷͺ-ͽͿΆΈ-ΊΌΎ-ΡΣ-ϵϷ-ҁҊ-ԯԱ-Ֆՙՠ-ֈא-תׯ-ײؠ-ي٠-٩ٮ-ٯٱ-ۓەۥ-ۦۮ-ۼۿܐܒ-ܯݍ-ޥޱ߀-ߪߴ-ߵߺࠀ-ࠕࠚࠤࠨࡀ-ࡘࡠ-ࡪࡰ-ࢇࢉ-ࢎࢠ-ࣉऄ-हऽॐक़-ॡ०-९ॱ-ঀঅ-ঌএ-ঐও-নপ-রলশ-হঽৎড়-ঢ়য়-ৡ০-ৱ৴-৹ৼਅ-ਊਏ-ਐਓ-ਨਪ-ਰਲ-ਲ਼ਵ-ਸ਼ਸ-ਹਖ਼-ੜਫ਼੦-੯ੲ-ੴઅ-ઍએ-ઑઓ-નપ-રલ-ળવ-હઽૐૠ-ૡ૦-૯ૹଅ-ଌଏ-ଐଓ-ନପ-ରଲ-ଳଵ-ହଽଡ଼-ଢ଼ୟ-ୡ୦-୯ୱ-୷ஃஅ-ஊஎ-ஐஒ-கங-சஜஞ-டண-தந-பம-ஹௐ௦-௲అ-ఌఎ-ఐఒ-నప-హఽౘ-ౚౝౠ-ౡ౦-౯౸-౾ಀಅ-ಌಎ-ಐಒ-ನಪ-ಳವ-ಹಽೝ-ೞೠ-ೡ೦-೯ೱ-ೲഄ-ഌഎ-ഐഒ-ഺഽൎൔ-ൖ൘-ൡ൦-൸ൺ-ൿඅ-ඖක-නඳ-රලව-ෆ෦-෯ก-ะา-ำเ-ๆ๐-๙ກ-ຂຄຆ-ຊຌ-ຣລວ-ະາ-ຳຽເ-ໄໆ໐-໙ໜ-ໟༀ༠-༳ཀ-ཇཉ-ཬྈ-ྌက-ဪဿ-၉ၐ-ၕၚ-ၝၡၥ-ၦၮ-ၰၵ-ႁႎ႐-႙Ⴀ-ჅჇჍა-ჺჼ-ቈቊ-ቍቐ-ቖቘቚ-ቝበ-ኈኊ-ኍነ-ኰኲ-ኵኸ-ኾዀዂ-ዅወ-ዖዘ-ጐጒ-ጕጘ-ፚ፩-፼ᎀ-ᎏᎠ-Ᏽᏸ-ᏽᐁ-ᙬᙯ-ᙿᚁ-ᚚᚠ-ᛪᛮ-ᛸᜀ-ᜑᜟ-ᜱᝀ-ᝑᝠ-ᝬᝮ-ᝰក-ឳៗៜ០-៩៰-៹᠐-᠙ᠠ-ᡸᢀ-ᢄᢇ-ᢨᢪᢰ-ᣵᤀ-ᤞ᥆-ᥭᥰ-ᥴᦀ-ᦫᦰ-ᧉ᧐-᧚ᨀ-ᨖᨠ-ᩔ᪀-᪉᪐-᪙ᪧᬅ-ᬳᭅ-ᭌ᭐-᭙ᮃ-ᮠᮮ-ᯥᰀ-ᰣ᱀-᱉ᱍ-ᱽᲀ-ᲊᲐ-ᲺᲽ-Ჿᳩ-ᳬᳮ-ᳳᳵ-ᳶᳺᴀ-ᶿḀ-ἕἘ-Ἕἠ-ὅὈ-Ὅὐ-ὗὙὛὝὟ-ώᾀ-ᾴᾶ-ᾼιῂ-ῄῆ-ῌῐ-ΐῖ-Ίῠ-Ῥῲ-ῴῶ-ῼ⁰-ⁱ⁴-⁹ⁿ-₉ₐ-ₜℂℇℊ-ℓℕℙ-ℝℤΩℨK-ℭℯ-ℹℼ-ℿⅅ-ⅉⅎ⅐-↉①-⒛⓪-⓿❶-➓Ⰰ-ⳤⳫ-ⳮⳲ-ⳳ⳽ⴀ-ⴥⴧⴭⴰ-ⵧⵯⶀ-ⶖⶠ-ⶦⶨ-ⶮⶰ-ⶶⶸ-ⶾⷀ-ⷆⷈ-ⷎⷐ-ⷖⷘ-ⷞⸯ々-〇〡-〩〱-〵〸-〼ぁ-ゖゝ-ゟァ-ヺー-ヿㄅ-ㄯㄱ-ㆎ㆒-㆕ㆠ-ㆿㇰ-ㇿ㈠-㈩㉈-㉏㉑-㉟㊀-㊉㊱-㊿㐀-䶿一-ꒌꓐ-ꓽꔀ-ꘌꘐ-ꘫꙀ-ꙮꙿ-ꚝꚠ-ꛯꜗ-ꜟꜢ-ꞈꞋ-ꟍꟐ-ꟑꟓꟕ-Ƛꟲ-ꠁꠃ-ꠅꠇ-ꠊꠌ-ꠢ꠰-꠵ꡀ-ꡳꢂ-ꢳ꣐-꣙ꣲ-ꣷꣻꣽ-ꣾ꤀-ꤥꤰ-ꥆꥠ-ꥼꦄ-ꦲꧏ-꧙ꧠ-ꧤꧦ-ꧾꨀ-ꨨꩀ-ꩂꩄ-ꩋ꩐-꩙ꩠ-ꩶꩺꩾ-ꪯꪱꪵ-ꪶꪹ-ꪽꫀꫂꫛ-ꫝꫠ-ꫪꫲ-ꫴꬁ-ꬆꬉ-ꬎꬑ-ꬖꬠ-ꬦꬨ-ꬮꬰ-ꭚꭜ-ꭩꭰ-ꯢ꯰-꯹가-힣ힰ-ퟆퟋ-ퟻ豈-舘並-龎ﬀ-ﬆﬓ-ﬗיִײַ-ﬨשׁ-זּטּ-לּמּנּ-סּףּ-פּצּ-ﮱﯓ-ﴽﵐ-ﶏﶒ-ﷇﷰ-ﷻﹰ-ﹴﹶ-ﻼ０-９Ａ-Ｚａ-ｚｦ-ﾾￂ-ￇￊ-ￏￒ-ￗￚ-ￜ𐀀-𐀋𐀍-𐀦𐀨-𐀺𐀼-𐀽𐀿-𐁍𐁐-𐁝𐂀-𐃺𐄇-𐄳𐅀-𐅸𐆊-𐆋𐊀-𐊜𐊠-𐋐𐋡-𐋻𐌀-𐌣𐌭-𐍊𐍐-𐍵𐎀-𐎝𐎠-𐏃𐏈-𐏏𐏑-𐏕𐐀-𐒝𐒠-𐒩𐒰-𐓓𐓘-𐓻𐔀-𐔧𐔰-𐕣𐕰-𐕺𐕼-𐖊𐖌-𐖒𐖔-𐖕𐖗-𐖡𐖣-𐖱𐖳-𐖹𐖻-𐖼𐗀-𐗳𐘀-𐜶𐝀-𐝕𐝠-𐝧𐞀-𐞅𐞇-𐞰𐞲-𐞺𐠀-𐠅𐠈𐠊-𐠵𐠷-𐠸𐠼𐠿-𐡕𐡘-𐡶𐡹-𐢞𐢧-𐢯𐣠-𐣲𐣴-𐣵𐣻-𐤛𐤠-𐤹𐦀-𐦷𐦼-𐧏𐧒-𐨀𐨐-𐨓𐨕-𐨗𐨙-𐨵𐩀-𐩈𐩠-𐩾𐪀-𐪟𐫀-𐫇𐫉-𐫤𐫫-𐫯𐬀-𐬵𐭀-𐭕𐭘-𐭲𐭸-𐮑𐮩-𐮯𐰀-𐱈𐲀-𐲲𐳀-𐳲𐳺-𐴣𐴰-𐴹𐵀-𐵥𐵯-𐶅𐹠-𐹾𐺀-𐺩𐺰-𐺱𐻂-𐻄𐼀-𐼧𐼰-𐽅𐽑-𐽔𐽰-𐾁𐾰-𐿋𐿠-𐿶𑀃-𑀷𑁒-𑁯𑁱-𑁲𑁵𑂃-𑂯𑃐-𑃨𑃰-𑃹𑄃-𑄦𑄶-𑄿𑅄𑅇𑅐-𑅲𑅶𑆃-𑆲𑇁-𑇄𑇐-𑇚𑇜𑇡-𑇴𑈀-𑈑𑈓-𑈫𑈿-𑉀𑊀-𑊆𑊈𑊊-𑊍𑊏-𑊝𑊟-𑊨𑊰-𑋞𑋰-𑋹𑌅-𑌌𑌏-𑌐𑌓-𑌨𑌪-𑌰𑌲-𑌳𑌵-𑌹𑌽𑍐𑍝-𑍡𑎀-𑎉𑎋𑎎𑎐-𑎵𑎷𑏑𑏓𑐀-𑐴𑑇-𑑊𑑐-𑑙𑑟-𑑡𑒀-𑒯𑓄-𑓅𑓇𑓐-𑓙𑖀-𑖮𑗘-𑗛𑘀-𑘯𑙄𑙐-𑙙𑚀-𑚪𑚸𑛀-𑛉𑛐-𑛣𑜀-𑜚𑜰-𑜻𑝀-𑝆𑠀-𑠫𑢠-𑣲𑣿-𑤆𑤉𑤌-𑤓𑤕-𑤖𑤘-𑤯𑤿𑥁𑥐-𑥙𑦠-𑦧𑦪-𑧐𑧡𑧣𑨀𑨋-𑨲𑨺𑩐𑩜-𑪉𑪝𑪰-𑫸𑯀-𑯠𑯰-𑯹𑰀-𑰈𑰊-𑰮𑱀𑱐-𑱬𑱲-𑲏𑴀-𑴆𑴈-𑴉𑴋-𑴰𑵆𑵐-𑵙𑵠-𑵥𑵧-𑵨𑵪-𑶉𑶘𑶠-𑶩𑻠-𑻲𑼂𑼄-𑼐𑼒-𑼳𑽐-𑽙𑾰𑿀-𑿔𒀀-𒎙𒐀-𒑮𒒀-𒕃𒾐-𒿰𓀀-𓐯𓑁-𓑆𓑠-𔏺𔐀-𔙆𖄀-𖄝𖄰-𖄹𖠀-𖨸𖩀-𖩞𖩠-𖩩𖩰-𖪾𖫀-𖫉𖫐-𖫭𖬀-𖬯𖭀-𖭃𖭐-𖭙𖭛-𖭡𖭣-𖭷𖭽-𖮏𖵀-𖵬𖵰-𖵹𖹀-𖺖𖼀-𖽊𖽐𖾓-𖾟𖿠-𖿡𖿣𗀀-𘟷𘠀-𘳕𘳿-𘴈𚿰-𚿳𚿵-𚿻𚿽-𚿾𛀀-𛄢𛄲𛅐-𛅒𛅕𛅤-𛅧𛅰-𛋻𛰀-𛱪𛱰-𛱼𛲀-𛲈𛲐-𛲙𜳰-𜳹𝋀-𝋓𝋠-𝋳𝍠-𝍸𝐀-𝑔𝑖-𝒜𝒞-𝒟𝒢𝒥-𝒦𝒩-𝒬𝒮-𝒹𝒻𝒽-𝓃𝓅-𝔅𝔇-𝔊𝔍-𝔔𝔖-𝔜𝔞-𝔹𝔻-𝔾𝕀-𝕄𝕆𝕊-𝕐𝕒-𝚥𝚨-𝛀𝛂-𝛚𝛜-𝛺𝛼-𝜔𝜖-𝜴𝜶-𝝎𝝐-𝝮𝝰-𝞈𝞊-𝞨𝞪-𝟂𝟄-𝟋𝟎-𝟿𝼀-𝼞𝼥-𝼪𞀰-𞁭𞄀-𞄬𞄷-𞄽𞅀-𞅉𞅎𞊐-𞊭𞋀-𞋫𞋰-𞋹𞓐-𞓫𞓰-𞓹𞗐-𞗭𞗰-𞗺𞟠-𞟦𞟨-𞟫𞟭-𞟮𞟰-𞟾𞠀-𞣄𞣇-𞣏𞤀-𞥃𞥋𞥐-𞥙𞱱-𞲫