-- SOURCE: 20261012133426_traffic_accounting_lazy_rows.sql
-- Viewport-sized accounting reads, then ten rows per scroll request.
-- No new tables. Keeps existing RLS, financial totals and payroll write baselines.
-- Also includes the preceding payroll timeout fix. Run in Supabase SQL Editor.

create or replace function public.traffic_payroll_validate(p_data jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare
 history jsonb:=coalesce(nullif(p_data->'Історія','null'::jsonb),'{}'::jsonb);
 missing_act boolean; invalid_records boolean; duplicate_act text; duplicate_record_act text;
begin
 if jsonb_typeof(history) is distinct from 'object' then raise exception 'Некоректна історія зарплат';end if;
 if exists(select 1 from jsonb_each(history) h where jsonb_typeof(h.value) is distinct from 'array') then
  raise exception 'Некоректна дата історії зарплат';
 end if;
 with entries as materialized (
  select x.value entry from jsonb_each(history) h cross join lateral jsonb_array_elements(h.value) x
 )
 select exists(select 1 from entries e where e.entry->>'Акт' is null),
  (select e.entry->>'Акт' from entries e group by e.entry->>'Акт' having count(*)>1 limit 1),
  exists(select 1 from entries e where e.entry?'Записи' and e.entry->'Записи'<>'null'::jsonb
   and jsonb_typeof(e.entry->'Записи') is distinct from 'array')
 into missing_act,duplicate_act,invalid_records;
 if missing_act then raise exception 'Нарахування без номера акта';end if;
 if duplicate_act is not null then raise exception 'Дублікати зарплати за актом %',duplicate_act;end if;
 if invalid_records then raise exception 'Некоректний список робіт';end if;
 select x.value->>'Акт' into duplicate_record_act
 from jsonb_each(history) h cross join lateral jsonb_array_elements(h.value) x
 cross join lateral jsonb_array_elements(coalesce(nullif(x.value->'Записи','null'::jsonb),'[]'::jsonb)) r
 where nullif(r.value->>'recordId','') is not null
 group by x.value->>'Акт',r.value->>'recordId' having count(*)>1 limit 1;
 if duplicate_record_act is not null then raise exception 'Повторні ідентифікатори робіт в акті %',duplicate_record_act;end if;
 return true;
end $$;

create or replace function public.traffic_payroll_report_optimized(
 p_filters jsonb,p_offset integer default 0,p_options boolean default true)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare
 result jsonb;
 page_size integer:=greatest(1,least(200,case when coalesce(p_filters->>'page_size','')~'^[0-9]{1,3}$' then (p_filters->>'page_size')::integer else 50 end));
 selected_name text:=coalesce(p_filters->>'name','');
 mode text:=coalesce(p_filters->>'mode','open');
 from_day text:=public.traffic_payroll_iso(p_filters->>'from');
 to_day text:=public.traffic_payroll_iso(p_filters->>'to');
begin
 if mode not in ('open','close','paid') then raise exception 'Невідомий режим дат';end if;
 if to_day='' then raise exception 'Потрібна кінцева дата звіту';end if;
 -- Keep validation global: a duplicate outside the date window must still block payment.
 perform public.traffic_payroll_validate(public.payroll_json_object(to_jsonb(s.data)))
 from public.slyusars s
 where selected_name='' or public.payroll_json_object(to_jsonb(s.data))->>'Name'=selected_name;

 with employee_docs as materialized (
  select s.slyusar_id id,public.payroll_json_object(to_jsonb(s.data)) doc from public.slyusars s
 ), employees as materialized (
  select * from employee_docs where selected_name='' or doc->>'Name'=selected_name
 ), history_days as materialized (
  select e.id,e.doc->>'Name' name,e.doc->'ПроцентРоботи' percent,
   h.key history_day,h.value bucket,public.traffic_payroll_iso(h.key) history_iso
  from employees e cross join lateral jsonb_each(coalesce(nullif(e.doc->'Історія','null'::jsonb),'{}'::jsonb)) h
 ), selected_days as materialized (
  -- Opening dates belong to history buckets. Filter them before expanding acts or works.
  select * from history_days where mode<>'open' or
   (history_iso<>'' and (from_day='' or history_iso>=from_day) and history_iso<=to_day)
 ), raw_entries as materialized (
  select d.id,d.name,d.percent,d.history_day,d.history_iso,x.value entry,x.ordinality entry_order,
   x.value->>'Акт' act,
   -- Cast the history value, never the indexed acts.act_id. Canonical text matching
   -- retains the old behavior for malformed, padded or out-of-range legacy IDs.
   case when x.value->>'Акт' ~ '^(0|[1-9][0-9]{0,18}|-[1-9][0-9]{0,18})$' then
    case when (x.value->>'Акт')::numeric between -9223372036854775808 and 9223372036854775807
     then (x.value->>'Акт')::bigint end end act_number
  from selected_days d cross join lateral jsonb_array_elements(d.bucket) with ordinality x
 ), act_ids as materialized (
  select distinct act_number from raw_entries where act_number is not null
 ), act_docs as materialized (
  -- Parse each referenced act once, even if several employees worked on it.
  select a.act_id,a.date_off,parsed.doc->'Заморожений'='true'::jsonb frozen,
   parsed.doc->'__payroll_pending'='true'::jsonb pending
  from act_ids i join public.acts a on a.act_id=i.act_number
  -- Keep one evaluation of the parser, but materialize only two flags, not act JSON.
  cross join lateral (select public.payroll_json_object(to_jsonb(a.data)) doc offset 0) parsed
 ), entries as materialized (
  select r.*,a.act_id existing_act_id,a.date_off,
   a.frozen,a.pending,
   case when a.act_id is not null then coalesce(a.date_off::text,'') else coalesce(r.entry->>'ДатаЗакриття','') end close_day,
   case when a.act_id is not null then a.date_off is not null else coalesce(r.entry->>'ДатаЗакриття','')<>'' end closed
  from raw_entries r left join act_docs a on a.act_id=r.act_number
 ), scoped_entries as materialized (
  -- Closing dates cannot be inferred from opening dates. Filter their effective
  -- act/legacy date after the join, but still before expanding works.
  select * from entries where not coalesce(frozen,false) and
   (mode<>'close' or (public.traffic_payroll_iso(close_day)<>''
    and (from_day='' or public.traffic_payroll_iso(close_day)>=from_day)
    and public.traffic_payroll_iso(close_day)<=to_day))
 ), expanded as (
  select e.*,case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0 then 'work'
   when entry?'СуммаРоботи' then 'receiver' when entry?'СуммаЗапчастин' then 'parts' else 'unknown' end kind,
   r.value row_data,r.ordinality::integer-1 work_index
  from scoped_entries e cross join lateral jsonb_array_elements(
   case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0
    then entry->'Записи' else '[null]'::jsonb end) with ordinality r
 ), dated_rows as (
  select e.*,d.paid_day,
   case when kind='work' then coalesce(row_data->>'Робота','') when kind='receiver' then '-' else 'Запчастини' end work,
   case when mode='paid' then public.traffic_payroll_iso(d.paid_day)
    when mode='close' then public.traffic_payroll_iso(close_day) else history_iso end filter_day
  from expanded e cross join lateral (
   select case when kind='work' then coalesce(row_data->>'Розраховано','') else coalesce(entry->>'Розраховано','') end paid_day
  ) d
  where kind<>'unknown' and not(kind='work' and coalesce(row_data->'Кількість'='0'::jsonb,false)
   and not public.traffic_search_truthy(row_data->'Зарплата'))
 ), value_rows as materialized (
  -- Store scalar report values only. Do not copy the complete act/work JSON into
  -- every expanded row of the materialized totals/sort pipeline.
  select id,name,percent,history_day,history_iso,entry_order,act,existing_act_id,date_off,closed,pending,
   kind,work_index,paid_day,work,
   coalesce(public.traffic_search_number(row_data->'Ціна'),0)*coalesce(public.traffic_search_number(row_data->'Кількість'),0) work_total,
   coalesce(public.traffic_search_number(row_data->'Зарплата'),0) work_salary,
   coalesce(public.traffic_search_number(entry->'СуммаРоботи'),0) work_sum,
   coalesce(public.traffic_search_number(entry->'СуммаЗапчастин'),0) parts_sum,
   coalesce(public.traffic_search_number(entry->'ЗарплатаРоботи'),0) receiver_work_salary,
   coalesce(public.traffic_search_number(entry->'ЗарплатаЗапчастин'),0) parts_salary
  from dated_rows where filter_day<>'' and (from_day='' or filter_day>=from_day) and filter_day<=to_day
 ), date_matches as materialized (
  select *,case when kind='work' then work_total when kind='receiver' then work_sum+parts_sum else parts_sum end revenue,
   case when kind='work' then work_salary when kind='receiver' then (case when work_sum>0 then receiver_work_salary else 0 end)+parts_salary
    else case when parts_sum>0 then parts_salary else 0 end end salary
  from value_rows
 ), matches as materialized (
  select * from date_matches where
   (coalesce(p_filters->>'act','')='' or act=p_filters->>'act')
   and (coalesce(p_filters->>'work','')='' or strpos(lower(work),lower(p_filters->>'work'))>0)
   and (coalesce(p_filters->>'payment','all')='all' or (p_filters->>'payment'='paid' and paid_day<>'') or (p_filters->>'payment'='unpaid' and paid_day=''))
   and (coalesce(p_filters->>'status','all')='all' or (p_filters->>'status'='closed' and closed) or (p_filters->>'status'='open' and not closed))
   and (coalesce(p_filters->>'percentage','all')='all' or (kind='work' and salary<>0 and coalesce(public.traffic_search_number(percent),0)<>0 and
    case when p_filters->>'percentage'='higher' then (case when revenue>0 then salary/revenue*100 else 0 end)>public.traffic_search_number(percent)
     else (case when revenue>0 then salary/revenue*100 else 0 end)<public.traffic_search_number(percent) end))
 ), page as materialized (
  select *,coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) sort_act,
   case when mode='paid' then public.traffic_payroll_iso(paid_day) else history_iso end sort_day
  from matches order by sort_act desc,sort_day desc,id,history_day,entry_order,work_index
  offset greatest(coalesce(p_offset,0),0) limit page_size
 ), page_entries as (
  -- Full act fragments remain available for the existing guarded payroll writes.
  select distinct p.id,p.name,p.percent,p.history_day,r.entry,p.entry_order
  from page p join raw_entries r on r.id=p.id and r.history_day=p.history_day and r.entry_order=p.entry_order
 ), histories as (
  select id,name,percent,history_day,jsonb_agg(entry order by entry_order) entries
  from page_entries group by id,name,percent,history_day
 ), rows as (
  select id,jsonb_build_object('slyusar_id',id,'data',jsonb_build_object('Name',name,'ПроцентРоботи',percent,'Історія',jsonb_object_agg(history_day,entries))) row
  from histories group by id,name,percent
 ), totals as (
  select count(*) total,coalesce(sum(revenue),0) revenue,coalesce(sum(salary),0) salary from matches
 )
 select jsonb_build_object(
  'employees',coalesce((select jsonb_agg(row order by id) from rows),'[]'::jsonb),
  'keys',coalesce((select jsonb_agg(jsonb_build_array(id,history_day,act,case when kind='work' then work_index else null end)
   order by sort_act desc,sort_day desc,id,history_day,entry_order,work_index) from page),'[]'::jsonb),
  'statuses',coalesce((select jsonb_agg(jsonb_build_object('actId',id,'dateOff',date_off,'isClosed',closed,'isFrozen',false,'payrollPending',pending))
   from (select distinct existing_act_id::text id,date_off,closed,pending from page where existing_act_id is not null)s),'[]'::jsonb),
  'page_size',page_size,'total',t.total,'revenue',t.revenue,'salary',t.salary,'has_more',t.total>greatest(coalesce(p_offset,0),0)+page_size,
  'acts',case when coalesce(p_options,true) then coalesce((select jsonb_agg(act order by coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) desc)
   from(select distinct act from date_matches)a),'[]'::jsonb) else '[]'::jsonb end,
  'works',case when coalesce(p_options,true) then coalesce((select jsonb_agg(work order by work)
   from(select distinct work from date_matches order by work limit 150)w),'[]'::jsonb) else '[]'::jsonb end
 ) into result from totals t;
 return result;
end $$;

-- Both deployed API versions use the same optimized query. A separate core
-- also keeps reinstalling the previous v2 wrapper safe (no wrapper recursion).
create or replace function public.traffic_payroll_report(p_filters jsonb,p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select public.traffic_payroll_report_optimized(p_filters,p_offset,true);
$$;
create or replace function public.traffic_payroll_report_v2(p_filters jsonb,p_offset integer default 0,p_options boolean default true)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select public.traffic_payroll_report_optimized(p_filters,p_offset,p_options);
$$;

revoke all on function public.traffic_payroll_validate(jsonb),public.traffic_payroll_report_optimized(jsonb,integer,boolean),
 public.traffic_payroll_report(jsonb,integer),public.traffic_payroll_report_v2(jsonb,integer,boolean) from public;
grant execute on function public.traffic_payroll_validate(jsonb),public.traffic_payroll_report_optimized(jsonb,integer,boolean),
 public.traffic_payroll_report(jsonb,integer),public.traffic_payroll_report_v2(jsonb,integer,boolean) to anon,authenticated;

create or replace function public.traffic_audit_page(p_filter jsonb default '{}'::jsonb,p_before timestamptz default null,p_before_id bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with params as (
  select greatest(1,least(200,case when coalesce(p_filter->>'page_size','')~'^[0-9]{1,3}$' then (p_filter->>'page_size')::integer else 50 end)) page_size
 ), source as (
  select id,created_at,user_login,user_role,action,act_id,
   coalesce(nullif(details->>'_category',''),case
    when action like 'act\_%' escape '\' or action in ('open_act','close_act','freeze_act','unfreeze_act','update_act_items','update_act_info') then 'act'
    when action like 'planning\_%' escape '\' then 'planning'
    when action like 'client\_%' escape '\' or action like 'car\_%' escape '\' then 'client'
    when action like 'settings\_%' escape '\' or action in ('db_edit_slyusars','db_delete_slyusars','db_add_slyusars') then 'settings'
    when action like 'warehouse\_%' escape '\' or action like 'db_edit\_%' escape '\' or action like 'db_delete\_%' escape '\' or action like 'db_add\_%' escape '\' then 'warehouse'
    else 'act' end) category
  from public.audit_logs
  where action<>'update_act_info'
   and (nullif(p_filter->>'from','') is null or created_at>=((p_filter->>'from')::date::timestamp at time zone 'Europe/Kyiv'))
   and (nullif(p_filter->>'to','') is null or created_at<(((p_filter->>'to')::date+1)::timestamp at time zone 'Europe/Kyiv'))
   and (nullif(p_filter->>'user','') is null or user_login=p_filter->>'user')
   and (nullif(p_filter->>'role','') is null or user_role=p_filter->>'role')
   and (p_before is null or (created_at,id)<(p_before,p_before_id))
 ), candidates as (
  select * from source where coalesce(p_filter->>'category','all')='all' or category=p_filter->>'category'
  order by created_at desc,id desc limit (select page_size+1 from params)
 ), page as (select * from candidates order by created_at desc,id desc limit (select page_size from params))
 select jsonb_build_object('page_size',(select page_size from params),'items',coalesce((select jsonb_agg(to_jsonb(p) order by created_at desc,id desc) from page p),'[]'),
  'has_more',(select count(*)>(select page_size from params) from candidates),
  'users',case when p_before is null then (select coalesce(jsonb_agg(v order by v),'[]') from (select distinct user_login v from public.audit_logs)u) else '[]'::jsonb end,
  'roles',case when p_before is null then (select coalesce(jsonb_agg(v order by v),'[]') from (select distinct user_role v from public.audit_logs where user_role is not null)u) else '[]'::jsonb end)
$$;

revoke all on function public.traffic_audit_page(jsonb,timestamptz,bigint) from public;
grant execute on function public.traffic_audit_page(jsonb,timestamptz,bigint) to anon,authenticated;
notify pgrst,'reload schema';

-- SOURCE: 20261013105659_payroll_pending_recovery.sql
-- SQL Editor, not Edge Functions. Requires payroll_fragments, traffic_payroll_employees
-- and act_editor_lease_guard. No new tables and no automatic data repair.


do $$
begin
 if to_regprocedure('public.payroll_act_entries(jsonb,text)') is null
  or to_regprocedure('public.write_payroll_fragments(bigint,text,jsonb)') is null
  or to_regprocedure('public.assert_editor_act_lease(integer,text)') is null
  or to_regprocedure('public.traffic_payroll_employees(bigint[],integer,bigint,text)') is null then
  raise exception 'Спочатку встановіть payroll_fragments, act_editor_lease_guard і traffic_payroll_employees з пакета оптимізації.';
 end if;
end $$;

create or replace function public.payroll_pending_acts(p_before integer default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare rows_json jsonb; more boolean; cursor_id integer;
begin
 with page as (
  select a.act_id,a.date_on,a.date_off,a.pruimalnyk
  from public.acts a
  where (p_before is null or a.act_id<p_before)
   and public.payroll_json_object(to_jsonb(a.data))->'__payroll_pending'='true'::jsonb
   and public.payroll_json_object(to_jsonb(a.data))->'Заморожений' is distinct from 'true'::jsonb
  order by a.act_id desc limit 51
 ), visible as (select * from page order by act_id desc limit 50)
 select coalesce((select jsonb_agg(to_jsonb(v) order by act_id desc) from visible v),'[]'::jsonb),
  (select count(*)>50 from page),(select min(act_id) from visible)
 into rows_json,more,cursor_id;
 return jsonb_build_object('rows',rows_json,'hasMore',more,'nextAfter',case when more then cursor_id else null end);
end $$;

create or replace function public.payroll_recovery_context(p_act_id integer)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare a public.acts%rowtype; doc jsonb; context_value jsonb;
begin
 select * into a from public.acts where act_id=p_act_id;
 if not found then raise exception 'Акт відсутній або недоступний' using errcode='40001';end if;
 doc:=public.payroll_json_object(to_jsonb(a.data));
 if doc->'Заморожений'='true'::jsonb then raise exception 'Заморожений акт не відновлюється автоматично' using errcode='55000';end if;
 context_value:=jsonb_build_object('date_on',a.date_on,'date_off',a.date_off,'pruimalnyk',a.pruimalnyk,'client_id',a.client_id,'cars_id',a.cars_id);
 return context_value||jsonb_build_object('act_id',a.act_id,'data',doc,'revision',doc->>'__act_revision',
  'checksum',md5(doc::text),'context_checksum',md5(context_value::text));
end $$;

-- Paid entries may keep updated display labels, but their financial content and
-- payment markers cannot disappear or be rewritten during recovery.
create or replace function public.assert_payroll_paid_preserved(p_expected jsonb,p_desired jsonb)
returns void language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare previous jsonb; next_value jsonb; item jsonb; matched jsonb; matches integer;
begin
 if p_expected=p_desired then return;end if;
 previous:=p_expected#>'{0,value}';next_value:=p_desired#>'{0,value}';
 if previous is null then return;end if;
 if (coalesce(previous->'Розраховано','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'""'::jsonb)
  or exists(select 1 from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb)) r
   where coalesce(r->'Розраховано','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'""'::jsonb)))
  and p_expected#>>'{0,date}' is distinct from p_desired#>>'{0,date}' then
  raise exception 'Дата оплаченої зарплати змінюється. Відновлення зупинено.' using errcode='55000';
 end if;
 if coalesce(previous->'Розраховано','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'""'::jsonb)
  and (next_value is null or (previous-array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input']) is distinct from
   (next_value-array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input'])) then
  raise exception 'Відновлення змінює оплачене нарахування. Потрібна перевірка; виплати збережено.' using errcode='55000';
 end if;
 for item in select value from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb)) loop
  if coalesce(item->'Розраховано','null'::jsonb) in ('null'::jsonb,'false'::jsonb,'""'::jsonb) then continue;end if;
  select count(*) into matches from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb)) r
   where case when nullif(item->>'recordId','') is not null then r->>'recordId'=item->>'recordId' else r=item end;
  if matches<>1 then raise exception 'Оплачена робота видаляється або змінює виконавця. Відновлення зупинено.' using errcode='55000';end if;
  select value into matched from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))
   where case when nullif(item->>'recordId','') is not null then value->>'recordId'=item->>'recordId' else value=item end;
  if matched is distinct from item then raise exception 'Сума або дані оплаченої роботи змінилися. Відновлення зупинено.' using errcode='55000';end if;
 end loop;
end $$;

create or replace function public.commit_act_payroll(
 p_act_id integer,p_checksum text,p_context_checksum text,p_revision text,
 p_next_revision text,p_employees jsonb,p_lock_owner text default null,p_stock jsonb default '[]'::jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare a public.acts%rowtype; held public.act_locks%rowtype; doc jsonb; context_value jsonb;
 item jsonb; employee public.slyusars%rowtype; employee_data jsonb; settings jsonb;
 actual jsonb; expected jsonb; desired jsonb; receipt jsonb; changed integer:=0;
 stock_row public.sclad%rowtype; stock_item jsonb;
begin
 if p_act_id is null or p_act_id<=0 or nullif(p_checksum,'') is null or nullif(p_context_checksum,'') is null
  or nullif(p_next_revision,'') is null or p_next_revision is not distinct from p_revision
  or jsonb_typeof(p_employees) is distinct from 'array' or jsonb_array_length(p_employees)>2000
  or jsonb_typeof(p_stock) is distinct from 'array' or jsonb_array_length(p_stock)>2000 then
  raise exception 'Некоректний пакет відновлення зарплати';
 end if;
 if exists(select 1 from jsonb_array_elements(p_employees)e where coalesce(e->>'id','')!~'^[1-9][0-9]*$')
  or exists(select 1 from jsonb_array_elements(p_employees)e group by e->>'id' having count(*)>1) then
  raise exception 'Некоректні ідентифікатори працівників';
 end if;
 if exists(select 1 from jsonb_array_elements(p_stock)e where coalesce(e->>'id','')!~'^[1-9][0-9]*$' or jsonb_typeof(e->'expected') is distinct from 'object')
  or exists(select 1 from jsonb_array_elements(p_stock)e group by e->>'id' having count(*)>1) then
  raise exception 'Некоректний знімок складу';
 end if;
 -- Match the editor's lock order: lease, act, employee IDs.
 if nullif(p_lock_owner,'') is not null then
  perform public.assert_editor_act_lease(p_act_id,p_lock_owner);
 else
  select * into held from public.act_locks where act_id=p_act_id for update;
  if found and held.heartbeat_at>clock_timestamp()-interval '90 seconds' then
   raise exception 'Акт відкритий у редакторі. Закрийте його та повторіть відновлення.' using errcode='55P03';
  end if;
 end if;
 select * into a from public.acts where act_id=p_act_id for update;
 if not found then raise exception 'Акт відсутній або недоступний' using errcode='40001';end if;
 doc:=public.payroll_json_object(to_jsonb(a.data));
 context_value:=jsonb_build_object('date_on',a.date_on,'date_off',a.date_off,'pruimalnyk',a.pruimalnyk,'client_id',a.client_id,'cars_id',a.cars_id);
 if md5(context_value::text) is distinct from p_context_checksum then raise exception 'Дати або відповідальні акта змінилися. Повторіть відновлення.' using errcode='40001';end if;
 if doc->'Заморожений'='true'::jsonb or (nullif(p_lock_owner,'') is not null and a.date_off is not null) then
  raise exception 'Стан акта не дозволяє цей запис зарплати' using errcode='55000';
 end if;
 -- A repeated request with the same unique revision is harmless.
 if doc->>'__act_revision'=p_next_revision and doc->'__payroll_pending'='false'::jsonb then
  return jsonb_build_object('act_id',p_act_id,'status','unchanged','revision',p_next_revision,'checksum',md5(doc::text),'cars_id',a.cars_id);
 end if;
 if md5(doc::text) is distinct from p_checksum or doc->>'__act_revision' is distinct from p_revision
  or doc->'__payroll_pending' is distinct from 'true'::jsonb then
  raise exception 'Акт змінився під час розрахунку. Нарахування не записано; повторіть операцію.' using errcode='40001';
 end if;
 if p_employees='[]'::jsonb and (coalesce(doc->'Роботи','[]'::jsonb)<>'[]'::jsonb or coalesce(doc->'Деталі','[]'::jsonb)<>'[]'::jsonb) then
  raise exception 'Не знайдено працівників для нарахування';
 end if;
 if exists(select 1 from jsonb_array_elements(coalesce(nullif(doc->'Деталі','null'::jsonb),'[]'::jsonb)) d
  where nullif(d->>'Деталь','') is not null and nullif(d->>'sclad_id','') is not null
   and not exists(select 1 from jsonb_array_elements(p_stock)s where s->>'id'=d->>'sclad_id')) then
  raise exception 'Не всі складські дані підтверджені. Повторіть розрахунок.' using errcode='40001';
 end if;
 -- The act row is already locked. Lock only the stock IDs used in this act,
 -- before employees, and compare the exact inputs used by the salary formulas.
 for stock_item in select value from jsonb_array_elements(p_stock) order by (value->>'id')::bigint loop
  if not exists(select 1 from jsonb_array_elements(coalesce(nullif(doc->'Деталі','null'::jsonb),'[]'::jsonb)) d
   where nullif(d->>'Деталь','') is not null and d->>'sclad_id'=stock_item->>'id') then raise exception 'Зайві складські дані у пакеті';end if;
  select * into stock_row from public.sclad where sclad_id=(stock_item->>'id')::bigint for update;
  if not found or jsonb_build_object('price',stock_row.price,'scladNomer',stock_row."scladNomer",'xto_zamovuv',stock_row.xto_zamovuv)
   is distinct from stock_item->'expected' then
   raise exception 'Ціна, склад або власник деталі змінилися. Повторіть розрахунок зарплати.' using errcode='40001';
  end if;
 end loop;
 -- Reject incomplete directory pagination or a changed employee set. This uses
 -- identifiers only and never sends unrelated payroll history to the client.
 if exists(select 1 from public.slyusars s where not exists(select 1 from jsonb_array_elements(p_employees)e where (e->>'id')::bigint=s.slyusar_id)) then
  raise exception 'Перелік працівників змінився або завантажений не повністю. Повторіть відновлення.' using errcode='40001';
 end if;
 for item in select value from jsonb_array_elements(p_employees) order by (value->>'id')::bigint loop
  expected:=item->'expected';desired:=item->'desired';
  if jsonb_typeof(expected) is distinct from 'array' or jsonb_typeof(desired) is distinct from 'array'
   or jsonb_array_length(expected)>1 or jsonb_array_length(desired)>1
   or jsonb_typeof(item->'settings') is distinct from 'object' then raise exception 'Некоректний фрагмент зарплати';end if;
  if exists(select 1 from jsonb_array_elements(expected||desired)e where e#>>'{value,Акт}' is distinct from p_act_id::text) then
   raise exception 'Пакет містить зарплату іншого акта';
  end if;
  select * into employee from public.slyusars where slyusar_id=(item->>'id')::bigint for update;
  if not found then raise exception 'Працівник відсутній або недоступний' using errcode='40001';end if;
  employee_data:=public.payroll_json_object(to_jsonb(employee.data));
  select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into settings from jsonb_each(employee_data)
   where key in ('Name','Доступ','Склад','ПроцентРоботи','ПроцентЗапчастин');
  if settings is distinct from item->'settings' then raise exception 'Налаштування працівника змінилися. Повторіть розрахунок.' using errcode='40001';end if;
  -- Use the same projection as the reader. An unrelated legacy entry without
  -- an act number must not block an unchanged employee's baseline check.
  select coalesce(jsonb_agg(jsonb_build_object('date',bucket.key,'value',entry.value) order by bucket.key,entry.ordinality),'[]'::jsonb) into actual
   from jsonb_each(coalesce(nullif(employee_data->'Історія','null'::jsonb),'{}'::jsonb)) bucket
   cross join lateral jsonb_array_elements(bucket.value) with ordinality entry(value,ordinality)
   where entry.value->>'Акт'=p_act_id::text;
  if actual is distinct from expected then raise exception 'Зарплату змінено паралельно. Повторіть розрахунок.' using errcode='40001';end if;
  perform public.assert_payroll_paid_preserved(expected,desired);
  if expected is distinct from desired then
   receipt:=public.write_payroll_fragments((item->>'id')::bigint,'accrual',jsonb_build_array(jsonb_build_object('act_id',p_act_id,'expected',expected,'desired',desired)));
   if receipt->>'status' not in ('updated','unchanged') then raise exception 'Немає підтвердження зарплати';end if;
   changed:=changed+1;
  end if;
 end loop;
 doc:=doc||jsonb_build_object('__payroll_pending',false,'__act_revision',p_next_revision);
 update public.acts set data=doc where act_id=p_act_id;
 if not found or doc is distinct from (select public.payroll_json_object(to_jsonb(data)) from public.acts where act_id=p_act_id) then
  raise exception 'Немає підтвердження завершення зарплати' using errcode='40001';
 end if;
 return jsonb_build_object('act_id',p_act_id,'status','updated','revision',p_next_revision,'checksum',md5(doc::text),'cars_id',a.cars_id,'employees_changed',changed);
end $$;

revoke all on function public.payroll_pending_acts(integer),public.payroll_recovery_context(integer),
 public.assert_payroll_paid_preserved(jsonb,jsonb),public.commit_act_payroll(integer,text,text,text,text,jsonb,text,jsonb) from public,anon;
grant execute on function public.payroll_pending_acts(integer),public.payroll_recovery_context(integer),
 public.assert_payroll_paid_preserved(jsonb,jsonb),public.commit_act_payroll(integer,text,text,text,text,jsonb,text,jsonb) to authenticated;
notify pgrst,'reload schema';



notify pgrst, 'reload schema';

-- SOURCE: 20261013120709_traffic_profit_date_compatibility.sql
-- Profit report operands only. No financial writes or new tables.
create or replace function public.traffic_profit_acts(
 p_mode text, p_from text, p_to text default null, p_offset integer default 0
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare
 result jsonb;
 date_column text;
 date_type text;
begin
 if p_mode not in ('open','close','paid') or p_mode is null then raise exception 'Invalid date mode'; end if;
 if p_offset is null or p_offset<0 then raise exception 'Invalid offset'; end if;
 -- Cast parameters to the actual column type, never the indexed column.
 -- Older projects use text; newer templates use timestamp for rosraxovano.
 date_column := case p_mode when 'open' then 'date_on' when 'close' then 'date_off' else 'rosraxovano' end;
 select case a.atttypid
   when 'timestamp'::regtype then 'timestamp'
   when 'timestamptz'::regtype then 'timestamptz'
   when 'date'::regtype then 'date'
   when 'text'::regtype then 'text'
   when 'varchar'::regtype then 'text'
 end into date_type
 from pg_attribute a
 where a.attrelid='public.acts'::regclass and a.attname=date_column
   and a.attnum>0 and not a.attisdropped;
 if date_type is null then
   raise exception 'Unsupported or missing date column public.acts.%', date_column;
 end if;
 execute format($query$
 with candidates as (
   select a.act_id,a.date_on,to_jsonb(a) row_data,public.sto_read_object_v1(to_jsonb(a.data)) body
   from public.acts a
   where ($1 is null or a.%1$I >= $1::%2$s)
     and ($2 is null or a.%1$I <= $2::%2$s)
   order by a.date_on desc,a.act_id desc limit 201 offset $3
 ), page as (select * from candidates order by date_on desc,act_id desc limit 200)
 select jsonb_build_object('items',coalesce((select jsonb_agg(
   (select jsonb_object_agg(key,value) from jsonb_each(p.row_data)
    where key=any(array['act_id','date_on','date_off','rosraxovano','xto_rozraxuvav','client_id','cars_id','avans','tupOplatu']))
   ||jsonb_build_object('data',(select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(p.body)
    where key=any(array['Прибуток за деталі','Прибуток за роботу','За деталі','За роботу','Знижка','Заморожений'])))
   order by p.date_on desc,p.act_id desc) from page p),'[]'::jsonb),
   'has_more',(select count(*)>200 from candidates))
 $query$, date_column, date_type) into result using p_from, p_to, p_offset;
 return result;
end $$;
revoke all on function public.traffic_profit_acts(text,text,text,integer) from public;
grant execute on function public.traffic_profit_acts(text,text,text,integer) to anon,authenticated;

notify pgrst, 'reload schema';




