-- BEGIN ACCOUNTING CURSOR PAGES 2026-10-15
-- SOURCE: 20261015154333_traffic_stock_accounting_page.sql
-- Bound every scan to the requested period using the raw date column.
-- Reuse an existing leading-column btree index, including a composite index.
do $$
declare date_column text; column_number smallint;
begin
 foreach date_column in array array['time_on','rosraxovano'] loop
  select attnum into column_number from pg_attribute
   where attrelid='public.sclad'::regclass and attname=date_column and attnum>0 and not attisdropped;
  if column_number is null then raise exception 'Missing stock date column: %',date_column;end if;
  if not exists(
   select 1 from pg_index i join pg_class c on c.oid=i.indexrelid join pg_am am on am.oid=c.relam
   where i.indrelid='public.sclad'::regclass and i.indisvalid and i.indisready
    and i.indpred is null and i.indnkeyatts>0 and i.indkey[0]=column_number and am.amname='btree'
  ) then
   execute format('create index %I on public.sclad (%I)','traffic_stock_accounting_'||date_column||'_idx',date_column);
  end if;
 end loop;
end $$;

-- One authoritative predicate for pages, totals, export and bulk settlement.
-- Existing tables and their RLS remain authoritative; no full JSON leaves SQL.
create or replace function public.traffic_stock_accounting_rows(p_filter jsonb)
returns table(row_data jsonb,sort_day text,amount numeric,remaining_amount numeric,eligible boolean)
language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare f text:=p_filter->>'from'; t text:=p_filter->>'to'; mode text:=coalesce(p_filter->>'dateMode','open');
 date_column text; date_type text;
begin
 if jsonb_typeof(p_filter) is distinct from 'object' or f is null or t is null
  or f!~'^\d{4}-\d{2}-\d{2}$' or t!~'^\d{4}-\d{2}-\d{2}$' or f::date>t::date
  or mode not in ('open','paid') or coalesce(p_filter->>'payment','2') not in ('0','1','2')
  or coalesce(p_filter->>'availability','4') not in ('0','1','2','3','4') then
  raise exception 'Invalid stock accounting filter';
 end if;
 if p_filter ? 'exclude' and (jsonb_typeof(p_filter->'exclude') is distinct from 'array' or jsonb_array_length(p_filter->'exclude')>2000) then
  raise exception 'Invalid excluded stock rows';
 end if;
 date_column:=case mode when 'paid' then 'rosraxovano' else 'time_on' end;
 select case a.atttypid when 'timestamp'::regtype then 'timestamp' when 'timestamptz'::regtype then 'timestamptz'
  when 'date'::regtype then 'date' when 'text'::regtype then 'text' when 'varchar'::regtype then 'text' end into date_type
 from pg_attribute a where a.attrelid='public.sclad'::regclass and a.attname=date_column and a.attnum>0 and not a.attisdropped;
 if date_type is null then raise exception 'Unsupported stock date column';end if;
 -- Cast bounds to the actual column type, never the indexed date column.
 return query execute format($query$
 with base as (
  select to_jsonb(s) d,public.traffic_shop_date(case $4 when 'paid' then s.rosraxovano::text else s.time_on::text end) AS day
  from public.sclad s where s.%1$I >= $2::%2$s and s.%1$I < $3::%2$s
 ), prepared as (
  select d,day,coalesce(nullif(d->>'kilkist_on',''),'0')::numeric quantity,
   coalesce(nullif(d->>'kilkist_off',''),'0')::numeric used,coalesce(nullif(d->>'price',''),'0')::numeric price,
   nullif(d->>'rosraxovano','') is not null paid,nullif(d->>'povernennya','') is not null returned
  from base where day>=$2 and day<$3
 )
 select (select jsonb_object_agg(key,value) from jsonb_each(d) where key=any(array[
   'sclad_id','time_on','shops','rahunok','akt','name','part_number','kilkist_on','kilkist_off','price',
   'rosraxovano','povernennya','xto_povernyv','scladNomer','xto_zamovuv']))||jsonb_build_object('requester_name',public.traffic_json_object(st.data::jsonb)->>'Name'),day,
   quantity*price,greatest(quantity-used,0)*price,not paid and not returned
 from prepared left join public.slyusars st on st.slyusar_id=case when coalesce(d->>'xto_zamovuv','')~'^[1-9][0-9]*$' then (d->>'xto_zamovuv')::bigint end
 where (nullif($1->>'shop','') is null or lower(btrim(coalesce(d->>'shops','')))=lower(btrim($1->>'shop')))
  and (nullif($1->>'bill','') is null or strpos(lower(coalesce(d->>'rahunok','')),lower($1->>'bill'))>0)
  and (nullif($1->>'item','') is null or strpos(lower(coalesce(d->>'name','')),lower($1->>'item'))>0)
  and (nullif($1->>'catalog','') is null or strpos(lower(coalesce(d->>'part_number','')),lower($1->>'catalog'))>0
   or (regexp_replace(lower(normalize($1->>'catalog',NFKC)),'[^[:alnum:]]','','g')<>'' and
    strpos(regexp_replace(lower(normalize(coalesce(d->>'part_number',''),NFKC)),'[^[:alnum:]]','','g'),
     regexp_replace(lower(normalize($1->>'catalog',NFKC)),'[^[:alnum:]]','','g'))>0))
  and (coalesce($1->>'payment','2')='2' or paid=($1->>'payment'='0'))
  and (coalesce($1->>'availability','4')='4'
    or $1->>'availability'='0' and quantity-used>0
    or $1->>'availability'='1' and quantity-used=0
    or $1->>'availability'='2' and quantity-used<0
    or $1->>'availability'='3' and returned)
  and (nullif($1->>'warehouse','') is null or d->>'scladNomer'=$1->>'warehouse')
  and (nullif($1->>'requester','') is null or d->>'xto_zamovuv'=$1->>'requester')
  and not exists(select 1 from jsonb_array_elements_text(coalesce($1->'exclude','[]')) x where x=d->>'sclad_id')
 $query$,date_column,date_type) using p_filter,f,(t::date+1)::text,mode;
end $$;

create or replace function public.traffic_stock_accounting_page(
 p_filter jsonb,p_cursor jsonb default null,p_limit integer default 40,
 p_include_summary boolean default true,p_expected_revision text default null
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb; facets jsonb; filter_hash text:=md5(p_filter::text);
begin
 if p_limit is null or p_limit<1 or p_limit>200 or p_include_summary is null then raise exception 'Invalid stock accounting page';end if;
 if p_cursor is not null and (jsonb_typeof(p_cursor) is distinct from 'object' or p_cursor->>'filter' is distinct from filter_hash
   or coalesce(p_cursor->>'id','')!~'^[1-9][0-9]*$' or coalesce(p_cursor->>'day','')!~'^\d{4}-\d{2}-\d{2}$'
   or p_expected_revision is null) then raise exception 'Invalid stock accounting cursor';end if;
 with filtered as materialized (select * from public.traffic_stock_accounting_rows(p_filter)),
 stamp as (select md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint),'')) version from filtered),
 candidates as (
  select * from filtered where p_cursor is null or (sort_day,(row_data->>'sclad_id')::bigint)<(p_cursor->>'day',(p_cursor->>'id')::bigint)
  order by sort_day desc,(row_data->>'sclad_id')::bigint desc limit p_limit+1
 ), page as (select * from candidates order by sort_day desc,(row_data->>'sclad_id')::bigint desc limit p_limit)
 select jsonb_build_object('items',coalesce((select jsonb_agg(row_data
   order by sort_day desc,(row_data->>'sclad_id')::bigint desc) from page),'[]'),
  'has_more',(select count(*)>p_limit from candidates),
  'next_cursor',(select jsonb_build_object('day',sort_day,'id',row_data->'sclad_id','filter',filter_hash)
   from page order by sort_day,(row_data->>'sclad_id')::bigint limit 1),'revision',(select version from stamp))
  ||case when p_include_summary then jsonb_build_object('summary',
   (select jsonb_build_object('totalCount',count(*),'totalAmount',coalesce(sum(amount),0),
    'remainingAmount',coalesce(sum(remaining_amount),0),'payableCount',count(*) filter(where eligible),
    'payableAmount',coalesce(sum(amount) filter(where eligible),0),
    'payableBaseline',md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint) filter(where eligible),''))) from filtered)) else '{}'::jsonb end
 into result;
 if p_expected_revision is not null and result->>'revision' is distinct from p_expected_revision then raise exception 'ACCOUNTING_REPORT_STALE';end if;
 if p_include_summary then
  with base as (select row_data from public.traffic_stock_accounting_rows(jsonb_build_object(
   'from',p_filter->'from','to',p_filter->'to','dateMode',p_filter->'dateMode','exclude',coalesce(p_filter->'exclude','[]')))),
  ids as (select distinct (row_data->>'xto_zamovuv')::bigint id from base where coalesce(row_data->>'xto_zamovuv','')~'^[1-9][0-9]*$')
  select jsonb_build_object('warehouses',coalesce((select jsonb_agg(id order by id) from (select distinct (row_data->>'scladNomer')::integer id
   from base where coalesce(row_data->>'scladNomer','')~'^[1-9][0-9]*$') w),'[]'),
   'requesters',coalesce((select jsonb_agg(jsonb_build_object('id',ids.id,'name',coalesce(public.traffic_json_object(s.data::jsonb)->>'Name','ID: '||ids.id)) order by ids.id)
    from ids left join public.slyusars s on s.slyusar_id=ids.id),'[]')) into facets;
  result:=result||jsonb_build_object('facets',facets);
 end if;
 return result;
end $$;

-- Only names, scoped to period/shop, requested on focus/typing. No row/history download.
create or replace function public.traffic_stock_accounting_suggest(p_filter jsonb,p_field text,p_query text default '',p_item_exact text default null,p_after text default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare field_name text; result jsonb;
begin
 field_name:=case p_field when 'bill' then 'rahunok' when 'item' then 'name' when 'catalog' then 'part_number' end;
 if field_name is null or length(coalesce(p_query,''))>200 then raise exception 'Invalid stock suggestion';end if;
 with names as (
  select distinct btrim(row_data->>field_name) value from public.traffic_stock_accounting_rows(jsonb_build_object(
   'from',p_filter->'from','to',p_filter->'to','dateMode',p_filter->'dateMode','shop',p_filter->'shop'))
  where nullif(btrim(row_data->>field_name),'') is not null
   and (p_item_exact is null or btrim(row_data->>'name')=p_item_exact)
 ), matches as (
  select value from names where (p_after is null or value>p_after) and
   (coalesce(p_query,'')='' or strpos(lower(value),lower(p_query))>0 or p_field='catalog' and
    regexp_replace(lower(normalize(p_query,NFKC)),'[^[:alnum:]]','','g')<>'' and
    strpos(regexp_replace(lower(normalize(value,NFKC)),'[^[:alnum:]]','','g'),regexp_replace(lower(normalize(p_query,NFKC)),'[^[:alnum:]]','','g'))>0)
  order by value limit 51
 ) select jsonb_build_object('items',coalesce((select jsonb_agg(value order by value) from (select value from matches order by value limit 50) visible),'[]'),
   'has_more',(select count(*)>50 from matches)) into result;
 return result;
end $$;

-- A retry after commit is rejected as stale; it cannot settle any row twice.
-- Fix the candidate IDs before locking; never reevaluate a broader UPDATE filter.
create or replace function public.traffic_stock_accounting_pay(p_filter jsonb,p_expected_revision text,p_baseline text,p_paid_at text)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare ids bigint[]; locked_ids bigint[]; baseline text; version text; n integer; converted public.sclad%rowtype;
begin
 if nullif(p_expected_revision,'') is null or coalesce(p_baseline,'')!~'^[0-9a-f]{32}$'
  or coalesce(p_paid_at,'')!~'^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid stock settlement';end if;
 select md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint),'')) into version from public.traffic_stock_accounting_rows(p_filter);
 if version is distinct from p_expected_revision then raise exception 'ACCOUNTING_REPORT_STALE';end if;
 select array_agg((row_data->>'sclad_id')::bigint order by (row_data->>'sclad_id')::bigint) into ids
  from public.traffic_stock_accounting_rows(p_filter) where eligible;
 if coalesce(cardinality(ids),0)=0 then raise exception 'ACCOUNTING_REPORT_STALE';end if;
 select array_agg(sclad_id order by sclad_id) into locked_ids from
  (select sclad_id from public.sclad where sclad_id=any(ids) order by sclad_id for update) locked;
 if locked_ids is distinct from ids then raise exception 'ACCOUNTING_REPORT_STALE';end if;
 -- Re-read after acquiring the locks: concurrent edits/deletions/settlements fail.
 select md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint),'')) into baseline
  from public.traffic_stock_accounting_rows(p_filter) where eligible;
 select md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint),'')) into version from public.traffic_stock_accounting_rows(p_filter);
 if baseline is distinct from p_baseline or version is distinct from p_expected_revision then
  raise exception 'ACCOUNTING_REPORT_STALE';end if;
 converted:=jsonb_populate_record(null::public.sclad,jsonb_build_object('rosraxovano',p_paid_at));
 update public.sclad set rosraxovano=converted.rosraxovano where sclad_id=any(ids) and rosraxovano is null and povernennya is null;
 get diagnostics n=row_count;
 if n<>cardinality(ids) then raise exception 'ACCOUNTING_REPORT_STALE';end if;
 return jsonb_build_object('updatedCount',n);
end $$;

revoke all on function public.traffic_stock_accounting_rows(jsonb),public.traffic_stock_accounting_page(jsonb,jsonb,integer,boolean,text),public.traffic_stock_accounting_suggest(jsonb,text,text,text,text),public.traffic_stock_accounting_pay(jsonb,text,text,text) from public;
grant execute on function public.traffic_stock_accounting_rows(jsonb),public.traffic_stock_accounting_page(jsonb,jsonb,integer,boolean,text),public.traffic_stock_accounting_suggest(jsonb,text,text,text,text),public.traffic_stock_accounting_pay(jsonb,text,text,text) to anon,authenticated;

-- SOURCE: 20261015154335_traffic_profit_accounting_page.sql
-- Exact profit/cash totals with cursor pages and a fingerprint of the filtered result.
-- All queries and writes preserve caller RLS. No client/history/act documents leave the RPC.

create or replace function public.traffic_profit_accounting_number(p_value jsonb)
returns numeric language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare value text; radix integer; digit integer; result numeric:=0; i integer;
begin
 if p_value is null or p_value='null'::jsonb then return 0; end if;
 if p_value='true'::jsonb then return 1; end if;
 if p_value='false'::jsonb then return 0; end if;
 if jsonb_typeof(p_value) not in ('number','string') then return 0; end if;
 value:=btrim(p_value#>>'{}',E' \t\r\n'||chr(160));
 if value='' then return 0; end if;
 if value ~* '^0(x[0-9a-f]+|b[01]+|o[0-7]+)$' then
  radix:=case lower(substr(value,2,1)) when 'x' then 16 when 'b' then 2 else 8 end;
  if length(value)>1026 then raise exception 'Accounting number is outside the JavaScript range'; end if;
  for i in 3..length(value) loop
   digit:=strpos('0123456789abcdef',lower(substr(value,i,1)))-1;
   result:=result*radix+digit;
  end loop;
  return result;
 end if;
 if value !~ '^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$' then return 0; end if;
 begin return value::numeric; exception when numeric_value_out_of_range then return 0; end;
end $$;

-- Decode the IEEE-754 input before rounding. numeric(double::text) would lose
-- the binary half-cent behavior of Number(value.toFixed(2)) / Math.round(value).
create or replace function public.traffic_profit_accounting_round(p_value double precision,p_digits integer default 2,p_math_round boolean default false)
returns numeric language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare bytes bytea:=float8send(p_value); sign integer; exponent integer; mantissa numeric; numerator numeric; denominator numeric:=1; factor numeric; i integer;
begin
 if p_value is null then return 0; end if;
 if p_digits not in (0,2) then raise exception 'Unsupported accounting precision'; end if;
 sign:=case when get_byte(bytes,0)>=128 then -1 else 1 end;
 exponent:=((get_byte(bytes,0)&127)*16)+(get_byte(bytes,1)>>4);
 if exponent=2047 then raise exception 'Non-finite accounting number'; end if;
 mantissa:=get_byte(bytes,1)&15;
 for i in 2..7 loop mantissa:=mantissa*256+get_byte(bytes,i); end loop;
 if exponent=0 then exponent:=-1074; else mantissa:=mantissa+4503599627370496; exponent:=exponent-1075; end if;
 factor:=case when p_digits=2 then 100 else 1 end;
 numerator:=mantissa*factor;
 if exponent>=0 then numerator:=numerator*power(2::numeric,exponent); else denominator:=power(2::numeric,-exponent); end if;
 return sign*div(2*numerator+denominator-case when p_math_round and sign<0 then 1 else 0 end,2*denominator)/factor;
end $$;

create or replace function public.traffic_profit_accounting_stamp(p_value text)
returns text language plpgsql stable security invoker set search_path=pg_catalog as $$
begin
 if nullif(btrim(p_value),'') is null then return null; end if;
 if p_value ~ '(Z|[+-][0-9]{2}(:?[0-9]{2})?)$' and p_value ~ '[T ]' then
  return to_char(p_value::timestamptz at time zone 'Europe/Kyiv','YYYY-MM-DD"T"HH24:MI:SS.US');
 end if;
 return to_char(p_value::timestamp,'YYYY-MM-DD"T"HH24:MI:SS.US');
exception when invalid_datetime_format or datetime_field_overflow then return null;
end $$;

create or replace function public.traffic_profit_accounting_day(p_value text)
returns text language plpgsql stable security invoker set search_path=pg_catalog as $$
begin
 if nullif(btrim(p_value),'') is null then return null; end if;
 if p_value ~ '(Z|[+-][0-9]{2}(:?[0-9]{2})?)$' and p_value ~ '[T ]' then
  return to_char(p_value::timestamptz at time zone 'Europe/Kyiv','YYYY-MM-DD');
 end if;
 return to_char(p_value::timestamp,'YYYY-MM-DD');
exception when invalid_datetime_format or datetime_field_overflow then return null;
end $$;

-- One reusable financial relation for page, summary and payment eligibility.
create or replace function public.traffic_profit_accounting_rows(p_filter jsonb,p_cursor jsonb default null)
returns setof jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare mode text:=coalesce(p_filter->>'mode','open'); from_day date; to_day date;
 act_column text; expense_column text; act_type text; expense_type text; act_predicate text; expense_predicate text;
begin
 if jsonb_typeof(p_filter) is distinct from 'object' or mode not in ('open','close','paid') then raise exception 'Invalid profit filter'; end if;
 if coalesce(p_filter->>'from','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_filter->>'to','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Select a valid profit date range'; end if;
 from_day:=(p_filter->>'from')::date; to_day:=(p_filter->>'to')::date;
 if from_day>to_day then raise exception 'Invalid profit date range'; end if;
 if coalesce(p_filter->>'payment','2') not in ('0','1','2') or coalesce(p_filter->>'type','2') not in ('0','1','2')
  or coalesce(p_filter->>'status','2') not in ('0','1','2') or coalesce(p_filter->>'discount','2') not in ('0','1','2') then raise exception 'Invalid profit switches'; end if;
 if jsonb_typeof(coalesce(p_filter->'exclude_ids','[]'::jsonb))<>'array' then raise exception 'Invalid hidden profit IDs'; end if;
 if exists(select 1 from jsonb_array_elements_text(coalesce(p_filter->'exclude_ids','[]'::jsonb)) id where id !~ '^-?[0-9]+$') then raise exception 'Invalid hidden profit IDs'; end if;
 if p_cursor is not null and (jsonb_typeof(p_cursor) is distinct from 'object' or coalesce(p_cursor->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_cursor->>'id','') !~ '^-?[0-9]+$') then raise exception 'Invalid profit cursor'; end if;
 act_column:=case mode when 'open' then 'date_on' when 'close' then 'date_off' else 'rosraxovano' end;
 expense_column:=case mode when 'paid' then 'dataOff' else 'dataOnn' end;
 select case atttypid when 'timestamp'::regtype then 'timestamp' when 'timestamptz'::regtype then 'timestamptz' when 'date'::regtype then 'date' when 'text'::regtype then 'text' when 'varchar'::regtype then 'text' end into act_type
  from pg_attribute where attrelid='public.acts'::regclass and attname=act_column and attnum>0 and not attisdropped;
 select case atttypid when 'timestamp'::regtype then 'timestamp' when 'timestamptz'::regtype then 'timestamptz' when 'date'::regtype then 'date' when 'text'::regtype then 'text' when 'varchar'::regtype then 'text' end into expense_type
  from pg_attribute where attrelid='public.vutratu'::regclass and attname=expense_column and attnum>0 and not attisdropped;
 if act_type is null or expense_type is null then raise exception 'Unsupported accounting date column'; end if;
 act_predicate:=case when act_type='timestamptz' then format('a.%I >= ($1::timestamp at time zone ''Europe/Kyiv'') and a.%I < ($2::timestamp at time zone ''Europe/Kyiv'')',act_column,act_column)
  else format('a.%I >= $1::%s and a.%I < $2::%s',act_column,act_type,act_column,act_type) end;
 expense_predicate:=case when expense_type='timestamptz' then format('v.%I >= ($1::timestamp at time zone ''Europe/Kyiv'') and v.%I < ($2::timestamp at time zone ''Europe/Kyiv'')',expense_column,expense_column)
  else format('v.%I >= $1::%s and v.%I < $2::%s',expense_column,expense_type,expense_column,expense_type) end;
 return query execute format($query$
 with acts as materialized (
  select a.act_id,a.client_id,a.cars_id,a.date_on,a.date_off,a.rosraxovano,a.xto_rozraxuvav,a.avans,a."tupOplatu",
   public.sto_read_object_v1(to_jsonb(a.data)) d,public.traffic_profit_accounting_day(a.date_on::text) AS day
  from public.acts a where %s
 ), visible_acts as materialized (
  select * from acts where d->'Заморожений' is distinct from 'true'::jsonb
   and ($4 is null or (day,-act_id)<($4->>'date',($4->>'id')::bigint))
 ), staff as materialized (
  select s.slyusar_id,public.sto_read_object_v1(to_jsonb(s.data)) d from public.slyusars s
  where exists(select 1 from visible_acts)
 ), salary_records as (
  select s.slyusar_id,h.key day_key,e.ord,public.traffic_profit_accounting_number(e.r->'Акт')::double precision act_id,
   public.traffic_profit_accounting_number(e.r->'ЗарплатаЗапчастин')::double precision parts,
   public.traffic_profit_accounting_number(e.r->'ЗарплатаРоботи')::double precision work,
   public.traffic_profit_accounting_number(e.r->'ЗарплатаЗапчастистів')::double precision buyer
  from staff s cross join lateral jsonb_each(case when jsonb_typeof(s.d->'Історія')='object' then s.d->'Історія' else '{}'::jsonb end) h
   cross join lateral jsonb_array_elements(case when jsonb_typeof(h.value)='array' then h.value else '[]'::jsonb end) with ordinality e(r,ord)
  where s.d->>'Доступ'='Приймальник'
 ), salaries as (
  select s.act_id,sum(s.parts order by s.slyusar_id,s.day_key,s.ord) parts,sum(s.work order by s.slyusar_id,s.day_key,s.ord) work,sum(s.buyer order by s.slyusar_id,s.day_key,s.ord) buyer from salary_records s
   join visible_acts a on a.act_id=s.act_id where s.parts>0 or s.work>0 or s.buyer>0 group by s.act_id
 ), operands as (
  select a.*,public.traffic_profit_accounting_round(public.traffic_profit_accounting_number(d->'Прибуток за деталі')::double precision-coalesce(s.parts,0)-coalesce(s.buyer,0)) parts_profit,
   public.traffic_profit_accounting_round(public.traffic_profit_accounting_number(d->'Прибуток за роботу')::double precision-coalesce(s.work,0)) work_profit,
   public.traffic_profit_accounting_number(d->'За деталі')::double precision full_parts,public.traffic_profit_accounting_number(d->'За роботу')::double precision full_work,
   public.traffic_profit_accounting_number(d->'Знижка')::double precision discount_percent
  from visible_acts a left join salaries s on s.act_id=a.act_id
 ), act_rows as (
  select jsonb_build_object('id',-act_id,'date',day,'sortStamp',public.traffic_profit_accounting_stamp(date_on::text),'paymentDate',public.traffic_profit_accounting_day(date_off::text),'rosraxovanoDate',rosraxovano,
   'category','Прибуток','actNumber',act_id,'description','-','notes','-','amount',parts_profit::double precision+work_profit::double precision,'detailsAmount',parts_profit,'workAmount',work_profit,
   'paymentMethod',coalesce(to_jsonb(avans),'0'::jsonb),'isPaid',nullif(rosraxovano::text,'') is not null,'createdBy','Система',
   'clientId',client_id,'carId',cars_id,'xto_rozraxuvav',xto_rozraxuvav,'fullDetailsAmount',full_parts,'fullWorkAmount',full_work,'fullAmount',full_parts+full_work,
   'tupOplatu',"tupOplatu",'discount',discount_percent,'discountAmount',case when discount_percent>0 then public.traffic_profit_accounting_round((full_parts+full_work)*discount_percent/100,0,true) else 0 end) r
  from operands
 ), expenses as (
  select jsonb_build_object('id',v.vutratu_id,'date',public.traffic_profit_accounting_day(v."dataOnn"::text),'sortStamp',public.traffic_profit_accounting_stamp(v."dataOnn"::text),'paymentDate',public.traffic_profit_accounting_day(v."dataOff"::text),
   'rosraxovanoDate',v."dataOff",'category',coalesce(v.kategoria,''),'description',v.opys_vytraty,'amount',v.suma,
   'paymentMethod',coalesce(v.sposob_oplaty,''),'notes',coalesce(v.prymitky,''),'isPaid',nullif(v."dataOff"::text,'') is not null,'createdBy',v.xto_zapusav,'xto_rozraxuvav',v.xto_zapusav) r
  from public.vutratu v where v.suma<0 and v.act is null and %s
   and ($4 is null or (public.traffic_profit_accounting_day(v."dataOnn"::text),v.vutratu_id)<($4->>'date',($4->>'id')::bigint))
 ), combined as (select r from act_rows union all select r from expenses)
 select r from combined where
  not exists(select 1 from jsonb_array_elements_text(coalesce($3->'exclude_ids','[]'::jsonb)) hidden where hidden::bigint=(r->>'id')::bigint)
  and
  (nullif($3->>'category','') is null or r->>'category'=$3->>'category')
  and (nullif($3->>'paymentMethod','') is null or case when r->>'category'='Прибуток' then position($3->>'paymentMethod' in coalesce(r->>'tupOplatu',''))>0 else r->>'paymentMethod'=$3->>'paymentMethod' end)
  and (coalesce($3->>'payment','2')='2' or (r->>'isPaid')::boolean=(($3->>'payment')='0'))
  and (coalesce($3->>'type','2')='2' or ((r->>'amount')::numeric>=0)=(($3->>'type')='0'))
  and (r->>'category'<>'Прибуток' or coalesce($3->>'status','2')='2' or (nullif(r->>'paymentDate','') is not null)=(($3->>'status')='0'))
  and (coalesce($3->>'discount','2')='2' or (($3->>'discount')='1' and coalesce((r->>'discountAmount')::numeric,0)>0)
   or (($3->>'discount')='0' and ((r->>'amount')::numeric<0 or coalesce((r->>'discountAmount')::numeric,0)<=0)))
 $query$,act_predicate,expense_predicate) using from_day::text,(to_day+1)::text,p_filter,p_cursor;
end $$;

create or replace function public.traffic_profit_accounting_page(p_filter jsonb,p_cursor jsonb default null,p_limit integer default 30,p_summary boolean default true,p_expected_revision text default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare revision text; result jsonb;
begin
 if p_limit is null or p_limit<1 or p_limit>100 then raise exception 'Invalid profit page size'; end if;
 if p_cursor is not null and (coalesce(p_cursor->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_cursor->>'id','') !~ '^-?[0-9]+$' or nullif(p_cursor->>'stamp','') is null) then raise exception 'Invalid profit cursor'; end if;
 if p_cursor is not null and p_expected_revision is null then raise exception 'A profit cursor requires its revision'; end if;
 if p_summary and p_cursor is not null then raise exception 'Summary is only available on the first page'; end if;
 with report as materialized (select r from public.traffic_profit_accounting_rows(p_filter) r),
 fingerprint as (select md5(coalesce(string_agg(md5(r::text),',' order by (r->>'id')::bigint),'')) value from report),
 candidates as (select r from report where p_cursor is null or (r->>'date',(r->>'id')::bigint>0,r->>'sortStamp',abs((r->>'id')::bigint))<(p_cursor->>'date',(p_cursor->>'id')::bigint>0,p_cursor->>'stamp',abs((p_cursor->>'id')::bigint))
  order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc limit p_limit+1),
 page as (select r from candidates order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc limit p_limit),
 labelled as (
  select p.r || case when coalesce((p_filter->>'include_client')::boolean,false) and p.r->>'category'='Прибуток' and c.d is not null then
   jsonb_build_object('clientLabel',jsonb_build_object('ПІБ',c.d->'ПІБ','Телефон',c.d->'Телефон','Джерело',c.d->'Джерело','Додаткові',c.d->'Додаткові')) else '{}'::jsonb end
   || case when coalesce((p_filter->>'include_car')::boolean,false) and p.r->>'category'='Прибуток' and a.d is not null then
   jsonb_build_object('carLabel',jsonb_build_object('Авто',a.d->'Авто','Номер авто',a.d->'Номер авто','Обʼєм',a.d->'Обʼєм','КодДВЗ',a.d->'КодДВЗ','Пальне',a.d->'Пальне')) else '{}'::jsonb end r
  from page p left join lateral (select public.sto_read_object_v1(to_jsonb(data)) d from public.clients where client_id=(p.r->>'clientId')::bigint and coalesce((p_filter->>'include_client')::boolean,false)) c on true
   left join lateral (select public.sto_read_object_v1(to_jsonb(data)) d from public.cars where cars_id=(p.r->>'carId')::bigint and coalesce((p_filter->>'include_car')::boolean,false)) a on true
 ), totals as (
  select count(*) count,coalesce(sum((r->>'amount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc),0) amount,
   coalesce(sum((r->>'amount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'<>'Прибуток'),0) negative,
   coalesce(sum(greatest(public.traffic_profit_accounting_number(r->'paymentMethod')::double precision,0) order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is null),0) advances,
   coalesce(sum((r->>'detailsAmount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "detailsProfit",
   coalesce(sum((r->>'workAmount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "workProfit",
   coalesce(sum((r->>'fullDetailsAmount')::double precision-case when (r->>'discountAmount')::double precision>0 and (r->>'fullAmount')::double precision>0 then (r->>'fullDetailsAmount')::double precision*((r->>'discountAmount')::double precision/(r->>'fullAmount')::double precision) else 0::double precision end order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "cashDetails",
   coalesce(sum((r->>'fullWorkAmount')::double precision-case when (r->>'discountAmount')::double precision>0 and (r->>'fullAmount')::double precision>0 then (r->>'fullWorkAmount')::double precision*((r->>'discountAmount')::double precision/(r->>'fullAmount')::double precision) else 0::double precision end order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "cashWork",
   coalesce(sum((r->>'discountAmount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) discount,
   count(*) filter(where not (r->>'isPaid')::boolean) "eligibleCount",
   coalesce(sum((r->>'amount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where not (r->>'isPaid')::boolean),0) "eligibleAmount",
   md5(coalesce(string_agg(r::text,'|' order by (r->>'id')::bigint) filter(where not (r->>'isPaid')::boolean),'')) "eligibleBaseline"
  from report where p_summary
 )
 select jsonb_build_object('formula_version',1,'revision',(select value from fingerprint),'rows',coalesce((select jsonb_agg(r order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) from labelled),'[]'::jsonb),
  'has_more',(select count(*)>p_limit from candidates),'next_cursor',(select jsonb_build_object('date',r->>'date','id',(r->>'id')::bigint,'stamp',r->>'sortStamp') from page order by r->>'date',((r->>'id')::bigint>0),r->>'sortStamp',abs((r->>'id')::bigint) limit 1))
  ||case when p_summary then jsonb_build_object('summary',(select to_jsonb(t) from totals t)) else '{}'::jsonb end into result;
 revision:=result->>'revision';
 if p_expected_revision is not null and p_expected_revision is distinct from revision then raise exception using errcode='P0001',message='ACCOUNTING_REPORT_STALE'; end if;
 return result;
end $$;

create or replace function public.traffic_profit_accounting_pay(p_filter jsonb,p_expected_revision text,p_baseline text,p_actor text)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare captured bigint[]; baseline text; current_revision text; updated_count bigint:=0; changed bigint; stamp timestamp:=clock_timestamp() at time zone 'Europe/Kyiv';
begin
 if p_expected_revision is null or p_baseline is null or nullif(btrim(p_actor),'') is null then raise exception 'Missing payment baseline'; end if;
 select md5(coalesce(string_agg(md5(r::text),',' order by (r->>'id')::bigint),'')),
  coalesce(array_agg((r->>'id')::bigint order by (r->>'id')::bigint) filter(where not (r->>'isPaid')::boolean),'{}'::bigint[]),
  md5(coalesce(string_agg(r::text,'|' order by (r->>'id')::bigint) filter(where not (r->>'isPaid')::boolean),'')) into current_revision,captured,baseline
  from public.traffic_profit_accounting_rows(p_filter) r;
 if current_revision is distinct from p_expected_revision or baseline is distinct from p_baseline then raise exception using errcode='P0001',message='ACCOUNTING_REPORT_STALE'; end if;
 perform act_id from public.acts where -act_id=any(captured) order by act_id for update;
 perform vutratu_id from public.vutratu where vutratu_id=any(captured) order by vutratu_id for update;
 -- The second snapshot validates the confirmed financial inputs after row locks.
 -- Only captured IDs are paid; unrelated/new rows are never added by UPDATE.
 select md5(coalesce(string_agg(md5(r::text),',' order by (r->>'id')::bigint),'')),
  md5(coalesce(string_agg(r::text,'|' order by (r->>'id')::bigint) filter(where not (r->>'isPaid')::boolean),'')) into current_revision,baseline
  from public.traffic_profit_accounting_rows(p_filter) r;
 if current_revision is distinct from p_expected_revision or baseline is distinct from p_baseline then raise exception using errcode='P0001',message='ACCOUNTING_REPORT_STALE'; end if;
 update public.acts set rosraxovano=stamp,xto_rozraxuvav=p_actor where -act_id=any(captured) and nullif(rosraxovano::text,'') is null;
 get diagnostics changed=row_count; updated_count:=updated_count+changed;
 update public.vutratu set "dataOff"=stamp where vutratu_id=any(captured) and nullif("dataOff"::text,'') is null;
 get diagnostics changed=row_count; updated_count:=updated_count+changed;
 if updated_count<>cardinality(captured) then raise exception using errcode='P0001',message='ACCOUNTING_REPORT_STALE'; end if;
 return jsonb_build_object('updated_count',updated_count);
end $$;

revoke all on function public.traffic_profit_accounting_round(double precision,integer,boolean),public.traffic_profit_accounting_stamp(text),public.traffic_profit_accounting_number(jsonb),public.traffic_profit_accounting_day(text),public.traffic_profit_accounting_rows(jsonb,jsonb),public.traffic_profit_accounting_page(jsonb,jsonb,integer,boolean,text),public.traffic_profit_accounting_pay(jsonb,text,text,text) from public;
grant execute on function public.traffic_profit_accounting_round(double precision,integer,boolean),public.traffic_profit_accounting_stamp(text),public.traffic_profit_accounting_number(jsonb),public.traffic_profit_accounting_day(text),public.traffic_profit_accounting_rows(jsonb,jsonb),public.traffic_profit_accounting_page(jsonb,jsonb,integer,boolean,text),public.traffic_profit_accounting_pay(jsonb,text,text,text) to anon,authenticated;
-- Avoid duplicate indexes when an existing valid btree already leads with the date.
do $$
declare target record; relation regclass; number smallint;
begin
 for target in select * from (values ('acts','date_on'),('acts','date_off'),('acts','rosraxovano'),('vutratu','dataOnn'),('vutratu','dataOff')) x(table_name,column_name) loop
  relation:=to_regclass(format('public.%I',target.table_name));
  select attnum into number from pg_attribute where attrelid=relation and attname=target.column_name and attnum>0 and not attisdropped;
  if number is not null and not exists(select 1 from pg_index i join pg_class c on c.oid=i.indexrelid join pg_am a on a.oid=c.relam
   where i.indrelid=relation and i.indisvalid and i.indisready and i.indpred is null and i.indkey[0]=number and a.amname='btree') then
   execute format('create index %I on public.%I (%I)', 'traffic_profit_'||target.table_name||'_'||lower(target.column_name)||'_idx',target.table_name,target.column_name);
  end if;
 end loop;
end $$;
-- END ACCOUNTING CURSOR PAGES 2026-10-15

notify pgrst, 'reload schema';

-- BEGIN PLANNER CLIENT OPTIONS 2026-10-15
-- SOURCE: 20261015180716_traffic_planner_client_options.sql
-- Planner suggestions: only client IDs, names and phone fields leave the database.
-- Requires sto_read_object_v1 from the existing traffic optimization package.

create or replace function public.traffic_planner_client_options(
  p_kind text,
  p_query text default '',
  p_after bigint default null,
  p_client bigint default null
) returns jsonb
language plpgsql stable security invoker
set search_path = pg_catalog, public
as $$
declare
  v_query text := lower(btrim(coalesce(p_query, '')));
  v_digits text := regexp_replace(coalesce(p_query, ''), '[^0-9]', '', 'g');
  v_result jsonb;
begin
  if p_kind is null or p_kind not in ('client', 'phone') then
    raise exception 'Unsupported planner client field' using errcode = '22023';
  end if;

  if p_kind = 'phone' and v_digits <> '' then
    v_query := v_digits;
  end if;

  -- Empty/short global searches must never enumerate the whole directory.
  -- An explicit client ID can still be restored without entering its name.
  if p_client is null and char_length(v_query) < 3 then
    return jsonb_build_object('items', '[]'::jsonb, 'has_more', false, 'next_cursor', null);
  end if;

  with candidates as (
    select c.client_id as id, public.sto_read_object_v1(c.data::jsonb) as d
    from public.clients c
    where (p_after is null or c.client_id > p_after)
      and (p_client is null or c.client_id = p_client)
  ), named as (
    select id, d, coalesce(d->>'ПІБ', '') as full_name
    from candidates
    where btrim(coalesce(d->>'ПІБ', '')) <> ''
      and (p_kind = 'phone' or strpos(lower(coalesce(d->>'ПІБ', '')), v_query) > 0)
  ), contacts as (
    select n.id, n.full_name, contact.phones
    from named n
    cross join lateral (
      select coalesce(array_agg(btrim(e.value) order by
        case when lower(e.key) = 'телефон' then 0 else 1 end, e.key), '{}'::text[]) as phones
      from jsonb_each_text(n.d) as e(key, value)
      where e.key ilike '%телефон%'
        and jsonb_typeof(n.d->e.key) = 'string'
        and btrim(e.value) <> ''
    ) as contact
  ), matched as (
    select c.id, c.full_name, c.phones,
      case when p_kind = 'phone' then (
        select p.value
        from unnest(c.phones) with ordinality as p(value, phone_order)
        where strpos(lower(p.value), v_query) > 0
          or (v_digits <> '' and strpos(regexp_replace(p.value, '[^0-9]', '', 'g'), v_digits) > 0)
        order by p.phone_order limit 1
      ) else c.phones[1] end as phone
    from contacts c
  ), page as (
    select id, full_name, phones, phone
    from matched
    where p_kind = 'client' or phone is not null
    order by id limit 21
  ), visible as (
    select id, full_name, phones, phone from page order by id limit 20
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(jsonb_build_object(
      'id', id::text,
      'fullName', full_name,
      'phone', coalesce(phone, ''),
      'phones', to_jsonb(phones)
    ) order by id) from visible), '[]'::jsonb),
    'has_more', (select count(*) > 20 from page),
    'next_cursor', (select max(id) from visible)
  ) into v_result;

  return v_result;
end;
$$;

revoke all on function public.traffic_planner_client_options(text,text,bigint,bigint) from public;
grant execute on function public.traffic_planner_client_options(text,text,bigint,bigint) to anon, authenticated;
-- END PLANNER CLIENT OPTIONS 2026-10-15

-- BEGIN PAID WORK PRICE CORRECTION 2026-10-20
-- SOURCE: 20261020055020_payroll_paid_price_correction.sql
-- SQL Editor, not Edge Functions.
-- Requires payroll_pending_recovery. This changes validation only: it does not
-- rewrite salary history, mark payments, or repair any act automatically.

do $$
begin
 if to_regprocedure('public.assert_payroll_paid_preserved(jsonb,jsonb)') is null then
  raise exception 'Спочатку встановіть payroll_pending_recovery з пакета оптимізації.';
 end if;
end $$;

-- Strict, finite number conversion for the narrow client-price correction.
-- Blank/missing values must not silently become zero.
create or replace function public.payroll_price_correction_number(p_value jsonb)
returns double precision language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare raw_value text; result_value double precision;
begin
 if jsonb_typeof(p_value) not in ('number','string') or p_value is null then return null;end if;
 raw_value:=replace(regexp_replace(p_value#>>'{}','[[:space:]]','','g'),',','.');
 if raw_value !~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' then return null;end if;
 result_value:=raw_value::double precision;
 if result_value::text in ('NaN','Infinity','-Infinity') then return null;end if;
 return result_value;
exception when invalid_text_representation or numeric_value_out_of_range then return null;
end $$;

-- A customer's sale price can be corrected without changing the mechanic's
-- acknowledged wage. Every other stored field, including payment dates and
-- unknown metadata, must remain exactly the same. Legacy rows without an ID
-- cannot use this exception.
create or replace function public.payroll_paid_work_price_preserved(p_previous jsonb,p_next jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare previous_price double precision; next_price double precision; quantity double precision; wage double precision;
 calculated_sum double precision; next_sum double precision;
begin
 if p_previous=p_next then return true;end if;
 if jsonb_typeof(p_previous) is distinct from 'object' or jsonb_typeof(p_next) is distinct from 'object'
  or coalesce(jsonb_typeof(p_previous->'recordId'),'null') not in ('number','string')
  or nullif(btrim(p_previous->>'recordId'),'') is null
  or jsonb_typeof(p_previous->'Робота') is distinct from 'string'
  or nullif(btrim(p_previous->>'Робота'),'') is null
  or (p_previous-array['Ціна','Сума']) is distinct from (p_next-array['Ціна','Сума'])
  or (p_previous?'Сума') is distinct from (p_next?'Сума')
  or jsonb_typeof(p_next->'Ціна') is distinct from 'number' then return false;end if;
 previous_price:=public.payroll_price_correction_number(p_previous->'Ціна');
 next_price:=public.payroll_price_correction_number(p_next->'Ціна');
 quantity:=public.payroll_price_correction_number(p_previous->'Кількість');
 wage:=public.payroll_price_correction_number(p_previous->'Зарплата');
 if previous_price is null or next_price is null or quantity is null or wage is null or wage<0
  or previous_price<0 or next_price<0 or previous_price=next_price then return false;end if;
 calculated_sum:=next_price*quantity;
 if calculated_sum::text in ('NaN','Infinity','-Infinity') then return false;end if;
 if p_previous?'Сума' then
  next_sum:=public.payroll_price_correction_number(p_next->'Сума');
  if jsonb_typeof(p_next->'Сума') is distinct from 'number'
   or next_sum is null or next_sum<>calculated_sum then return false;end if;
 end if;
 return true;
exception when numeric_value_out_of_range then return false;
end $$;

-- The paid mechanic header may change only its customer-price total together
-- with a proven price edit. The row set, order, wages and payment marks stay
-- unchanged. Receiver/parts salary bases are not covered by this exception.
create or replace function public.payroll_paid_mechanic_prices_preserved(p_previous jsonb,p_next jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare previous_rows jsonb; next_rows jsonb; previous_row jsonb; next_row jsonb; position integer;
 price double precision; quantity double precision; total double precision:=0;
 expected_total double precision; next_total double precision; changed boolean:=false;
begin
 if jsonb_typeof(p_previous) is distinct from 'object' or jsonb_typeof(p_next) is distinct from 'object'
  or jsonb_typeof(p_previous->'Записи') is distinct from 'array'
  or jsonb_typeof(p_next->'Записи') is distinct from 'array'
  or p_previous?|array['ЗарплатаРоботи','ЗарплатаЗапчастин','ЗарплатаЗапчастистів','Зарплата','Знижка','МаржаДляЗарплати','СуммаЗапчастин',
    '__payroll_percent','__payroll_percent_work','__payroll_percent_parts']
  or (p_previous-array['Записи','СуммаРоботи','Клієнт','Автомобіль','ДатаЗакриття','__payroll_input']) is distinct from
   (p_next-array['Записи','СуммаРоботи','Клієнт','Автомобіль','ДатаЗакриття','__payroll_input']) then return false;end if;
 previous_rows:=p_previous->'Записи';next_rows:=p_next->'Записи';
 if jsonb_array_length(previous_rows)=0 or jsonb_array_length(previous_rows)<>jsonb_array_length(next_rows) then return false;end if;
 for position in 0..jsonb_array_length(previous_rows)-1 loop
  previous_row:=previous_rows->position;next_row:=next_rows->position;
  if not public.payroll_paid_work_price_preserved(previous_row,next_row) then return false;end if;
  if previous_row is distinct from next_row then changed:=true;end if;
  price:=public.payroll_price_correction_number(next_row->'Ціна');
  quantity:=public.payroll_price_correction_number(next_row->'Кількість');
  if price is null or price<0 or quantity is null then return false;end if;
  total:=total+price*quantity;
 end loop;
 if not changed or total::text in ('NaN','Infinity','-Infinity') then return false;end if;
 -- Same positive/zero result as Math.max(0, Math.round((sum+EPSILON)*100)/100).
 expected_total:=greatest(0,floor((total+2.220446049250313e-16::double precision)*100+0.5)/100);
 next_total:=public.payroll_price_correction_number(p_next->'СуммаРоботи');
 return jsonb_typeof(p_next->'СуммаРоботи')='number' and next_total is not null and next_total=expected_total;
exception when numeric_value_out_of_range then return false;
end $$;

create or replace function public.assert_payroll_paid_preserved(p_expected jsonb,p_desired jsonb)
returns void language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare previous jsonb; next_value jsonb; item jsonb; matched jsonb; matches integer;
begin
 if p_expected=p_desired then return;end if;
 previous:=p_expected#>'{0,value}';next_value:=p_desired#>'{0,value}';
 if previous is null then return;end if;
 if (coalesce(previous->'Розраховано','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'""'::jsonb)
  or exists(select 1 from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb)) r
   where coalesce(r->'Розраховано','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'""'::jsonb)))
  and p_expected#>>'{0,date}' is distinct from p_desired#>>'{0,date}' then
  raise exception 'Дата оплаченої зарплати змінюється. Відновлення зупинено.' using errcode='55000';
 end if;
 if coalesce(previous->'Розраховано','null'::jsonb) not in ('null'::jsonb,'false'::jsonb,'""'::jsonb)
  and (next_value is null or (previous-array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input']) is distinct from
   (next_value-array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input']))
  and not public.payroll_paid_mechanic_prices_preserved(previous,next_value) then
  raise exception 'Відновлення змінює оплачене нарахування. Потрібна перевірка; виплати збережено.' using errcode='55000';
 end if;
 for item in select value from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb)) loop
  if coalesce(item->'Розраховано','null'::jsonb) in ('null'::jsonb,'false'::jsonb,'""'::jsonb) then continue;end if;
  select count(*) into matches from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb)) r
   where case when nullif(item->>'recordId','') is not null then r->>'recordId'=item->>'recordId' else r=item end;
  if matches<>1 then raise exception 'Оплачена робота видаляється або змінює виконавця. Відновлення зупинено.' using errcode='55000';end if;
  select value into matched from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))
   where case when nullif(item->>'recordId','') is not null then value->>'recordId'=item->>'recordId' else value=item end;
  if not public.payroll_paid_work_price_preserved(item,matched) then
   raise exception 'Сума або дані оплаченої роботи змінилися. Відновлення зупинено.' using errcode='55000';
  end if;
 end loop;
end $$;

revoke all on function public.payroll_price_correction_number(jsonb),
 public.payroll_paid_work_price_preserved(jsonb,jsonb),public.payroll_paid_mechanic_prices_preserved(jsonb,jsonb),
 public.assert_payroll_paid_preserved(jsonb,jsonb) from public,anon;
grant execute on function public.payroll_price_correction_number(jsonb),
 public.payroll_paid_work_price_preserved(jsonb,jsonb),public.payroll_paid_mechanic_prices_preserved(jsonb,jsonb),
 public.assert_payroll_paid_preserved(jsonb,jsonb) to authenticated;

-- Installation self-check uses synthetic JSON only. If a guard regresses, the
-- transaction rolls back; no production act or employee is read or updated.
do $$
declare original_fragment jsonb; corrected_fragment jsonb; invalid_fragment jsonb;
 invalid_row jsonb; correction jsonb; rejected boolean;
begin
 original_fragment:='[{"date":"2026-08-14","value":{"Акт":"1274","СуммаРоботи":1,"Записи":[{"recordId":"row_new_1792221176241_vkc469iqi","Ціна":1,"Робота":"Полоскання блоку циліндрів","Записано":"17.10.2026","Зарплата":25,"Кількість":1,"Розраховано":"17.10.2026"}]}}]'::jsonb;
 corrected_fragment:=jsonb_set(jsonb_set(original_fragment,'{0,value,Записи,0,Ціна}','50'::jsonb),
  '{0,value,СуммаРоботи}','50'::jsonb);
 perform public.assert_payroll_paid_preserved(original_fragment,corrected_fragment);
 perform public.assert_payroll_paid_preserved(corrected_fragment,corrected_fragment);
 perform public.assert_payroll_paid_preserved(
  jsonb_set(original_fragment,'{0,value,Розраховано}','"17.10.2026"'::jsonb),
  jsonb_set(corrected_fragment,'{0,value,Розраховано}','"17.10.2026"'::jsonb));
 for correction in select value from jsonb_array_elements(
  '[{"Зарплата":26},{"Кількість":2},{"Розраховано":false},{"Розраховано":"18.10.2026"}]'::jsonb) loop
  invalid_row:=(corrected_fragment#>'{0,value,Записи,0}')||correction;
  invalid_fragment:=jsonb_set(corrected_fragment,'{0,value,Записи,0}',invalid_row);
  rejected:=false;
  begin
   perform public.assert_payroll_paid_preserved(original_fragment,invalid_fragment);
  exception when sqlstate '55000' then rejected:=true;
  end;
  if not rejected then raise exception 'Перевірка захисту оплаченої зарплати не пройшла; встановлення скасовано.';end if;
 end loop;
end $$;
-- END PAID WORK PRICE CORRECTION 2026-10-20

-- BEGIN PAYROLL PAYMENT LEDGER 2026-10-20
-- SOURCE: 20261020061759_traffic_payroll_payments.sql
-- Read-only payment ledger helpers and payroll report. Run in SQL Editor.
-- Existing tables and RLS are preserved. No historical data is rewritten.

create or replace function public.traffic_payroll_payment_number(p_value jsonb)
returns double precision language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare raw_value text; result_value double precision;
begin
 if jsonb_typeof(p_value) not in ('number','string') or p_value is null then return null;end if;
 raw_value:=replace(regexp_replace(p_value#>>'{}',U&'[[:space:]\00A0\1680\2000-\200A\2028\2029\202F\205F\3000\FEFF]','','g'),',','.');
 if raw_value !~ '^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$' then return null;end if;
 result_value:=raw_value::double precision;
 if result_value::text in ('NaN','Infinity','-Infinity') then return null;end if;
 return result_value;
exception when invalid_text_representation or numeric_value_out_of_range then return null;
end $$;

create or replace function public.traffic_payroll_payment_round(p_value double precision)
returns double precision language plpgsql immutable security invoker set search_path=pg_catalog as $$
begin
 if p_value is null or p_value::text in ('NaN','Infinity','-Infinity') then
  raise exception 'Некоректна сума зарплати' using errcode='22003';
 end if;
 return floor((p_value+2.220446049250313e-16::double precision)*100+0.5)/100;
end $$;

create or replace function public.traffic_payroll_payment_earned(p_target jsonb)
returns double precision language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare result_value double precision:=0; amount double precision; field_name text; item jsonb;
begin
 if jsonb_typeof(p_target) is distinct from 'object' then raise exception 'Некоректне нарахування зарплати';end if;
 if p_target?'Зарплата' then
  result_value:=case when p_target->'Зарплата' in ('null'::jsonb,'""'::jsonb) then 0
   else public.traffic_payroll_payment_number(p_target->'Зарплата') end;
 elsif p_target?'ЗарплатаРоботи' or p_target?'ЗарплатаЗапчастин' then
  foreach field_name in array array['ЗарплатаРоботи','ЗарплатаЗапчастин'] loop
   if not(p_target?field_name) then continue;end if;
   amount:=case when p_target->field_name in ('null'::jsonb,'""'::jsonb) then 0
    else public.traffic_payroll_payment_number(p_target->field_name) end;
   if amount is null or amount<0 then raise exception 'Некоректна сума зарплати';end if;
   if field_name='ЗарплатаРоботи' and p_target?'СуммаРоботи'
    and coalesce(public.traffic_payroll_payment_number(p_target->'СуммаРоботи'),0)<=0 then amount:=0;end if;
   if field_name='ЗарплатаЗапчастин' and not(p_target?'СуммаРоботи') and p_target?'СуммаЗапчастин'
    and coalesce(public.traffic_payroll_payment_number(p_target->'СуммаЗапчастин'),0)<=0 then amount:=0;end if;
   result_value:=result_value+amount;
  end loop;
 elsif jsonb_typeof(p_target->'Записи')='array' then
  for item in select value from jsonb_array_elements(p_target->'Записи') loop
   result_value:=result_value+public.traffic_payroll_payment_earned(item);
  end loop;
 end if;
 if result_value is null or result_value<0 or result_value::text in ('NaN','Infinity','-Infinity') then
  raise exception 'Некоректна сума зарплати';
 end if;
 return result_value;
end $$;

create or replace function public.traffic_payroll_legacy_payment_date(p_target jsonb,p_header jsonb default null)
returns text language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare marker jsonb;
begin
 marker:=p_target->'Розраховано';
 if coalesce(marker,'null'::jsonb) in ('null'::jsonb,'false'::jsonb,'""'::jsonb) then marker:=p_header->'Розраховано';end if;
 if coalesce(marker,'null'::jsonb) in ('null'::jsonb,'false'::jsonb,'""'::jsonb) then return '';end if;
 return coalesce(marker#>>'{}','');
end $$;

-- Returns the explicit ledger, or a virtual legacy payment without writing it.
-- Voids are immutable audit events and can address only the last active payment.
create or replace function public.traffic_payroll_payments(p_target jsonb,p_header jsonb default null)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare ledger jsonb; item jsonb; event_id text; event_ids text[]:='{}'; active_ids text[]:='{}';
 amount double precision; marker text; count_keys integer; active_count integer;
begin
 if not(p_target?'__payroll_payments') then
  marker:=public.traffic_payroll_legacy_payment_date(p_target,p_header);
  if marker='' then return '[]'::jsonb;end if;
  return jsonb_build_array(jsonb_build_object('id','legacy','amount',public.traffic_payroll_payment_earned(p_target),'date',marker));
 end if;
 ledger:=p_target->'__payroll_payments';
 if jsonb_typeof(ledger) is distinct from 'array' then raise exception 'Некоректна історія виплат';end if;
 for item in select value from jsonb_array_elements(ledger) loop
  if jsonb_typeof(item) is distinct from 'object' then raise exception 'Некоректний запис виплати';end if;
  select count(*) into count_keys from jsonb_object_keys(item);
  event_id:=item->>'id';
  if count_keys<>3 or jsonb_typeof(item->'id') is distinct from 'string' or nullif(btrim(event_id),'') is null
   or event_id=any(event_ids) or jsonb_typeof(item->'date') is distinct from 'string'
   or nullif(btrim(item->>'date'),'') is null then raise exception 'Некоректні або повторні дані виплати';end if;
  event_ids:=array_append(event_ids,event_id);
  if item?'amount' then
   amount:=public.traffic_payroll_payment_number(item->'amount');
   if jsonb_typeof(item->'amount') is distinct from 'number' or amount is null or amount<0 then raise exception 'Некоректна сума виплати';end if;
   active_ids:=array_append(active_ids,event_id);
  elsif item?'voids' then
   active_count:=coalesce(array_length(active_ids,1),0);
   if jsonb_typeof(item->'voids') is distinct from 'string' or active_count=0
    or active_ids[active_count] is distinct from item->>'voids' then
    raise exception 'Скасувати можна лише останню чинну виплату';
   end if;
   active_ids:=coalesce(active_ids[1:active_count-1],'{}'::text[]);
  else raise exception 'Невідомий запис виплати';
  end if;
 end loop;
 return ledger;
end $$;

create or replace function public.traffic_payroll_payment_day(p_value text)
returns text language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare day_iso text; parsed date;
begin
 if p_value ~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{4}$' then
  day_iso:=substr(p_value,7,4)||'-'||substr(p_value,4,2)||'-'||substr(p_value,1,2);
 elsif p_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' then day_iso:=left(p_value,10);
 else return '';end if;
 parsed:=day_iso::date;
 if to_char(parsed,'YYYY-MM-DD')<>day_iso then return '';end if;
 return day_iso;
exception when invalid_datetime_format or datetime_field_overflow then return '';
end $$;

create or replace function public.traffic_payroll_payment_summary(
 p_target jsonb,p_header jsonb default null,p_from text default null,p_to text default null)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare ledger jsonb; item jsonb; earned double precision; paid double precision:=0; paid_period double precision:=0;
 payment_count integer:=0; period_count integer:=0; day_iso text; latest_day text:=''; latest_iso text:='';
 last_active_id text:=''; balance double precision;
 start_day text:=public.traffic_payroll_payment_day(p_from); end_day text:=public.traffic_payroll_payment_day(p_to);
begin
 earned:=public.traffic_payroll_payment_earned(p_target);
 ledger:=public.traffic_payroll_payments(p_target,p_header);
 for item in select e.value from jsonb_array_elements(ledger) e
  where e.value?'amount' and not exists(select 1 from jsonb_array_elements(ledger)v where v->>'voids'=e.value->>'id') loop
  paid:=paid+public.traffic_payroll_payment_number(item->'amount');
  payment_count:=payment_count+1;last_active_id:=item->>'id';
  day_iso:=public.traffic_payroll_payment_day(item->>'date');
  if day_iso<>'' and (start_day='' or day_iso>=start_day) and (end_day='' or day_iso<=end_day) then
   paid_period:=paid_period+public.traffic_payroll_payment_number(item->'amount');
   period_count:=period_count+1;
   if day_iso>=latest_iso then latest_iso:=day_iso;latest_day:=item->>'date';end if;
  end if;
 end loop;
 paid:=public.traffic_payroll_payment_round(paid);
 balance:=public.traffic_payroll_payment_round(earned-paid);
 return jsonb_build_object('earned',earned,'paidAmount',paid,
  'due',greatest(0,balance),'overpaid',greatest(0,-balance),
  'paidInPeriod',public.traffic_payroll_payment_round(paid_period),'hasPayment',payment_count>0,
  'hasPeriodPayment',period_count>0,'lastActiveId',last_active_id,'paidDate',latest_day,'paidIso',latest_iso);
end $$;
create or replace function public.traffic_payroll_validate(p_data jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare
 history jsonb:=coalesce(nullif(p_data->'Історія','null'::jsonb),'{}'::jsonb);
 missing_act boolean; invalid_records boolean; duplicate_act text; duplicate_record_act text;
 payroll_entry jsonb; work_entry jsonb;
begin
 if jsonb_typeof(history) is distinct from 'object' then raise exception 'Некоректна історія зарплат';end if;
 if exists(select 1 from jsonb_each(history) h where jsonb_typeof(h.value) is distinct from 'array') then
  raise exception 'Некоректна дата історії зарплат';
 end if;
 with entries as materialized (
  select x.value entry from jsonb_each(history) h cross join lateral jsonb_array_elements(h.value) x
 )
 select exists(select 1 from entries e where e.entry->>'Акт' is null),
  (select e.entry->>'Акт' from entries e group by e.entry->>'Акт' having count(*)>1 limit 1),
  exists(select 1 from entries e where e.entry?'Записи' and e.entry->'Записи'<>'null'::jsonb
   and jsonb_typeof(e.entry->'Записи') is distinct from 'array')
 into missing_act,duplicate_act,invalid_records;
 if missing_act then raise exception 'Нарахування без номера акта';end if;
 if duplicate_act is not null then raise exception 'Дублікати зарплати за актом %',duplicate_act;end if;
 if invalid_records then raise exception 'Некоректний список робіт';end if;
 select x.value->>'Акт' into duplicate_record_act
 from jsonb_each(history) h cross join lateral jsonb_array_elements(h.value) x
 cross join lateral jsonb_array_elements(coalesce(nullif(x.value->'Записи','null'::jsonb),'[]'::jsonb)) r
 where nullif(r.value->>'recordId','') is not null
 group by x.value->>'Акт',r.value->>'recordId' having count(*)>1 limit 1;
 if duplicate_record_act is not null then raise exception 'Повторні ідентифікатори робіт в акті %',duplicate_record_act;end if;
 for payroll_entry in select x.value from jsonb_each(history)h cross join lateral jsonb_array_elements(h.value)x loop
  if payroll_entry?'__payroll_payments' then perform public.traffic_payroll_payments(payroll_entry);end if;
  for work_entry in select value from jsonb_array_elements(coalesce(nullif(payroll_entry->'Записи','null'::jsonb),'[]'::jsonb)) loop
   if work_entry?'__payroll_payments' then perform public.traffic_payroll_payments(work_entry,payroll_entry);end if;
  end loop;
 end loop;
 return true;
end $$;

create or replace function public.traffic_payroll_report_optimized(
 p_filters jsonb,p_offset integer default 0,p_options boolean default true)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare
 result jsonb;
 page_size integer:=greatest(1,least(200,case when coalesce(p_filters->>'page_size','')~'^[0-9]{1,3}$' then (p_filters->>'page_size')::integer else 50 end));
 selected_name text:=coalesce(p_filters->>'name','');
 mode text:=coalesce(p_filters->>'mode','open');
 from_day text:=public.traffic_payroll_iso(p_filters->>'from');
 to_day text:=public.traffic_payroll_iso(p_filters->>'to');
begin
 if mode not in ('open','close','paid') then raise exception 'Невідомий режим дат';end if;
 if to_day='' then raise exception 'Потрібна кінцева дата звіту';end if;
 -- Keep validation global: a duplicate outside the date window must still block payment.
 perform public.traffic_payroll_validate(public.payroll_json_object(to_jsonb(s.data)))
 from public.slyusars s
 where selected_name='' or public.payroll_json_object(to_jsonb(s.data))->>'Name'=selected_name;

 with employee_docs as materialized (
  select s.slyusar_id id,public.payroll_json_object(to_jsonb(s.data)) doc from public.slyusars s
 ), employees as materialized (
  select * from employee_docs where selected_name='' or doc->>'Name'=selected_name
 ), history_days as materialized (
  select e.id,e.doc->>'Name' name,e.doc->'ПроцентРоботи' percent,
   h.key history_day,h.value bucket,public.traffic_payroll_iso(h.key) history_iso
  from employees e cross join lateral jsonb_each(coalesce(nullif(e.doc->'Історія','null'::jsonb),'{}'::jsonb)) h
 ), selected_days as materialized (
  -- Opening dates belong to history buckets. Filter them before expanding acts or works.
  select * from history_days where mode<>'open' or
   (history_iso<>'' and (from_day='' or history_iso>=from_day) and history_iso<=to_day)
 ), raw_entries as materialized (
  select d.id,d.name,d.percent,d.history_day,d.history_iso,x.value entry,x.ordinality entry_order,
   x.value->>'Акт' act,
   -- Cast the history value, never the indexed acts.act_id. Canonical text matching
   -- retains the old behavior for malformed, padded or out-of-range legacy IDs.
   case when x.value->>'Акт' ~ '^(0|[1-9][0-9]{0,18}|-[1-9][0-9]{0,18})$' then
    case when (x.value->>'Акт')::numeric between -9223372036854775808 and 9223372036854775807
     then (x.value->>'Акт')::bigint end end act_number
  from selected_days d cross join lateral jsonb_array_elements(d.bucket) with ordinality x
 ), act_ids as materialized (
  select distinct act_number from raw_entries where act_number is not null
 ), act_docs as materialized (
  -- Parse each referenced act once, even if several employees worked on it.
  select a.act_id,a.date_off,parsed.doc->'Заморожений'='true'::jsonb frozen,
   parsed.doc->'__payroll_pending'='true'::jsonb pending
  from act_ids i join public.acts a on a.act_id=i.act_number
  -- Keep one evaluation of the parser, but materialize only two flags, not act JSON.
  cross join lateral (select public.payroll_json_object(to_jsonb(a.data)) doc offset 0) parsed
 ), entries as materialized (
  select r.*,a.act_id existing_act_id,a.date_off,
   a.frozen,a.pending,
   case when a.act_id is not null then coalesce(a.date_off::text,'') else coalesce(r.entry->>'ДатаЗакриття','') end close_day,
   case when a.act_id is not null then a.date_off is not null else coalesce(r.entry->>'ДатаЗакриття','')<>'' end closed
  from raw_entries r left join act_docs a on a.act_id=r.act_number
 ), scoped_entries as materialized (
  -- Closing dates cannot be inferred from opening dates. Filter their effective
  -- act/legacy date after the join, but still before expanding works.
  select * from entries where not coalesce(frozen,false) and
   (mode<>'close' or (public.traffic_payroll_iso(close_day)<>''
    and (from_day='' or public.traffic_payroll_iso(close_day)>=from_day)
    and public.traffic_payroll_iso(close_day)<=to_day))
 ), expanded as (
  select e.*,case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0 then 'work'
   when entry?'СуммаРоботи' then 'receiver' when entry?'СуммаЗапчастин' then 'parts' else 'unknown' end kind,
   r.value row_data,r.ordinality::integer-1 work_index
  from scoped_entries e cross join lateral jsonb_array_elements(
   case when jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0
    then entry->'Записи' else '[null]'::jsonb end) with ordinality r
 ), dated_rows as (
  select e.*,d.paid_day,d.payment_summary,
   case when kind='work' then coalesce(row_data->>'Робота','') when kind='receiver' then '-' else 'Запчастини' end work,
   case when mode='paid' then d.payment_summary->>'paidIso'
    when mode='close' then public.traffic_payroll_iso(close_day) else history_iso end filter_day
  from expanded e cross join lateral (
   select payment_summary,payment_summary->>'paidDate' paid_day from (
    select public.traffic_payroll_payment_summary(
     case when kind='work' then row_data else entry end,
     case when kind='work' then entry else null end,from_day,to_day) payment_summary offset 0
   ) calculated
  ) d
  where kind<>'unknown' and not(kind='work' and coalesce(row_data->'Кількість'='0'::jsonb,false)
   and not public.traffic_search_truthy(row_data->'Зарплата')
   and not coalesce((d.payment_summary->>'hasPayment')::boolean,false))
 ), value_rows as materialized (
  -- Store scalar report values only. Do not copy the complete act/work JSON into
  -- every expanded row of the materialized totals/sort pipeline.
  select id,name,percent,history_day,history_iso,entry_order,act,existing_act_id,date_off,closed,pending,
   kind,work_index,paid_day,work,
   (payment_summary->>'earned')::double precision earned,
   (payment_summary->>'paidAmount')::double precision paid_amount,
   (payment_summary->>'due')::double precision due,
   (payment_summary->>'overpaid')::double precision overpaid,
   (payment_summary->>'paidInPeriod')::double precision paid_period,
   (payment_summary->>'hasPayment')::boolean has_payment,
   coalesce(public.traffic_search_number(row_data->'Ціна'),0)*coalesce(public.traffic_search_number(row_data->'Кількість'),0) work_total,
   coalesce(public.traffic_search_number(row_data->'Зарплата'),0) work_salary,
   coalesce(public.traffic_search_number(entry->'СуммаРоботи'),0) work_sum,
   coalesce(public.traffic_search_number(entry->'СуммаЗапчастин'),0) parts_sum,
   coalesce(public.traffic_search_number(entry->'ЗарплатаРоботи'),0) receiver_work_salary,
   coalesce(public.traffic_search_number(entry->'ЗарплатаЗапчастин'),0) parts_salary
  from dated_rows where filter_day<>'' and (from_day='' or filter_day>=from_day) and filter_day<=to_day
 ), date_matches as materialized (
  select *,case when kind='work' then work_total when kind='receiver' then work_sum+parts_sum else parts_sum end revenue,
   earned salary
  from value_rows
 ), matches as materialized (
  select * from date_matches where
   (coalesce(p_filters->>'act','')='' or act=p_filters->>'act')
   and (coalesce(p_filters->>'work','')='' or strpos(lower(work),lower(p_filters->>'work'))>0)
   and (coalesce(p_filters->>'payment','all')='all'
    or (p_filters->>'payment'='paid' and has_payment and due=0)
    or (p_filters->>'payment'='unpaid' and due>0))
   and (coalesce(p_filters->>'status','all')='all' or (p_filters->>'status'='closed' and closed) or (p_filters->>'status'='open' and not closed))
   and (coalesce(p_filters->>'percentage','all')='all' or (kind='work' and salary<>0 and coalesce(public.traffic_search_number(percent),0)<>0 and
    case when p_filters->>'percentage'='higher' then (case when revenue>0 then salary/revenue*100 else 0 end)>public.traffic_search_number(percent)
     else (case when revenue>0 then salary/revenue*100 else 0 end)<public.traffic_search_number(percent) end))
 ), page as materialized (
  select *,coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) sort_act,
   case when mode='paid' then public.traffic_payroll_iso(paid_day) else history_iso end sort_day
  from matches order by sort_act desc,sort_day desc,id,history_day,entry_order,work_index
  offset greatest(coalesce(p_offset,0),0) limit page_size
 ), page_entries as (
  -- Full act fragments remain available for the existing guarded payroll writes.
  select distinct p.id,p.name,p.percent,p.history_day,r.entry,p.entry_order
  from page p join raw_entries r on r.id=p.id and r.history_day=p.history_day and r.entry_order=p.entry_order
 ), histories as (
  select id,name,percent,history_day,jsonb_agg(entry order by entry_order) entries
  from page_entries group by id,name,percent,history_day
 ), rows as (
  select id,jsonb_build_object('slyusar_id',id,'data',jsonb_build_object('Name',name,'ПроцентРоботи',percent,'Історія',jsonb_object_agg(history_day,entries))) row
  from histories group by id,name,percent
 ), totals as (
  select count(*) total,coalesce(sum(revenue),0) revenue,coalesce(sum(salary),0) salary,
   coalesce(sum(paid_amount),0) paid_amount,coalesce(sum(due),0) due,
   coalesce(sum(overpaid),0) overpaid,coalesce(sum(paid_period),0) paid_period from matches
 )
 select jsonb_build_object(
  'employees',coalesce((select jsonb_agg(row order by id) from rows),'[]'::jsonb),
  'keys',coalesce((select jsonb_agg(jsonb_build_array(id,history_day,act,case when kind='work' then work_index else null end)
   order by sort_act desc,sort_day desc,id,history_day,entry_order,work_index) from page),'[]'::jsonb),
  'statuses',coalesce((select jsonb_agg(jsonb_build_object('actId',id,'dateOff',date_off,'isClosed',closed,'isFrozen',false,'payrollPending',pending))
   from (select distinct existing_act_id::text id,date_off,closed,pending from page where existing_act_id is not null)s),'[]'::jsonb),
  'page_size',page_size,'total',t.total,'revenue',t.revenue,'salary',t.salary,
  'paidAmount',t.paid_amount,'due',t.due,'overpaid',t.overpaid,'paidInPeriod',t.paid_period,
  'has_more',t.total>greatest(coalesce(p_offset,0),0)+page_size,
  'acts',case when coalesce(p_options,true) then coalesce((select jsonb_agg(act order by coalesce(substring(act from '^[-+]?[0-9]+')::numeric,0) desc)
   from(select distinct act from date_matches)a),'[]'::jsonb) else '[]'::jsonb end,
  'works',case when coalesce(p_options,true) then coalesce((select jsonb_agg(work order by work)
   from(select distinct work from date_matches order by work limit 150)w),'[]'::jsonb) else '[]'::jsonb end
 ) into result from totals t;
 return result;
end $$;

-- Both deployed API versions use the same optimized query. A separate core
-- also keeps reinstalling the previous v2 wrapper safe (no wrapper recursion).
create or replace function public.traffic_payroll_report(p_filters jsonb,p_offset integer default 0)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select public.traffic_payroll_report_optimized(p_filters,p_offset,true);
$$;
create or replace function public.traffic_payroll_report_v2(p_filters jsonb,p_offset integer default 0,p_options boolean default true)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select public.traffic_payroll_report_optimized(p_filters,p_offset,p_options);
$$;

revoke all on function public.traffic_payroll_validate(jsonb),public.traffic_payroll_report_optimized(jsonb,integer,boolean),
 public.traffic_payroll_report(jsonb,integer),public.traffic_payroll_report_v2(jsonb,integer,boolean) from public;
grant execute on function public.traffic_payroll_validate(jsonb),public.traffic_payroll_report_optimized(jsonb,integer,boolean),
 public.traffic_payroll_report(jsonb,integer),public.traffic_payroll_report_v2(jsonb,integer,boolean) to anon,authenticated;

revoke all on function public.traffic_payroll_payment_number(jsonb),public.traffic_payroll_payment_round(double precision),
 public.traffic_payroll_payment_earned(jsonb),public.traffic_payroll_legacy_payment_date(jsonb,jsonb),
 public.traffic_payroll_payments(jsonb,jsonb),public.traffic_payroll_payment_day(text),
 public.traffic_payroll_payment_summary(jsonb,jsonb,text,text) from public;
grant execute on function public.traffic_payroll_payment_number(jsonb),public.traffic_payroll_payment_round(double precision),
 public.traffic_payroll_payment_earned(jsonb),public.traffic_payroll_legacy_payment_date(jsonb,jsonb),
 public.traffic_payroll_payments(jsonb,jsonb),public.traffic_payroll_payment_day(text),
 public.traffic_payroll_payment_summary(jsonb,jsonb,text,text) to anon,authenticated;

-- SOURCE: 20261020061804_payroll_payment_ledger.sql
-- Paid accrual corrections keep a payment ledger. Run in SQL Editor after
-- traffic_payroll_payments. No automatic data repair or new tables.

do $$ begin
 if to_regprocedure('public.traffic_payroll_payment_summary(jsonb,jsonb,text,text)') is null
  or to_regprocedure('public.write_payroll_fragments(bigint,text,jsonb)') is null then
  raise exception 'Спочатку встановіть traffic_payroll_payments і payroll_fragments.';
 end if;
end $$;

create or replace function public.payroll_accrual_ledger_preserved(
 p_previous jsonb,p_next jsonb,p_header jsonb default null)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare previous_ledger jsonb; next_ledger jsonb; old_earned double precision; new_earned double precision;
begin
 if jsonb_typeof(p_previous) is distinct from 'object' or jsonb_typeof(p_next) is distinct from 'object' then return false;end if;
 if p_previous?'__payroll_payments' then
  previous_ledger:=public.traffic_payroll_payments(p_previous,p_header);
  if not(p_next?'__payroll_payments') then return false;end if;
  next_ledger:=public.traffic_payroll_payments(p_next,p_header);
  return previous_ledger=next_ledger;
 end if;
 if public.traffic_payroll_legacy_payment_date(p_previous,p_header)='' then
  return not(p_next?'__payroll_payments');
 end if;
 old_earned:=public.traffic_payroll_payment_earned(p_previous);
 new_earned:=public.traffic_payroll_payment_earned(p_next);
 if not(p_next?'__payroll_payments') then return old_earned=new_earned;end if;
 next_ledger:=public.traffic_payroll_payments(p_next,p_header);
 previous_ledger:=public.traffic_payroll_payments(p_previous,p_header);
 return old_earned<>new_earned and next_ledger=previous_ledger;
exception when others then return false;
end $$;

create or replace function public.payroll_paid_work_adjustment_preserved(
 p_previous jsonb,p_next jsonb,p_header jsonb default null)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare price double precision; quantity double precision; wage double precision; total double precision;
 field_name text; old_amount double precision; next_amount double precision; changed boolean:=false;
begin
 if p_previous=p_next then return true;end if;
 if jsonb_typeof(p_previous) is distinct from 'object' or jsonb_typeof(p_next) is distinct from 'object'
  or coalesce(jsonb_typeof(p_previous->'recordId'),'null') not in ('number','string')
  or nullif(btrim(p_previous->>'recordId'),'') is null
  or jsonb_typeof(p_previous->'Робота') is distinct from 'string' or nullif(btrim(p_previous->>'Робота'),'') is null
  or (p_previous-array['Ціна','Кількість','Зарплата','Сума','__payroll_payments']) is distinct from
   (p_next-array['Ціна','Кількість','Зарплата','Сума','__payroll_payments'])
  or (p_previous?'Сума') is distinct from (p_next?'Сума') then return false;end if;
 foreach field_name in array array['Ціна','Кількість','Зарплата'] loop
  old_amount:=public.traffic_payroll_payment_number(p_previous->field_name);
  next_amount:=public.traffic_payroll_payment_number(p_next->field_name);
  if old_amount is null or next_amount is null then return false;end if;
  if old_amount<>next_amount then
   changed:=true;
   if jsonb_typeof(p_next->field_name) is distinct from 'number' then return false;end if;
  end if;
 end loop;
 if not changed then return false;end if;
 price:=public.traffic_payroll_payment_number(p_next->'Ціна');
 quantity:=public.traffic_payroll_payment_number(p_next->'Кількість');
 wage:=public.traffic_payroll_payment_number(p_next->'Зарплата');
 if price is null or price<0 or quantity is null or wage is null or wage<0 then return false;end if;
 if quantity<0 and quantity<>public.traffic_payroll_payment_number(p_previous->'Кількість') then return false;end if;
 total:=price*quantity;
 if total::text in ('NaN','Infinity','-Infinity') then return false;end if;
 if p_previous?'Сума' and (jsonb_typeof(p_next->'Сума') is distinct from 'number'
  or public.traffic_payroll_payment_number(p_next->'Сума') is null
  or public.traffic_payroll_payment_number(p_next->'Сума')<>total) then return false;end if;
 return public.payroll_accrual_ledger_preserved(p_previous,p_next,p_header);
exception when others then return false;
end $$;

create or replace function public.payroll_paid_header_adjustment_preserved(p_previous jsonb,p_next jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare numeric_keys text[]:=array['СуммаРоботи','СуммаЗапчастин','МаржаДляЗарплати','ЗарплатаРоботи',
 'ЗарплатаЗапчастин','ЗарплатаЗапчастистів','Зарплата','Знижка','__payroll_percent','__payroll_percent_work','__payroll_percent_parts'];
 allowed_keys text[]; field_name text; amount double precision; old_rows jsonb; next_rows jsonb; position integer;
 total double precision:=0; price double precision; quantity double precision;
 mechanic boolean;
begin
 if p_previous=p_next then return true;end if;
 if jsonb_typeof(p_previous) is distinct from 'object' or jsonb_typeof(p_next) is distinct from 'object' then return false;end if;
 if (p_previous-array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input'])=
  (p_next-array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input']) then return true;end if;
 old_rows:=coalesce(nullif(p_previous->'Записи','null'::jsonb),'[]'::jsonb);
 next_rows:=coalesce(nullif(p_next->'Записи','null'::jsonb),'[]'::jsonb);
 if jsonb_typeof(old_rows) is distinct from 'array' or jsonb_typeof(next_rows) is distinct from 'array'
  or jsonb_array_length(old_rows)<>jsonb_array_length(next_rows) then return false;end if;
 mechanic:=jsonb_typeof(p_previous->'Записи')='array';
 if mechanic then
  numeric_keys:=array['СуммаРоботи'];
 else
  if p_next?'Записи' then return false;end if;
  if (p_previous?'Зарплата') is distinct from (p_next?'Зарплата')
   or (p_previous?'СуммаРоботи') is distinct from (p_next?'СуммаРоботи')
   or (p_previous?'СуммаЗапчастин') is distinct from (p_next?'СуммаЗапчастин')
   or (not(p_previous?'СуммаРоботи') and p_previous?'СуммаЗапчастин'
    and (p_previous?'ЗарплатаРоботи') is distinct from (p_next?'ЗарплатаРоботи')) then return false;end if;
 end if;
 allowed_keys:=numeric_keys||array['Клієнт','Автомобіль','ДатаЗакриття','__payroll_input','__payroll_payments','Записи'];
 if (p_previous-allowed_keys) is distinct from (p_next-allowed_keys) then return false;end if;
 foreach field_name in array numeric_keys loop
  if not(p_next?field_name) then continue;end if;
  amount:=public.traffic_payroll_payment_number(p_next->field_name);
  if amount is null then return false;end if;
  if field_name like 'Зарплата%' and amount<0 then return false;end if;
  if (field_name like '__payroll_percent%' or field_name='Знижка') and (amount<0 or amount>100) then return false;end if;
 end loop;
 if mechanic then
  -- Whole mechanic-header legacy payments belong to the original child works.
  -- Store a correction's payment baseline on the affected child, not twice.
  if (p_previous?'__payroll_payments') is distinct from (p_next?'__payroll_payments')
   or p_previous->'__payroll_payments' is distinct from p_next->'__payroll_payments' then return false;end if;
  for position in 0..jsonb_array_length(old_rows)-1 loop
   if not public.payroll_paid_work_adjustment_preserved(old_rows->position,next_rows->position,p_previous) then return false;end if;
   price:=public.traffic_payroll_payment_number(next_rows->position->'Ціна');
   quantity:=public.traffic_payroll_payment_number(next_rows->position->'Кількість');
   if price is null or price<0 or quantity is null then return false;end if;
   total:=total+price*quantity;
  end loop;
  return coalesce(public.traffic_payroll_payment_number(p_next->'СуммаРоботи')=
   greatest(0,public.traffic_payroll_payment_round(total)),false);
 end if;
 return public.payroll_accrual_ledger_preserved(p_previous,p_next);
exception when others then return false;
end $$;

create or replace function public.assert_payroll_paid_preserved(p_expected jsonb,p_desired jsonb)
returns void language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare previous jsonb; next_value jsonb; item jsonb; matched jsonb; matches integer;
 old_protected boolean; row_protected boolean;
begin
 if p_expected=p_desired then return;end if;
 previous:=p_expected#>'{0,value}';next_value:=p_desired#>'{0,value}';
 if public.traffic_payroll_legacy_payment_date(next_value)<>'' and
  public.traffic_payroll_legacy_payment_date(previous)='' then
  raise exception 'Збереження акта не може позначати зарплату виплаченою' using errcode='55000';
 end if;
 for item in select value from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))
  where public.traffic_payroll_legacy_payment_date(value)<>'' loop
  select count(*) into matches from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb))r
   where case when nullif(btrim(item->>'recordId'),'') is not null then btrim(r->>'recordId')=btrim(item->>'recordId')
    else r=item end
    and public.traffic_payroll_legacy_payment_date(r)<>'';
  if matches<>1 then raise exception 'Збереження акта не може створювати позначку виплати роботи' using errcode='55000';end if;
 end loop;
 -- An accrual must never introduce payments in a new employee/act or work.
 if previous is null then
  if next_value?'__payroll_payments' or exists(
   select 1 from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))r where r?'__payroll_payments') then
   raise exception 'Нове нарахування не може містити попередні виплати' using errcode='55000';
  end if;
  return;
 end if;
 old_protected:=previous?'__payroll_payments' or public.traffic_payroll_legacy_payment_date(previous)<>'';
 if (old_protected or exists(select 1 from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb))r
  where r?'__payroll_payments' or public.traffic_payroll_legacy_payment_date(r,previous)<>''))
  and p_expected#>>'{0,date}' is distinct from p_desired#>>'{0,date}' then
  raise exception 'Дата оплаченої зарплати змінюється. Відновлення зупинено.' using errcode='55000';
 end if;
 if old_protected and not public.payroll_paid_header_adjustment_preserved(previous,next_value) then
  raise exception 'Зміна зарплати не зберігає попередні виплати або склад робіт' using errcode='55000';
 end if;
 if not old_protected and next_value?'__payroll_payments' then
  raise exception 'Нарахування не може створювати виплату' using errcode='55000';
 end if;
 for item in select value from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb)) loop
  row_protected:=item?'__payroll_payments' or public.traffic_payroll_legacy_payment_date(item,previous)<>'';
  if not row_protected then continue;end if;
  select count(*) into matches from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))r
   where case when nullif(item->>'recordId','') is not null then r->>'recordId'=item->>'recordId' else r=item end;
  if matches<>1 then raise exception 'Оплачена робота видаляється або змінює виконавця' using errcode='55000';end if;
  select value into matched from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))
   where case when nullif(item->>'recordId','') is not null then value->>'recordId'=item->>'recordId' else value=item end;
  if not public.payroll_paid_work_adjustment_preserved(item,matched,previous) then
   raise exception 'Оплачена робота не зберігає історію виплат або виконавця' using errcode='55000';
  end if;
 end loop;
 for item in select value from jsonb_array_elements(coalesce(nullif(next_value->'Записи','null'::jsonb),'[]'::jsonb))
  where value?'__payroll_payments' loop
  select count(*) into matches from jsonb_array_elements(coalesce(nullif(previous->'Записи','null'::jsonb),'[]'::jsonb))r
   where nullif(item->>'recordId','') is not null and r->>'recordId'=item->>'recordId';
  if matches<>1 then raise exception 'Нова робота не може створювати історію виплат' using errcode='55000';end if;
  select value into matched from jsonb_array_elements(previous->'Записи') where value->>'recordId'=item->>'recordId';
  if not public.payroll_accrual_ledger_preserved(matched,item,previous) then
   raise exception 'Нарахування не може змінювати історію виплат' using errcode='55000';
  end if;
 end loop;
end $$;

create or replace function public.payroll_payment_append_preserved(
 p_previous jsonb,p_next jsonb,p_header jsonb default null)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog as $$
declare old_ledger jsonb; next_ledger jsonb; event jsonb; prefix jsonb; old_summary jsonb; amount double precision;
begin
 if (p_previous-'__payroll_payments') is distinct from (p_next-'__payroll_payments')
  or not(p_next?'__payroll_payments') then return false;end if;
 old_ledger:=public.traffic_payroll_payments(p_previous,p_header);
 next_ledger:=public.traffic_payroll_payments(p_next,p_header);
 if jsonb_array_length(next_ledger)<>jsonb_array_length(old_ledger)+1 then return false;end if;
 event:=next_ledger->(jsonb_array_length(next_ledger)-1);
 select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into prefix
  from jsonb_array_elements(next_ledger) with ordinality where ordinality<=jsonb_array_length(old_ledger);
 if prefix is distinct from old_ledger or event->>'id'='legacy'
  or public.traffic_payroll_payment_day(event->>'date')='' then return false;end if;
 old_summary:=public.traffic_payroll_payment_summary(p_previous,p_header);
 if event?'amount' then
  amount:=public.traffic_payroll_payment_number(event->'amount');
  return amount>0 and amount=(old_summary->>'due')::double precision;
 end if;
 return nullif(old_summary->>'lastActiveId','') is not null and event->>'voids'=old_summary->>'lastActiveId';
exception when others then return false;
end $$;
create or replace function public.write_payroll_fragments(p_employee_id bigint,p_mode text,p_changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare employee public.slyusars%rowtype; converted public.slyusars%rowtype;
 current_data jsonb; original_data jsonb; history jsonb; act_data jsonb; act_id_value bigint;
 change jsonb; actual jsonb; expected jsonb; desired jsonb; entry jsonb; bucket jsonb; records jsonb;
 old_date text; new_date text; act_key text; record_key text; entry_index integer; record_index integer; match_count integer;
 target jsonb; next_target jsonb; paid jsonb; revision text;
begin
 if p_mode not in ('accrual','payment') or p_mode is null or jsonb_typeof(p_changes) is distinct from 'array' or jsonb_array_length(p_changes)>2000 then raise exception 'Некоректний запит зарплати';end if;
 if exists(select 1 from jsonb_array_elements(p_changes)x where coalesce(x->>'act_id','')!~'^[1-9][0-9]*$') then raise exception 'Некоректний номер акта';end if;
 -- Deterministic locks: all affected acts in ascending order, then one employee.
 -- Payment checks and employee mutation share this transaction.
 for act_id_value in select distinct (value->>'act_id')::bigint from jsonb_array_elements(p_changes) order by 1 loop
  select public.payroll_json_object(to_jsonb(a.data)) into act_data from public.acts a where a.act_id=act_id_value for update;
  if not found then raise exception 'Акт відсутній або недоступний' using errcode='40001';end if;
  if p_mode='payment' and (act_data->'Заморожений'='true'::jsonb or act_data->'__payroll_pending'='true'::jsonb) then
   raise exception 'Акт заморожений або розрахунок зарплати ще не завершений' using errcode='55000';
  end if;
 end loop;
 select * into employee from public.slyusars where slyusar_id=p_employee_id for update;
 if not found then raise exception 'Працівник відсутній або недоступний' using errcode='40001';end if;
 current_data:=public.payroll_json_object(to_jsonb(employee.data));original_data:=current_data;
 history:=coalesce(nullif(current_data->'Історія','null'::jsonb),'{}'::jsonb);
 for change in select value from jsonb_array_elements(p_changes) loop
  act_key:=change->>'act_id';actual:=public.payroll_act_entries(history,act_key);
  if jsonb_array_length(actual)>1 then raise exception 'Дублікати зарплати за актом %',act_key using errcode='40001';end if;
  if p_mode='accrual' then
   expected:=change->'expected';desired:=change->'desired';
   if jsonb_typeof(expected) is distinct from 'array' or jsonb_typeof(desired) is distinct from 'array' or jsonb_array_length(expected)>1 or jsonb_array_length(desired)>1 then raise exception 'Некоректний фрагмент нарахування';end if;
   if jsonb_array_length(desired)=1 then
    entry:=desired#>'{0,value}';new_date:=desired#>>'{0,date}';
    if jsonb_typeof(entry) is distinct from 'object' or entry->>'Акт' is distinct from act_key or nullif(new_date,'') is null then raise exception 'Некоректний акт нарахування';end if;
    records:=coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb);
    if jsonb_typeof(records) is distinct from 'array' then raise exception 'Некоректні записи робіт';end if;
    if exists(select 1 from jsonb_array_elements(records)r where nullif(r->>'recordId','') is not null group by r->>'recordId' having count(*)>1) then raise exception 'Повторні ідентифікатори робіт' using errcode='40001';end if;
   end if;
   if actual=desired then continue;end if;
   if actual is distinct from expected then raise exception 'Зарплату змінено. Оновіть дані.' using errcode='40001';end if;
   -- Direct accrual calls receive the same ledger protection as commit_act_payroll.
   perform public.assert_payroll_paid_preserved(actual,desired);
   old_date:=actual#>>'{0,date}';new_date:=desired#>>'{0,date}';
   if old_date is not null and old_date=new_date then
    select coalesce(jsonb_agg(case when value->>'Акт'=act_key then desired#>'{0,value}' else value end order by ordinality),'[]'::jsonb) into bucket from jsonb_array_elements(history->old_date) with ordinality;
    history:=jsonb_set(history,array[old_date],bucket);
   else
    if old_date is not null then
     select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into bucket from jsonb_array_elements(history->old_date) with ordinality where value->>'Акт' is distinct from act_key;
     history:=case when bucket='[]'::jsonb then history-old_date else jsonb_set(history,array[old_date],bucket) end;
    end if;
    if new_date is not null then history:=jsonb_set(history,array[new_date],coalesce(history->new_date,'[]'::jsonb)||jsonb_build_array(desired#>'{0,value}'));end if;
   end if;
  else
   if jsonb_array_length(actual)<>1 or actual#>>'{0,date}' is distinct from change->>'date' then raise exception 'Нарахування змінилось або відсутнє' using errcode='40001';end if;
   old_date:=actual#>>'{0,date}';entry:=actual#>'{0,value}';expected:=change->'expected';paid:=change->'desired';
   if jsonb_typeof(expected) is distinct from 'object' or jsonb_typeof(paid) is distinct from 'object'
    or exists(select 1 from jsonb_object_keys(paid)k where k not in ('Розраховано','__payroll_payments')) then
    raise exception 'Виплата може змінювати лише журнал виплат і позначку розрахунку';
   end if;
   if change->>'target'='act' then target:=entry-'Записи';
   elsif change->>'target'='record' then
    records:=entry->'Записи';record_key:=change->>'record_id';
    if jsonb_typeof(records) is distinct from 'array' then raise exception 'Роботи відсутні' using errcode='40001';end if;
    if record_key is not null then
     select count(*),min(ordinality::int-1) into match_count,record_index from jsonb_array_elements(records) with ordinality where value->>'recordId'=record_key;
     if match_count<>1 then raise exception 'Робота відсутня або має дублікат ID' using errcode='40001';end if;
    else
     if coalesce(change->>'index','')!~'^[0-9]+$' then raise exception 'Немає ідентифікатора роботи';end if;
     record_index:=(change->>'index')::integer;
     -- Legacy rows without IDs can only be addressed if their immutable content is unique.
     select count(*) into match_count from jsonb_array_elements(records)r where r-'Розраховано'=expected-'Розраховано';
     if match_count<>1 then raise exception 'Неоднозначна стара робота без ID' using errcode='40001';end if;
    end if;
    target:=records->record_index;
   else raise exception 'Невідома ціль виплати';end if;
   next_target:=(expected-array['Розраховано','__payroll_payments'])||paid;
   if target=next_target then continue;end if;
   if target is distinct from expected then raise exception 'Виплату або нарахування змінено. Оновіть дані.' using errcode='40001';end if;
   if change->>'target'='act' and (
    exists(select 1 from jsonb_array_elements(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))r
     where r?'__payroll_payments')
    or ((target?'__payroll_payments' or paid?'__payroll_payments')
     and jsonb_array_length(coalesce(nullif(entry->'Записи','null'::jsonb),'[]'::jsonb))>0)) then
    raise exception 'Роботи з історією виплат розраховуються окремо' using errcode='55000';
   end if;
   if target?'__payroll_payments' or paid?'__payroll_payments' then
    if not public.payroll_payment_append_preserved(target,next_target,
     case when change->>'target'='record' then entry else null end) then
     raise exception 'Виплата має зберегти історію та дорівнювати залишку; скасувати можна лише останню виплату' using errcode='55000';
    end if;
   elsif paid?'Розраховано' and (jsonb_typeof(paid->'Розраховано')<>'string' or nullif(paid->>'Розраховано','') is null) then
    raise exception 'Некоректна дата виплати';
   end if;
   if change->>'target'='act' then entry:=(entry-array['Розраховано','__payroll_payments'])||paid;
   else entry:=jsonb_set(entry,array['Записи',record_index::text],next_target);end if;
   select ordinality::integer-1 into entry_index from jsonb_array_elements(history->old_date) with ordinality where value->>'Акт'=act_key;
   history:=jsonb_set(history,array[old_date,entry_index::text],entry);
  end if;
 end loop;
 current_data:=jsonb_set(current_data,array['Історія'],history);
 if current_data=original_data then return jsonb_build_object('slyusar_id',p_employee_id,'status','unchanged','revision',current_data->>'__payroll_revision');end if;
 revision:=gen_random_uuid()::text;current_data:=current_data||jsonb_build_object('__payroll_revision',revision);
 converted:=jsonb_populate_record(null::public.slyusars,jsonb_build_object('data',current_data));
 update public.slyusars set data=converted.data where slyusar_id=p_employee_id;
 if not found then raise exception 'Запис зарплати заборонений' using errcode='40001';end if;
 return jsonb_build_object('slyusar_id',p_employee_id,'status','updated','revision',revision,'changed',jsonb_array_length(p_changes));
end $$;

