-- BEGIN DIRECTORY MODAL INTEGRITY 2026-10-21
-- SOURCE: 20261021154545_traffic_directory_modal_read.sql
-- Compact modal directory pages and selected stock baseline. Existing RLS remains in force.

create or replace function public.traffic_directory_page(p_kind text,p_query text default '',p_offset integer default 0,p_exact boolean default false,p_id bigint default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare id_col text; result jsonb; projection text; label text;
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'faktura' then 'faktura_id' when 'works' then 'work_id' when 'shops' then 'shop_id' when 'details' then 'detail_id' end;
 if id_col is null or p_offset is null or p_offset<0 or (p_id is not null and p_id<=0) then raise exception 'Invalid directory';end if;
 if p_kind='faktura' then
  projection:='jsonb_build_object(''faktura_id'',t.faktura_id,''name'',t.name,''oderjyvach'',t.oderjyvach,''prumitka'',t.prumitka,''data'',t.data,''namber'',t.namber)';
  label:='coalesce(t.oderjyvach,'''')';
 elsif p_kind in ('works','details') then
  projection:=format('jsonb_build_object(%L,t.%I,''data'',public.traffic_reference_name(to_jsonb(t.data)))',id_col,id_col);
  label:='coalesce(public.traffic_reference_name(to_jsonb(t.data)),'''')';
 else
  projection:=format('jsonb_build_object(%L,t.%I,''data'',(select coalesce(jsonb_object_agg(key,value),''{}''::jsonb) from jsonb_each(public.sto_read_object_v1(to_jsonb(t.data))) where key=any(%L::text[])))',id_col,id_col,
   case when p_kind='slyusars' then case when p_id is null then '{Name,Доступ}' else '{Name,Доступ,ПроцентРоботи,ПроцентЗапчастин,Склад,Пароль}' end else '{Name}' end);
  label:='coalesce(public.sto_read_object_v1(to_jsonb(t.data))->>''Name'','''')';
 end if;
 -- Count/filter only IDs and names. Build response JSON after the page boundary,
 -- avoiding extraction of editable metadata for every matching employee/record.
 execute format($query$
  with matches as materialized (
   select t.%I id,%s label from public.%I t
   where ($4 is null or t.%I=$4)
    and (case when $3 then public.traffic_directory_name(%s)=public.traffic_directory_name($1)
     else strpos(public.traffic_directory_name(%s),public.traffic_directory_name($1))>0 end)
  ), page as (select * from matches order by label,id offset $2 limit 50),
  serialized as (select p.id,p.label,%s row from page p join public.%I t on t.%I=p.id)
  select jsonb_build_object('items',coalesce((select jsonb_agg(row order by label,id) from serialized),'[]'::jsonb),
   'total',(select count(*) from matches))
 $query$,id_col,label,p_kind,id_col,label,label,projection,p_kind,id_col)
 into result using p_query,p_offset,p_exact,p_id;
 return result;
end $$;

create or replace function public.traffic_stock_position(p_id bigint)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_build_object('sclad_id',s.sclad_id,'time_on',s.time_on,'shops',s.shops,'part_number',s.part_number,'name',s.name,
  'kilkist_on',s.kilkist_on,'price',s.price,'rahunok',s.rahunok,'unit_measurement',s.unit_measurement,'scladNomer',s."scladNomer",'xto_zamovuv',s.xto_zamovuv,
  'shop_id',public.traffic_reference_id('shops',s.shops),'detail_id',public.traffic_reference_id('details',s.name),
  'employee_name',(select public.traffic_reference_name(to_jsonb(e.data)) from public.slyusars e where e.slyusar_id=s.xto_zamovuv))
  || (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(to_jsonb(s)) where key=any(array['kilkist_off','akt','statys','prumitka','client_price']))
 from public.sclad s where s.sclad_id=p_id
$$;
revoke all on function public.traffic_stock_position(bigint) from public;
grant execute on function public.traffic_stock_position(bigint) to anon,authenticated;

-- The existing lazy page also serves as a baseline for guarded editing/deletion.
-- Include consumed quantity once per loaded row, avoiding a selected-row re-read.
create or replace function public.traffic_stock_page_v2(p_status text default null,p_from text default null,p_to text default null,p_query text default '',p_before bigint default null,p_limit integer default 20)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
 select n.sclad_id,n.time_on,n.shops,n.part_number,n.name,n.kilkist_on,n.kilkist_off,n.price,n."scladNomer",n.rahunok,n.akt,n.unit_measurement,n.statys,n.prumitka,n.xto_zamovuv,to_jsonb(n)->'client_price' as client_price
 from public.sclad n
 where (case when p_status='Прибула' then n.statys is null when p_status in ('Замовити','Замовлено') then n.statys=p_status else n.statys in ('Замовити','Замовлено') end)
 and (nullif(p_from,'') is null or n.time_on >= nullif(p_from,'')::timestamptz)
 and (nullif(p_to,'') is null or n.time_on <= nullif(p_to,'')::timestamptz)
 and (p_before is null or n.sclad_id<p_before)
 and (nullif(btrim(p_query),'') is null or strpos(lower(coalesce(n.part_number,'')),lower(btrim(p_query)))>0 or
 (public.traffic_catalog_key(p_query)<>'' and strpos(public.traffic_catalog_key(n.part_number),public.traffic_catalog_key(p_query))>0))
 order by n.sclad_id desc limit least(20,greatest(1,coalesce(p_limit,20)))+1
 ), visible as (select * from page order by sclad_id desc limit least(20,greatest(1,coalesce(p_limit,20))))
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(v) order by v.sclad_id desc) from visible v),'[]'::jsonb),
 'has_more',(select count(*)>least(20,greatest(1,coalesce(p_limit,20))) from page),'next_cursor',(select min(sclad_id) from visible));
$$;
revoke all on function public.traffic_stock_page_v2(text,text,text,text,bigint,integer) from public;
grant execute on function public.traffic_stock_page_v2(text,text,text,text,bigint,integer) to anon,authenticated;


revoke all on function public.traffic_directory_page(text,text,integer,boolean,bigint) from public;
grant execute on function public.traffic_directory_page(text,text,integer,boolean,bigint) to anon,authenticated;

-- SOURCE: 20261021153336_directory_modal_integrity.sql
-- Modal directory CRUD: compact reads, atomic field patches and confirmed deletes.
-- Requires the existing directory/stock read and write migrations from package 8.
-- No new tables, policies, triggers, or privilege elevation.

-- Keep legacy catalog metadata and the original JSON/string representation.
-- The selected name key follows traffic_reference_name's existing precedence.
create or replace function public.traffic_directory_rename_reference(p_data jsonb,p_name text)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare document jsonb:=p_data; serialized boolean:=false; content text; field text;
begin
 if p_data is null or p_data='null'::jsonb then return to_jsonb(p_name);end if;
 if jsonb_typeof(document)='string' then
  content:=btrim(document#>>'{}');
  if left(content,1) not in ('{','[') then return to_jsonb(p_name);end if;
  begin document:=content::jsonb;exception when invalid_text_representation then return to_jsonb(p_name);end;
  serialized:=true;
 end if;
 if jsonb_typeof(document) is distinct from 'object' then raise exception 'Непідтримуваний формат назви довідника. Дані залишено без змін.';end if;
 foreach field in array array['Name','name','Назва','Текст','text','ПІБ'] loop
  if jsonb_typeof(document->field) in ('string','number') and nullif(btrim(document->>field),'') is not null then
   document:=jsonb_set(document,array[field],to_jsonb(p_name),false);
   return case when serialized then to_jsonb(document::text) else document end;
  end if;
 end loop;
 raise exception 'Не знайдено поле назви довідника. Дані залишено без змін.';
end $$;
revoke all on function public.traffic_directory_rename_reference(jsonb,text) from public;
grant execute on function public.traffic_directory_rename_reference(jsonb,text) to anon,authenticated;

create or replace function public.traffic_directory_write(p_kind text,p_id bigint,p_patch jsonb,p_expected jsonb default null)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare id_col text; allowed text[]; old jsonb; merged jsonb; name text; matches bigint[]; next_id bigint; value_type text; result jsonb; field text; payload text; name_expr text; affected bigint; plain boolean; original_data jsonb; renamed_data jsonb; outcome text:='updated';
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'shops' then 'shop_id' when 'works' then 'work_id' when 'details' then 'detail_id' end;
 if id_col is null or jsonb_typeof(p_patch) is distinct from 'object' or (p_id is not null and p_id<=0) then raise exception 'Invalid directory patch';end if;
 plain:=p_kind in ('works','details');
 allowed:=case when plain then array['data'] when p_kind='slyusars' then array['Name','Пароль','Доступ','ПроцентРоботи','ПроцентЗапчастин','Склад'] else array['Name'] end;
 if exists(select 1 from jsonb_object_keys(p_patch) k where not k=any(allowed)) then raise exception 'Only directory metadata may change';end if;
 for field in select jsonb_object_keys(p_patch) loop
  if field in ('Name','data','Доступ','Пароль') and jsonb_typeof(p_patch->field) is distinct from 'string' then raise exception 'Некоректне текстове поле %',field;end if;
  if field in ('ПроцентРоботи','ПроцентЗапчастин','Склад') then
   if jsonb_typeof(p_patch->field) is distinct from 'number' then raise exception 'Некоректне числове поле %',field;end if;
   if (p_patch->>field)::numeric<0 or (field<>'Склад' and (p_patch->>field)::numeric>100) or (field='Склад' and trunc((p_patch->>field)::numeric)<>(p_patch->>field)::numeric) then raise exception 'Некоректне значення поля %',field;end if;
  end if;
 end loop;
 if p_kind in ('shops','details') then perform pg_advisory_xact_lock(1937010546,1);end if;
 perform pg_advisory_xact_lock(hashtext('traffic-directory:'||p_kind));
 if p_id is null then execute format('lock table public.%I in share row exclusive mode',p_kind);
 else
  if plain then
   execute format('select jsonb_build_object(''data'',public.traffic_reference_name(to_jsonb(data))),to_jsonb(data) from public.%I where %I=$1 for update',p_kind,id_col) into old,original_data using p_id;
  else execute format('select public.sto_read_object_v1(to_jsonb(data)) from public.%I where %I=$1 for update',p_kind,id_col) into old using p_id;end if;
  if old is null then raise exception 'Запис не знайдено або немає доступу. Оновіть список.';end if;
  if jsonb_typeof(p_expected) is distinct from 'object' then raise exception 'Directory baseline required';end if;
  if p_kind='slyusars' and p_id=1 then p_patch:=p_patch-'Name'-'Доступ';end if;
  for field in select jsonb_object_keys(p_patch) loop
   if old->field is distinct from p_expected->field and old->field is distinct from p_patch->field then raise exception 'Поле % змінено іншим користувачем. Оновіть дані.',field;end if;
  end loop;
 end if;
 merged:=coalesce(old,case when p_kind='slyusars' then '{"Опис":{},"Історія":{}}'::jsonb when p_kind='shops' then '{"Склад":{},"Історія":{},"Про магазин":""}'::jsonb else '{}'::jsonb end)||p_patch;
 field:=case when plain then 'data' else 'Name' end;
 name:=public.traffic_directory_name(merged->>field);if name='' then raise exception 'Назва обов’язкова';end if;
 name_expr:=case when plain then 'public.traffic_reference_name(to_jsonb(data))' else 'public.sto_read_object_v1(to_jsonb(data))->>''Name''' end;
 if p_id is null or name is distinct from public.traffic_directory_name(old->>field) then
  execute format('select array_agg(%I order by %I) from public.%I where public.traffic_directory_name(%s)=$1 and ($2 is null or %I<>$2)',id_col,id_col,p_kind,name_expr,id_col) into matches using name,p_id;
 end if;
 if coalesce(cardinality(matches),0)>1 then raise exception 'Неоднозначна назва: декілька історичних записів. Виберіть ID.';end if;
 if coalesce(cardinality(matches),0)=1 then
  if p_id is not null then raise exception 'Запис із такою назвою вже існує';end if;
  result:=public.traffic_directory_page(p_kind,'',0,false,matches[1]);return jsonb_build_object('status','existing','row',result->'items'->0);
 end if;
 if old is not null and merged=old then
  result:=public.traffic_directory_page(p_kind,'',0,false,p_id);return jsonb_build_object('status','unchanged','row',result->'items'->0);
 end if;
 select format_type(a.atttypid,a.atttypmod) into value_type from pg_attribute a where a.attrelid=format('public.%I',p_kind)::regclass and a.attname='data';
 if plain then
  renamed_data:=public.traffic_directory_rename_reference(original_data,merged->>'data');
  payload:=case when value_type in ('json','jsonb') or jsonb_typeof(renamed_data)<>'string' then renamed_data::text else renamed_data#>>'{}' end;
 else payload:=merged::text;end if;
 if p_id is null then
  execute format('select coalesce(max(%I),0)+1 from public.%I',id_col,p_kind) into next_id;
  execute format('insert into public.%I(%I,data) values($1,$2::%s)',p_kind,id_col,value_type) using next_id,payload;
  get diagnostics affected=row_count;p_id:=next_id;outcome:='created';
 else
  execute format('update public.%I set data=$1::%s where %I=$2',p_kind,value_type,id_col) using payload,p_id;
  get diagnostics affected=row_count;
 end if;
 if affected<>1 then raise exception 'База не підтвердила збереження. Перевірте доступ або оновіть запис.' using errcode='42501';end if;
 result:=public.traffic_directory_page(p_kind,'',0,false,p_id);
 if result->'items'->0 is null then raise exception 'Не отримано збережений запис';end if;
 return jsonb_build_object('status',outcome,'row',result->'items'->0);
end $$;

-- Legacy histories may be JSON objects, arrays, or JSON serialized inside strings.
create or replace function public.traffic_directory_has_history(v jsonb)
returns boolean language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare child jsonb; parsed jsonb;
begin
 if v is null or v in ('null'::jsonb,'{}'::jsonb,'[]'::jsonb,'""'::jsonb) then return false;end if;
 if jsonb_typeof(v)='object' then
  for child in select value from jsonb_each(v) loop if public.traffic_directory_has_history(child) then return true;end if;end loop;return false;
 elsif jsonb_typeof(v)='array' then
  for child in select value from jsonb_array_elements(v) loop if public.traffic_directory_has_history(child) then return true;end if;end loop;return false;
 elsif jsonb_typeof(v)='string' then
  if btrim(v#>>'{}')='' then return false;end if;
  begin parsed:=(v#>>'{}')::jsonb;exception when others then return true;end;
  return public.traffic_directory_has_history(parsed);
 end if;
 return true;
end $$;
revoke all on function public.traffic_directory_has_history(jsonb) from public;
grant execute on function public.traffic_directory_has_history(jsonb) to anon,authenticated;

create or replace function public.traffic_directory_delete(p_kind text,p_id bigint,p_expected jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare id_col text; old jsonb; field text; affected bigint;
begin
 id_col:=case p_kind when 'slyusars' then 'slyusar_id' when 'incomes' then 'income_id' when 'receivers' then 'receiver_id' when 'shops' then 'shop_id' when 'works' then 'work_id' when 'details' then 'detail_id' when 'faktura' then 'faktura_id' end;
 if id_col is null or p_id is null or p_id<=0 or jsonb_typeof(p_expected) is distinct from 'object' or p_expected='{}'::jsonb then raise exception 'Виберіть запис для видалення зі списку.';end if;
 if p_kind='slyusars' and p_id=1 then raise exception 'Видалення адміністраторського акаунту заборонено!';end if;
 if p_kind in ('shops','details') then perform pg_advisory_xact_lock(1937010546,1);end if;
 perform pg_advisory_xact_lock(hashtext('traffic-directory:'||p_kind));
 if p_kind='faktura' then select to_jsonb(f) into old from public.faktura f where faktura_id=p_id for update;
 elsif p_kind in ('works','details') then execute format('select jsonb_build_object(''data'',public.traffic_reference_name(to_jsonb(data))) from public.%I where %I=$1 for update',p_kind,id_col) into old using p_id;
 else execute format('select public.sto_read_object_v1(to_jsonb(data)) from public.%I where %I=$1 for update',p_kind,id_col) into old using p_id;end if;
 if old is null then raise exception 'Запис уже видалено або немає доступу. Оновіть список.';end if;
 if (p_kind in ('works','details') and not (p_expected ? 'data')) or (p_kind not in ('works','details','faktura') and not (p_expected ? 'Name')) or (p_kind='faktura' and not (p_expected ? 'name')) then raise exception 'Немає вихідних даних запису. Виберіть його повторно.';end if;
 for field in select jsonb_object_keys(p_expected) loop
  if old->field is distinct from p_expected->field then raise exception 'Запис змінився після вибору. Оновіть його перед видаленням.';end if;
 end loop;
 if p_kind in ('slyusars','shops') and (public.traffic_directory_has_history(old->'Історія') or (p_kind='shops' and public.traffic_directory_has_history(old->'Склад'))) then
  raise exception 'Запис має історію або складські дані. Його видалення знищить ці дані та заблоковане.';
 end if;
 execute format('delete from public.%I where %I=$1',p_kind,id_col) using p_id;
 get diagnostics affected=row_count;
 if affected<>1 then raise exception 'База не підтвердила видалення. Перевірте права доступу.' using errcode='42501';end if;
 return jsonb_build_object('status','deleted','id',p_id);
end $$;

revoke all on function public.traffic_directory_page(text,text,integer,boolean,bigint),public.traffic_directory_write(text,bigint,jsonb,jsonb),public.traffic_directory_delete(text,bigint,jsonb) from public;
grant execute on function public.traffic_directory_page(text,text,integer,boolean,bigint),public.traffic_directory_write(text,bigint,jsonb,jsonb),public.traffic_directory_delete(text,bigint,jsonb) to anon,authenticated;

create or replace function public.traffic_contragent_write(p_id bigint,p_patch jsonb,p_expected jsonb default null)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare old jsonb; merged jsonb; iban text; n integer; next_id bigint; field text; result jsonb; affected bigint;
begin
 if jsonb_typeof(p_patch) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_patch) k where k not in ('name','oderjyvach','prumitka','data','namber')) then raise exception 'Invalid counterparty patch';end if;
 perform pg_advisory_xact_lock(hashtext('traffic-directory:faktura'));
 if p_id is null then lock table public.faktura in share row exclusive mode;
 else
  select to_jsonb(f) into old from public.faktura f where faktura_id=p_id for update;
  if old is null or p_expected is null then raise exception 'Оновіть контрагента перед редагуванням';end if;
  for field in select jsonb_object_keys(p_patch) loop
   if old->field is distinct from p_expected->field and old->field is distinct from p_patch->field then raise exception 'Контрагент змінений іншим користувачем. Оновіть дані.';end if;
  end loop;
 end if;
 merged:=coalesce(old,'{}'::jsonb)||p_patch;
 if old is not null and merged=old then return old;end if;
 if public.traffic_directory_name(merged->>'name')='' then raise exception 'Назва обов’язкова';end if;
 iban:=substring(regexp_replace(upper(coalesce(merged->>'prumitka','')),'[[:space:]]','','g') from 'UA[0-9]{27}');
 -- An entity can have several bank accounts. Compare IBAN when available;
 -- without one, compare the complete normalized name/recipient pair.
 select count(*) into n from public.faktura f where (p_id is null or f.faktura_id<>p_id) and
  case when iban is not null then substring(regexp_replace(upper(coalesce(f.prumitka,'')),'[[:space:]]','','g') from 'UA[0-9]{27}')=iban
   else public.traffic_directory_name(f.name)=public.traffic_directory_name(merged->>'name') and public.traffic_directory_name(f.oderjyvach)=public.traffic_directory_name(merged->>'oderjyvach') end;
 if n>0 and (p_id is null or public.traffic_directory_name(old->>'name') is distinct from public.traffic_directory_name(merged->>'name')
  or public.traffic_directory_name(old->>'oderjyvach') is distinct from public.traffic_directory_name(merged->>'oderjyvach')
  or substring(regexp_replace(upper(coalesce(old->>'prumitka','')),'[[:space:]]','','g') from 'UA[0-9]{27}') is distinct from iban)
 then raise exception 'Контрагент з такими реквізитами вже існує (% записів). Виберіть потрібний ID.',n;end if;
 if p_id is null then
  select coalesce(max(faktura_id),0)+1 into next_id from public.faktura;
  merged:=merged||jsonb_build_object('faktura_id',next_id);
  insert into public.faktura(faktura_id,name,oderjyvach,prumitka,data,namber)
   select f.faktura_id,f.name,f.oderjyvach,f.prumitka,f.data,f.namber from jsonb_populate_record(null::public.faktura,merged) f;
  get diagnostics affected=row_count;
  p_id:=next_id;
 else
  update public.faktura t set name=f.name,oderjyvach=f.oderjyvach,prumitka=f.prumitka,data=f.data,namber=f.namber from jsonb_populate_record(null::public.faktura,merged) f where t.faktura_id=p_id;
  get diagnostics affected=row_count;
 end if;
 if affected<>1 then raise exception 'База не підтвердила збереження контрагента. Перевірте доступ.' using errcode='42501';end if;
 select to_jsonb(f) into result from public.faktura f where faktura_id=p_id;
 if result is null then raise exception 'Не отримано збережений запис контрагента';end if;
 return result;
end $$;

revoke all on function public.traffic_contragent_write(bigint,jsonb,jsonb) from public;
grant execute on function public.traffic_contragent_write(bigint,jsonb,jsonb) to anon,authenticated;

-- Both reference fields in one confirmation either commit together or roll back.
create or replace function public.traffic_directory_reference_batch(p_changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare item jsonb; result jsonb:='[]'::jsonb; receipt jsonb; selected bigint;
begin
 if jsonb_typeof(p_changes) is distinct from 'array' then raise exception 'Invalid reference batch';end if;
 if jsonb_array_length(p_changes)>2 or exists(select 1 from jsonb_array_elements(p_changes) x where coalesce(x->>'kind','') not in ('shops','details') or coalesce(x->>'mode','') not in ('add','edit','delete'))
  or (select count(*)<>count(distinct x->>'kind') from jsonb_array_elements(p_changes) x) then raise exception 'Invalid reference batch';end if;
 perform pg_advisory_xact_lock(1937010546,1);
 for item in select value from jsonb_array_elements(p_changes) order by value->>'kind' loop
  selected:=nullif(item->>'id','')::bigint;
  if item->>'mode'='add' then
   if selected is not null then raise exception 'New reference must not replace a selected record';end if;
   receipt:=public.traffic_directory_write(item->>'kind',null,item->'patch',null);
  else
   if selected is null or selected<=0 then raise exception 'Selected reference required';end if;
   if item->>'mode'='edit' then receipt:=public.traffic_directory_write(item->>'kind',selected,item->'patch',item->'expected');
   else receipt:=public.traffic_directory_delete(item->>'kind',selected,item->'expected');end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('kind',item->>'kind')||receipt);
 end loop;
 return result;
end $$;
revoke all on function public.traffic_directory_reference_batch(jsonb) from public;
grant execute on function public.traffic_directory_reference_batch(jsonb) to anon,authenticated;
-- END DIRECTORY MODAL INTEGRITY 2026-10-21

-- BEGIN CLIENT CAR MODAL INTEGRITY 2026-10-21
-- SOURCE: 20261021163459_client_car_modal_integrity.sql
-- Client/car form: compact records, atomic delta writes, VIN restore and soft delete.
-- Existing package 8 is required. Existing caller permissions and RLS remain in force.

create or replace function public.traffic_client_car_vin(p_value text)
returns text language sql immutable security invoker set search_path=pg_catalog,public as $$
 select upper(regexp_replace(coalesce(p_value,''),'[[:space:]]','','g'));
$$;

create or replace function public.traffic_client_car_projection(p_kind text,p_data jsonb)
returns jsonb language sql immutable security invoker set search_path=pg_catalog,public as $$
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb)
 from jsonb_each(public.sto_read_object_v1(p_data))
 where key=any(case p_kind when 'client' then array['ПІБ','Телефон','Джерело','Додаткові']
 when 'car' then array['Авто','Номер авто','Обʼєм','Пальне','Vincode','VIN','Рік','КодДВЗ','Код ДВЗ'] else array[]::text[] end)
 or (p_kind='client' and key ilike '%телефон%' and jsonb_typeof(value)='string');
$$;

create or replace function public.traffic_client_car_record(p_kind text,p_id bigint)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if p_kind='client_car' then
  result:=jsonb_build_object('client',public.traffic_client_car_record('client',p_id),
   'car',(select jsonb_build_object('cars_id',cars_id::text,'client_id',client_id::text,'is_deleted',false,
    'data',public.traffic_client_car_projection('car',data)) from public.cars where client_id=p_id and is_deleted is not true order by cars_id limit 1));
 elsif p_kind='client' then
  select jsonb_build_object('client_id',client_id::text,'data',public.traffic_client_car_projection('client',data)) into result
  from public.clients where client_id=p_id;
 elsif p_kind='car' then
  select jsonb_build_object('cars_id',cars_id::text,'client_id',client_id::text,'is_deleted',is_deleted is true,
   'data',public.traffic_client_car_projection('car',data)) into result from public.cars where cars_id=p_id;
 else raise exception 'Unsupported client/car record';end if;
 if result is null then raise exception 'Запис не знайдено або немає доступу. Повторіть вибір.';end if;
 return result;
end $$;

-- A non-unique index supports legacy databases with duplicate VINs. Ambiguous
-- records are rejected, never silently merged or removed by this migration.
create index if not exists cars_form_vin_idx on public.cars
 (public.traffic_client_car_vin(coalesce(nullif(public.sto_read_object_v1(data)->>'Vincode',''),public.sto_read_object_v1(data)->>'VIN')));
create index if not exists cars_form_request_idx on public.cars ((data->>'__client_car_request_id'))
 where data ? '__client_car_request_id';
create index if not exists clients_form_name_idx on public.clients ((lower(btrim(public.sto_read_object_v1(data)->>'ПІБ'))));

create or replace function public.traffic_client_car_save(p_request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare
 op text:=p_request->>'operation'; cid bigint:=nullif(p_request->>'client_id','')::bigint;
 carid bigint:=nullif(p_request->>'cars_id','')::bigint; original_carid bigint:=carid;
 cp jsonb:=coalesce(p_request->'client_patch','{}'); vp jsonb:=coalesce(p_request->'car_patch','{}');
 ce jsonb:=coalesce(p_request->'client_expected','{}'); ve jsonb:=coalesce(p_request->'car_expected','{}');
 cd jsonb; vd jsonb; merged jsonb; owner_id bigint; deleted boolean; ids bigint[]; field text;
  vin text; token text:=p_request->>'request_id'; affected bigint; old_owner bigint; alias_key text;
 client_created boolean:=false; car_created boolean:=false; restored boolean:=false;
 client_changed boolean:=false; car_changed boolean:=false;
begin
 if jsonb_typeof(p_request) is distinct from 'object' or op is null or op not in ('add','edit','delete') then raise exception 'Invalid client/car operation';end if;
 if jsonb_typeof(cp) is distinct from 'object' or jsonb_typeof(vp) is distinct from 'object'
  or jsonb_typeof(ce) is distinct from 'object' or jsonb_typeof(ve) is distinct from 'object' then raise exception 'Invalid field patch';end if;
 for field in select jsonb_object_keys(cp) loop
  if field<>all(array['ПІБ','Телефон','Джерело','Додаткові']) or jsonb_typeof(cp->field) not in ('string','number','null') then raise exception 'Invalid client field %',field;end if;
 end loop;
 for field in select jsonb_object_keys(vp) loop
  if field<>all(array['Авто','Номер авто','Обʼєм','Пальне','Vincode','Рік','КодДВЗ']) or jsonb_typeof(vp->field) not in ('string','number','null') then raise exception 'Invalid car field %',field;end if;
 end loop;
 -- Serializes this short write path, including retry tokens and VIN reassignment.
 perform pg_advisory_xact_lock(1937010547,1);
 if op='add' then
  if token is null or token !~ '^[a-zA-Z0-9_-]{16,100}$' then raise exception 'Missing save request ID';end if;
  select array_agg(cars_id::bigint) into ids from public.cars where data ? '__client_car_request_id' and data->>'__client_car_request_id'=token;
  if cardinality(ids)>1 then raise exception 'Неоднозначне повторне збереження. Оновіть запис.';end if;
  if cardinality(ids)=1 then
   carid:=ids[1];select client_id,is_deleted into owner_id,deleted from public.cars where cars_id=carid;
   if deleted is true or (cid is not null and cid<>owner_id) then raise exception 'Автомобіль уже змінено. Повторіть вибір.';end if;
   return jsonb_build_object('client_id',owner_id::text,'cars_id',carid::text,'saved',true,'replayed',true,
    'client_changed',false,'car_changed',false,'client_created',false,'car_created',false,'car_restored',false,
    'client',public.traffic_client_car_record('client',owner_id),'car',public.traffic_client_car_record('car',carid));
  end if;
 end if;
 if cid is null then
  if op<>'add' then raise exception 'Оберіть клієнта.';end if;
  if nullif(btrim(cp->>'ПІБ'),'') is null or nullif(btrim(cp->>'Телефон'),'') is null then raise exception 'Заповніть ПІБ і телефон клієнта.';end if;
  select array_agg(client_id) into ids from public.clients
   where lower(btrim(public.sto_read_object_v1(data)->>'ПІБ'))=lower(btrim(cp->>'ПІБ'));
  if cardinality(ids)>0 then
   -- Do not choose one of two people with the same name from list ordering.
   select array_agg(c.client_id) into ids from public.clients c where c.client_id=any(ids)
    and exists(select 1 from regexp_split_to_table(coalesce(public.sto_read_object_v1(c.data)->>'Телефон',''),'[,;]') p
     where regexp_replace(p,'[^0-9]','','g')=regexp_replace(cp->>'Телефон','[^0-9]','','g'));
   if cardinality(ids)=1 then cid:=ids[1];cp:='{}';
   else raise exception 'Клієнт із таким ПІБ уже існує. Оберіть потрібного зі списку.';end if;
  else
   insert into public.clients(data) values(cp) returning client_id into cid;
   if cid is null then raise exception 'База не підтвердила створення клієнта.';end if;
   client_created:=true;client_changed:=true;
  end if;
 end if;
 select public.sto_read_object_v1(data) into cd from public.clients where client_id=cid for update;
 if cd is null then raise exception 'Клієнт недоступний. Повторіть вибір.';end if;
 if op<>'delete' then
  if not client_created then
   for field in select jsonb_object_keys(cp) loop
    if coalesce(cd->field,'null') is distinct from coalesce(ce->field,'null') and coalesce(cd->field,'null') is distinct from cp->field then
     raise exception 'Поле клієнта % змінено іншим користувачем. Повторіть вибір.',field;
    end if;
   end loop;
   merged:=cd||cp;
   if nullif(btrim(merged->>'ПІБ'),'') is null then raise exception 'Заповніть ПІБ клієнта.';end if;
   if merged is distinct from cd then
    update public.clients set data=merged where client_id=cid;get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила зміну клієнта.' using errcode='42501';end if;
    client_changed:=true;
   end if;
  end if;
 end if;
 if op='add' then
  if nullif(btrim(vp->>'Авто'),'') is null then raise exception 'Заповніть автомобіль.';end if;
  vin:=public.traffic_client_car_vin(vp->>'Vincode');
  if vin<>'' then
   select array_agg(cars_id::bigint order by cars_id) into ids from public.cars
   where public.traffic_client_car_vin(coalesce(nullif(public.sto_read_object_v1(data)->>'Vincode',''),public.sto_read_object_v1(data)->>'VIN'))=vin;
  else ids:=null;end if;
  if cardinality(ids)>1 then raise exception 'Знайдено кілька автомобілів із цим VIN. Потрібно перевірити дублікати; історію не змінено.';end if;
  if cardinality(ids)=1 then
   carid:=ids[1];
   select public.sto_read_object_v1(data),client_id,is_deleted into vd,owner_id,deleted from public.cars where cars_id=carid for update;
   if vd is null or public.traffic_client_car_vin(coalesce(nullif(vd->>'Vincode',''),vd->>'VIN')) is distinct from vin then
    raise exception 'VIN автомобіля змінено іншим користувачем. Повторіть вибір.';
   end if;
   if deleted is not true then raise exception 'Автомобіль із цим VIN уже активний. Оберіть його; для зміни власника спочатку приховайте авто у попереднього.';end if;
   if original_carid is not null and original_carid<>carid then raise exception 'Вибраний автомобіль не відповідає VIN. Повторіть вибір.';end if;
   if original_carid is not null then
    for field in select jsonb_object_keys(vp) loop
     if coalesce(vd->field,'null') is distinct from coalesce(ve->field,'null') and coalesce(vd->field,'null') is distinct from vp->field then
      raise exception 'Поле автомобіля % змінено іншим користувачем. Повторіть вибір.',field;
     end if;
     alias_key:=case field when 'Vincode' then 'VIN' when 'КодДВЗ' then 'Код ДВЗ' else null end;
     if alias_key is not null and coalesce(vd->alias_key,'null') is distinct from coalesce(ve->alias_key,'null')
      and coalesce(vd->alias_key,'null') is distinct from vp->field then
      raise exception 'Поле автомобіля % змінено іншим користувачем. Повторіть вибір.',alias_key;
     end if;
    end loop;
   end if;
   old_owner:=owner_id;
   merged:=vd||vp;
   if vp ? 'Vincode' and vd ? 'VIN' then merged:=merged||jsonb_build_object('VIN',vp->'Vincode');end if;
   if vp ? 'КодДВЗ' and vd ? 'Код ДВЗ' then merged:=merged||jsonb_build_object('Код ДВЗ',vp->'КодДВЗ');end if;
   update public.cars set client_id=cid,is_deleted=false,data=merged||jsonb_build_object('__client_car_request_id',token) where cars_id=carid;
   get diagnostics affected=row_count;if affected<>1 then raise exception 'База не підтвердила відновлення авто.' using errcode='42501';end if;
   restored:=true;car_changed:=true;
  else
   if original_carid is not null then raise exception 'VIN вибраного автомобіля змінився. Повторіть вибір.';end if;
   insert into public.cars(client_id,is_deleted,data) values(cid,false,vp||jsonb_build_object('__client_car_request_id',token)) returning cars_id into carid;
   if carid is null then raise exception 'База не підтвердила створення авто.';end if;
   car_created:=true;car_changed:=true;
  end if;
 elsif carid is not null then
  select public.sto_read_object_v1(data),client_id,is_deleted into vd,owner_id,deleted from public.cars where cars_id=carid for update;
  if vd is null or owner_id is distinct from cid then raise exception 'Автомобіль уже належить іншому клієнту або недоступний. Повторіть вибір.';end if;
  if op='delete' then
   if deleted is not true then
    for field in select jsonb_object_keys(public.traffic_client_car_projection('car',vd)) loop
     if coalesce(vd->field,'null') is distinct from coalesce(ve->field,'null') then raise exception 'Дані автомобіля змінено. Повторіть вибір перед видаленням.';end if;
    end loop;
    update public.cars set is_deleted=true where cars_id=carid;get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила приховування авто.' using errcode='42501';end if;
    car_changed:=true;
   end if;
  else
   if deleted is true then raise exception 'Автомобіль приховано. Відновіть його через «Додати» за VIN.';end if;
   for field in select jsonb_object_keys(vp) loop
    if coalesce(vd->field,'null') is distinct from coalesce(ve->field,'null') and coalesce(vd->field,'null') is distinct from vp->field then
     raise exception 'Поле автомобіля % змінено іншим користувачем. Повторіть вибір.',field;
    end if;
    alias_key:=case field when 'Vincode' then 'VIN' when 'КодДВЗ' then 'Код ДВЗ' else null end;
    if alias_key is not null and coalesce(vd->alias_key,'null') is distinct from coalesce(ve->alias_key,'null')
     and coalesce(vd->alias_key,'null') is distinct from vp->field then
     raise exception 'Поле автомобіля % змінено іншим користувачем. Повторіть вибір.',alias_key;
    end if;
   end loop;
   merged:=vd||vp;
   -- Keep aliases coherent when a legacy record is edited, including clearing
   -- a value. An old alias must not resurrect a deliberately removed VIN/code.
   if vp ? 'Vincode' and vd ? 'VIN' then merged:=merged||jsonb_build_object('VIN',vp->'Vincode');end if;
   if vp ? 'КодДВЗ' and vd ? 'Код ДВЗ' then merged:=merged||jsonb_build_object('Код ДВЗ',vp->'КодДВЗ');end if;
   if nullif(btrim(merged->>'Авто'),'') is null then raise exception 'Заповніть автомобіль.';end if;
   if vp ? 'Vincode' then
    vin:=public.traffic_client_car_vin(vp->>'Vincode');
    if vin<>'' and exists(select 1 from public.cars where cars_id<>carid and
     public.traffic_client_car_vin(coalesce(nullif(public.sto_read_object_v1(data)->>'Vincode',''),public.sto_read_object_v1(data)->>'VIN'))=vin) then
     raise exception 'VIN уже належить іншому автомобілю. Історію не змінено.';
    end if;
   end if;
   if merged is distinct from vd then
    update public.cars set data=merged where cars_id=carid;get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила зміну авто.' using errcode='42501';end if;
    car_changed:=true;
   end if;
  end if;
 elsif op='delete' or vp<>'{}' then raise exception 'Оберіть автомобіль.';
 end if;
 return jsonb_build_object('client_id',cid::text,'cars_id',carid::text,'saved',true,'client_created',client_created,
  'car_created',car_created,'car_restored',restored,'client_changed',client_changed,'car_changed',car_changed,'previous_client_id',old_owner::text,
  'client',public.traffic_client_car_record('client',cid),'car',case when carid is not null then public.traffic_client_car_record('car',carid) else null end);
end $$;

-- Add one exact VIN lookup for restoring a hidden vehicle. All existing bounded
-- client/scalar options keep their prior implementation and signatures.
create or replace function public.traffic_client_car_vin_option(p_query text,p_after bigint default null)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 with page as (
  select cars_id as id,client_id,is_deleted,public.traffic_client_car_projection('car',data) d from public.cars
  where public.traffic_client_car_vin(p_query)<>'' and (p_after is null or cars_id>p_after)
   and public.traffic_client_car_vin(coalesce(nullif(public.sto_read_object_v1(data)->>'Vincode',''),public.sto_read_object_v1(data)->>'VIN'))=public.traffic_client_car_vin(p_query)
  order by cars_id limit 21
 ), visible as(select * from page order by id limit 20)
 select jsonb_build_object('items',coalesce((select jsonb_agg(jsonb_build_object('id',id::text,'client_id',client_id::text,
  'is_deleted',is_deleted is true,'label',coalesce(nullif(d->>'Vincode',''),d->>'VIN'),'Авто',d->>'Авто','Номер авто',d->>'Номер авто') order by id) from visible),'[]'),
  'has_more',(select count(*)>20 from page),'next_cursor',(select max(id) from visible));
$$;

create index if not exists acts_form_request_idx on public.acts ((data->>'__client_car_request_id')) where data ? '__client_car_request_id';
create or replace function public.traffic_client_car_create_act(p_request jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare cid bigint:=(p_request->>'client_id')::bigint; carid bigint:=(p_request->>'cars_id')::bigint;
 token text:=p_request->>'request_id'; id bigint; old_client bigint; old_car bigint; owner_id bigint; deleted boolean; payload jsonb;
begin
 if token is null or token !~ '^[a-zA-Z0-9_-]{16,100}$' or cid is null or carid is null then raise exception 'Оберіть клієнта та автомобіль.';end if;
 perform pg_advisory_xact_lock(1937010547,1);
 select act_id,client_id,cars_id into id,old_client,old_car from public.acts where data ? '__client_car_request_id' and data->>'__client_car_request_id'=token;
 if id is not null then
  if old_client<>cid or old_car<>carid then raise exception 'Повторний запит стосується іншого авто.';end if;
  return jsonb_build_object('act_id',id,'replayed',true);
 end if;
 perform 1 from public.clients where client_id=cid for key share;
 if not found then raise exception 'Клієнт недоступний.';end if;
 select client_id,is_deleted into owner_id,deleted from public.cars where cars_id=carid for share;
 if not found or owner_id is distinct from cid or deleted is true then raise exception 'Автомобіль приховано або власника змінено. Повторіть вибір.';end if;
 payload:=jsonb_build_object('Деталі',jsonb_build_array(jsonb_build_object('Сума',0,'Ціна',0,'Деталь','','Магазин','','Кількість',0)),
  'Роботи',jsonb_build_array(jsonb_build_object('Сума',0,'Ціна',0,'Робота','','Слюсар','','Кількість',0)),
  'Пробіг',0,'За деталі',0,'За роботу',0,'Приймальник','','Рекомендації','','Примітки','','Загальна сума',0,
  'Причина звернення',coalesce(p_request->>'reason',''),'Прибуток за деталі',0,'Прибуток за роботу',0,'__client_car_request_id',token);
 insert into public.acts(date_on,client_id,cars_id,data,avans,pruimalnyk)
 values(coalesce(nullif(p_request->>'date_on','')::timestamp,localtimestamp),cid,carid,payload,0,nullif(p_request->>'pruimalnyk','')) returning act_id into id;
 if id is null then raise exception 'База не підтвердила створення акта.';end if;
 return jsonb_build_object('act_id',id,'replayed',false);
end $$;

revoke all on function public.traffic_client_car_vin(text),public.traffic_client_car_projection(text,jsonb),
 public.traffic_client_car_record(text,bigint),public.traffic_client_car_save(jsonb),public.traffic_client_car_vin_option(text,bigint),public.traffic_client_car_create_act(jsonb) from public;
grant execute on function public.traffic_client_car_vin(text),public.traffic_client_car_projection(text,jsonb),
 public.traffic_client_car_record(text,bigint),public.traffic_client_car_save(jsonb),public.traffic_client_car_vin_option(text,bigint),public.traffic_client_car_create_act(jsonb) to anon,authenticated;
-- END CLIENT CAR MODAL INTEGRITY 2026-10-21

-- BEGIN PLANNER POST MODAL INTEGRITY 2026-10-21
-- SOURCE: 20261021170138_planner_post_modal_integrity.sql
-- SQL Editor. Atomic post-modal CRUD and planner assignment; compact lazy options.
-- Existing tables/RLS are retained. No payroll history or bookings are rewritten.

create index if not exists idx_planner_post_name_category_id on public.post_name(category,post_id);
create index if not exists idx_planner_post_arxiv_name_post on public.post_arxiv(name_post);
-- Existing imports sometimes used explicit staff IDs. Align the sequence once as
-- migration owner; runtime callers need only their existing USAGE privilege.
do $$
declare sequence_name text; max_id bigint; current_value bigint;
begin
 lock table public.slyusars in share row exclusive mode;
 sequence_name:=pg_get_serial_sequence('public.slyusars','slyusar_id');
 if sequence_name is not null then
  select max(slyusar_id) into max_id from public.slyusars;
  execute format('select last_value from %s',sequence_name::regclass) into current_value;
  if max_id is not null and current_value<=max_id then perform setval(sequence_name::regclass,max_id,true);end if;
 end if;
end $$;

create or replace function public.traffic_planner_name(p_value text)
returns text language sql immutable security invoker set search_path=pg_catalog,public as $$
 select lower(regexp_replace(btrim(coalesce(p_value,'')), '[[:space:]]+', ' ', 'g'))
$$;
create or replace function public.traffic_planner_staff_document(p_value jsonb)
returns jsonb language plpgsql immutable security invoker set search_path=pg_catalog,public as $$
declare v jsonb:=p_value;
begin
 if jsonb_typeof(v)='string' then
  begin v:=(v#>>'{}')::jsonb; exception when invalid_text_representation then return '{}'::jsonb;end;
 end if;
 return case when jsonb_typeof(v)='object' then v else '{}'::jsonb end;
end $$;

create or replace function public.traffic_planner_post_options(
 p_kind text,p_category_id bigint default null,p_query text default '',p_after bigint default null,p_limit integer default 30)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb; q text:=public.traffic_planner_name(p_query); page_limit integer:=least(greatest(coalesce(p_limit,30),1),50);
begin
 if p_kind not in ('category','post','staff') or p_kind is null then raise exception 'Невідомий довідник планувальника';end if;
 if length(coalesce(p_query,''))>200 or coalesce(p_after,0)<0 then raise exception 'Некоректні параметри пошуку';end if;
 if p_kind='post' and coalesce(p_category_id,0)<=0 then raise exception 'Спочатку виберіть цех';end if;
 if p_kind='category' then
  with candidates as materialized (
   select category_id::bigint id,category name from public.post_category
   where category_id>coalesce(p_after,0) and strpos(public.traffic_planner_name(category),q)>0
   order by category_id limit page_limit+1
  ), page as (select * from candidates order by id limit page_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by id) from page),'[]'::jsonb),
   'has_more',(select count(*)>page_limit from candidates),
   'next_cursor',case when (select count(*)>page_limit from candidates) then (select max(id) from page) else null end) into result;
 elsif p_kind='post' then
  with candidates as materialized (
   select post_id::bigint id,name,category from public.post_name
   where category=p_category_id and post_id>coalesce(p_after,0) and strpos(public.traffic_planner_name(name),q)>0
   order by post_id limit page_limit+1
  ), page as (select * from candidates order by id limit page_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by id) from page),'[]'::jsonb),
   'has_more',(select count(*)>page_limit from candidates),
   'next_cursor',case when (select count(*)>page_limit from candidates) then (select max(id) from page) else null end) into result;
 else
  with candidates as materialized (
   select slyusar_id::bigint id,public.traffic_planner_staff_document(to_jsonb(data))->>'Name' name from public.slyusars
   where slyusar_id>coalesce(p_after,0)
    and nullif(btrim(public.traffic_planner_staff_document(to_jsonb(data))->>'Name'),'') is not null
    and strpos(public.traffic_planner_name(public.traffic_planner_staff_document(to_jsonb(data))->>'Name'),q)>0
   order by slyusar_id limit page_limit+1
  ), page as (select * from candidates order by id limit page_limit)
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by id) from page),'[]'::jsonb),
   'has_more',(select count(*)>page_limit from candidates),
   'next_cursor',case when (select count(*)>page_limit from candidates) then (select max(id) from page) else null end) into result;
 end if;
 return result;
end $$;

create or replace function public.traffic_planner_directory_write(
 p_action text,p_category_id bigint default null,p_post_id bigint default null,
 p_patch jsonb default '{}'::jsonb,p_expected jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare c jsonb; p jsonb; ids bigint[]; n text; k text; affected bigint; status text:='unchanged';
 category_changed boolean:=false; post_changed boolean:=false; target_category bigint;
begin
 if p_action is null or p_action not in ('add','edit','delete') or jsonb_typeof(p_patch) is distinct from 'object'
  or jsonb_typeof(p_expected) is distinct from 'object' or coalesce(p_category_id,1)<=0 or coalesce(p_post_id,1)<=0 then raise exception 'Некоректна операція планувальника';end if;
 if exists(select 1 from jsonb_object_keys(p_patch) as fields(key) where fields.key not in ('category','name')) then raise exception 'Дозволені лише назви цеху та поста';end if;
 for k in select jsonb_object_keys(p_patch) loop
  if jsonb_typeof(p_patch->k) is distinct from 'string' or length(btrim(p_patch->>k)) not between 1 and 200 then raise exception 'Назва має містити від 1 до 200 символів';end if;
 end loop;
 -- The same lock order is used by assignment. Legacy direct inserts cannot race MAX+1.
 lock table public.post_category,public.post_name,public.slyusars in share row exclusive mode;
 if p_action='add' then
  if p_post_id is not null then raise exception 'Для додавання не передавайте ID існуючого поста';end if;
  if p_category_id is not null then
   select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id for update;
   if c is null then raise exception 'Цех не знайдено або немає доступу';end if;
   if p_patch?'category' and public.traffic_planner_name(c->>'category')<>public.traffic_planner_name(p_patch->>'category') then raise exception 'Вибраний цех змінився. Виберіть його повторно';end if;
  else
   if not(p_patch?'category') then raise exception 'Виберіть або введіть цех';end if;
   n:=btrim(p_patch->>'category');
   select array_agg(category_id order by category_id) into ids from public.post_category where public.traffic_planner_name(category)=public.traffic_planner_name(n);
   if coalesce(cardinality(ids),0)>1 then raise exception 'Неоднозначна назва цеху. Виберіть конкретний ID';end if;
   p_category_id:=ids[1];
   if p_category_id is null then
    select coalesce(max(category_id),0)+1 into p_category_id from public.post_category;
    insert into public.post_category(category_id,category) values(p_category_id,n);get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила створення цеху';end if;
    status:='created';
   end if;
   select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id;
  end if;
  if p_patch?'name' then
   n:=btrim(p_patch->>'name');
   select array_agg(post_id order by post_id) into ids from public.post_name where category=p_category_id and public.traffic_planner_name(name)=public.traffic_planner_name(n);
   if coalesce(cardinality(ids),0)>1 then raise exception 'Неоднозначна назва поста. Виберіть конкретний ID';end if;
   p_post_id:=ids[1];
   if p_post_id is null then
    select coalesce(max(post_id),0)+1 into p_post_id from public.post_name;
    insert into public.post_name(post_id,name,category) values(p_post_id,n,p_category_id);get diagnostics affected=row_count;
    if affected<>1 then raise exception 'База не підтвердила створення поста';end if;
    status:='created';
   end if;
   select jsonb_build_object('post_id',post_id,'name',name,'category',category) into p from public.post_name where post_id=p_post_id;
  end if;
 else
  if p_post_id is not null then
   select jsonb_build_object('post_id',post_id,'name',name,'category',category) into p from public.post_name where post_id=p_post_id for update;
   if p is null then raise exception 'Пост не знайдено або немає доступу';end if;
   target_category:=(p->>'category')::bigint;
   if p_category_id is distinct from target_category then raise exception 'Пост належить іншому цеху. Виберіть його повторно';end if;
   if not(p_expected?'post_category') or (p_expected->>'post_category')::bigint is distinct from target_category then raise exception 'Прив’язка поста змінилася. Оновіть вибір';end if;
  end if;
  if p_category_id is null then raise exception 'Спочатку виберіть конкретний цех або пост';end if;
  select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id for update;
  if c is null then raise exception 'Цех не знайдено або немає доступу';end if;
  if p_action='delete' then
   if p_post_id is not null then
    if not(p_expected?'name') or p->'name' is distinct from p_expected->'name' then raise exception 'Назва поста змінилася. Оновіть вибір';end if;
    lock table public.post_arxiv in share row exclusive mode;
    if exists(select 1 from public.slyusars where case when btrim(post_sluysar) ~ '^[+]?[0-9]+([.]0+)?$' then btrim(post_sluysar)::numeric=p_post_id else false end)
     or exists(select 1 from public.post_arxiv where name_post=p_post_id::double precision) then raise exception 'Пост використовується працівником або має історію записів. Видалення заблоковано';end if;
    delete from public.post_name where post_id=p_post_id;get diagnostics affected=row_count;
   else
    if not(p_expected?'category') or c->'category' is distinct from p_expected->'category' then raise exception 'Назва цеху змінилася. Оновіть вибір';end if;
    if exists(select 1 from public.post_name where category=p_category_id) then raise exception 'Цех містить пости. Видалення заблоковано';end if;
    delete from public.post_category where category_id=p_category_id;get diagnostics affected=row_count;
   end if;
   if affected<>1 then raise exception 'База не підтвердила видалення. Перевірте доступ' using errcode='42501';end if;
   status:='deleted';
  else
   if p_patch?'name' and p_post_id is null then raise exception 'Для редагування виберіть конкретний пост зі списку';end if;
   if p_patch?'category' then
    if not(p_expected?'category') then raise exception 'Відсутня початкова назва цеху';end if;
    n:=btrim(p_patch->>'category');
    if c->'category' is distinct from p_expected->'category' and c->>'category' is distinct from n then raise exception 'Назву цеху змінено іншим користувачем';end if;
    category_changed:=c->>'category' is distinct from n;
    if category_changed then
     if exists(select 1 from public.post_category where category_id<>p_category_id and public.traffic_planner_name(category)=public.traffic_planner_name(n)) then raise exception 'Цех із такою назвою вже існує';end if;
     update public.post_category set category=n where category_id=p_category_id;get diagnostics affected=row_count;
     if affected<>1 then raise exception 'База не підтвердила редагування цеху' using errcode='42501';end if;
     c:=jsonb_set(c,'{category}',to_jsonb(n));
    end if;
   end if;
   if p_patch?'name' then
    if not(p_expected?'name') then raise exception 'Відсутня початкова назва поста';end if;
    n:=btrim(p_patch->>'name');
    if p->'name' is distinct from p_expected->'name' and p->>'name' is distinct from n then raise exception 'Назву поста змінено іншим користувачем';end if;
    post_changed:=p->>'name' is distinct from n;
    if post_changed then
     if exists(select 1 from public.post_name where post_id<>p_post_id and category=p_category_id and public.traffic_planner_name(name)=public.traffic_planner_name(n)) then raise exception 'Пост із такою назвою вже існує в цьому цеху';end if;
     update public.post_name set name=n where post_id=p_post_id;get diagnostics affected=row_count;
     if affected<>1 then raise exception 'База не підтвердила редагування поста' using errcode='42501';end if;
     p:=jsonb_set(p,'{name}',to_jsonb(n));
    end if;
   end if;
   if category_changed or post_changed then status:='updated';end if;
  end if;
 end if;
 if c is null or (p_post_id is not null and p is null) then raise exception 'База не повернула збережені дані. Перевірте доступ';end if;
 return jsonb_build_object('status',status,'category',c,'post',p);
end $$;

create or replace function public.traffic_planner_post_assign(
 p_category text,p_post text,p_staff_name text,p_staff_id bigint default null,p_namber double precision default null,
 p_category_id bigint default null,p_post_id bigint default null)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare receipt jsonb; c jsonb; p jsonb; s jsonb; ids bigint[]; staff_id bigint; affected bigint; value_type text; staff_sequence text; max_staff_id bigint; sequence_steps integer:=0;
 old_post text; old_number double precision; actual_name text; status text:='updated';
begin
 p_category:=btrim(p_category);p_post:=btrim(p_post);p_staff_name:=btrim(p_staff_name);
 if coalesce(length(p_category),0) not between 1 and 200 or coalesce(length(p_post),0) not between 1 and 200
  or coalesce(length(p_staff_name),0) not between 1 and 200 or coalesce(p_staff_id,1)<=0
  or coalesce(p_category_id,1)<=0 or coalesce(p_post_id,1)<=0
  or p_namber is null or p_namber<=0 or p_namber::text in ('NaN','Infinity','-Infinity') then raise exception 'Заповніть цех, пост, слюсаря та порядок рядка';end if;
 lock table public.post_category,public.post_name,public.slyusars in share row exclusive mode;
 if p_staff_id is null then
  select array_agg(slyusar_id order by slyusar_id) into ids from public.slyusars
   where public.traffic_planner_name(public.traffic_planner_staff_document(to_jsonb(data))->>'Name')=public.traffic_planner_name(p_staff_name);
  if coalesce(cardinality(ids),0)>1 then raise exception 'Неоднозначне ПІБ. Виберіть конкретного слюсаря зі списку';end if;
  staff_id:=ids[1];
 else staff_id:=p_staff_id;end if;
 if staff_id is not null then
  select public.traffic_planner_staff_document(to_jsonb(data))->>'Name',post_sluysar,namber
   into actual_name,old_post,old_number from public.slyusars where slyusar_id=staff_id for update;
  if not found then raise exception 'Слюсаря не знайдено або немає доступу';end if;
  if public.traffic_planner_name(actual_name)<>public.traffic_planner_name(p_staff_name) then raise exception 'ПІБ вибраного слюсаря змінилося. Оновіть вибір';end if;
 else actual_name:=p_staff_name;end if;
 if p_post_id is not null then
  select jsonb_build_object('post_id',post_id,'name',name,'category',category) into p from public.post_name where post_id=p_post_id for update;
  if p is null then raise exception 'Вибраний пост не знайдено або немає доступу';end if;
  if p_category_id is null then p_category_id:=(p->>'category')::bigint;end if;
  if (p->>'category')::bigint<>p_category_id or public.traffic_planner_name(p->>'name')<>public.traffic_planner_name(p_post) then raise exception 'Вибраний пост змінився. Виберіть його повторно';end if;
  select jsonb_build_object('category_id',category_id,'category',category) into c from public.post_category where category_id=p_category_id for update;
  if c is null or public.traffic_planner_name(c->>'category')<>public.traffic_planner_name(p_category) then raise exception 'Вибраний цех змінився. Виберіть його повторно';end if;
 else
  receipt:=public.traffic_planner_directory_write('add',p_category_id,null,jsonb_build_object('category',p_category,'name',p_post),'{}');
  c:=receipt->'category';p:=receipt->'post';
 end if;
 if staff_id is not null then
  if old_number is not null and nullif(btrim(old_post),'') is not null then
   if (case when btrim(old_post) ~ '^[+]?[0-9]+([.]0+)?$' then btrim(old_post)::numeric=(p->>'post_id')::bigint else false end) then status:='unchanged';
   else raise exception 'Слюсар уже доданий до іншого поста планувальника';end if;
  else
   update public.slyusars set namber=p_namber,post_sluysar=p->>'post_id' where slyusar_id=staff_id;get diagnostics affected=row_count;
   if affected<>1 then raise exception 'База не підтвердила призначення слюсаря' using errcode='42501';end if;
   old_number:=p_namber;old_post:=p->>'post_id';
  end if;
 else
  select coalesce(max(slyusar_id),0) into max_staff_id from public.slyusars;
  staff_sequence:=pg_get_serial_sequence('public.slyusars','slyusar_id');
  if staff_sequence is null then staff_id:=max_staff_id+1;
  else
   loop
    staff_id:=nextval(staff_sequence::regclass);sequence_steps:=sequence_steps+1;
    exit when staff_id>max_staff_id;
    if sequence_steps>=1000 then raise exception 'Лічильник ID слюсарів відстає після імпорту. Повторно виконайте SQL-пакет planner-post-modal-repair.sql';end if;
   end loop;
  end if;
  select format_type(a.atttypid,a.atttypmod) into value_type from pg_attribute a where a.attrelid='public.slyusars'::regclass and a.attname='data';
  execute format('insert into public.slyusars(slyusar_id,data,namber,post_sluysar) values($1,$2::%s,$3,$4)',value_type)
   using staff_id,jsonb_build_object('Name',actual_name,'Опис','{}'::jsonb,'Доступ','Слюсар')::text,p_namber,p->>'post_id';
  get diagnostics affected=row_count;
  if affected<>1 then raise exception 'База не підтвердила створення слюсаря' using errcode='42501';end if;
  old_number:=p_namber;old_post:=p->>'post_id';status:='created';
 end if;
 s:=jsonb_build_object('slyusar_id',staff_id,'name',actual_name,'namber',old_number,'post_sluysar',old_post);
 return jsonb_build_object('status',status,'category',c,'post',p,'staff',s);
end $$;

revoke all on function public.traffic_planner_name(text),public.traffic_planner_staff_document(jsonb),
 public.traffic_planner_post_options(text,bigint,text,bigint,integer),
 public.traffic_planner_directory_write(text,bigint,bigint,jsonb,jsonb),
 public.traffic_planner_post_assign(text,text,text,bigint,double precision,bigint,bigint) from public;
grant execute on function public.traffic_planner_name(text),public.traffic_planner_staff_document(jsonb),
 public.traffic_planner_post_options(text,bigint,text,bigint,integer),
 public.traffic_planner_directory_write(text,bigint,bigint,jsonb,jsonb),
 public.traffic_planner_post_assign(text,text,text,bigint,double precision,bigint,bigint) to authenticated;
-- END PLANNER POST MODAL INTEGRITY 2026-10-21

-- BEGIN ACCOUNTING LOADED ROW PAYMENTS 2026-10-21
-- SOURCE: 20261021172731_accounting_shop_payment_scope.sql
-- Exact loaded-row settlements. Existing tables and RLS remain authoritative.
-- Requires traffic_shop_report_page, traffic_shop_report_v2 and traffic_stock_accounting_page.
create or replace function public.traffic_stock_payment_fingerprint(p_row jsonb)
returns text language sql immutable security invoker set search_path=pg_catalog as $$
 select encode(sha256(convert_to(coalesce((select jsonb_object_agg(k,coalesce(p_row->k,'null'::jsonb))
 from unnest(array['sclad_id','time_on','shops','rahunok','akt','name','part_number','kilkist_on','kilkist_off','price',
 'povernennya','xto_povernyv','scladNomer','xto_zamovuv']) k),'{}'::jsonb)::text,'UTF8')),'hex')
$$;

create or replace function public.traffic_shop_report_page(p_filter jsonb default '{}'::jsonb,p_offset integer default 0,p_limit integer default 100)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb;
begin
 if nullif(p_filter->>'from','') is null or nullif(p_filter->>'to','') is null then raise exception 'Встановіть період звіту';end if;
 if p_offset<0 or p_limit<1 or p_limit>200 then raise exception 'Invalid report page'; end if;
 with shops as materialized (
  select shop_id,public.sto_read_object_v1(to_jsonb(data)) body from public.shops
 ), history as materialized (
  select s.shop_id,s.body->>'Name' shop,h.key date_open,e.entry,e.ord entry_ord
  from shops s cross join lateral jsonb_each(case when jsonb_typeof(s.body->'Історія')='object' then s.body->'Історія' else '{}'::jsonb end) h
  cross join lateral jsonb_array_elements(case when jsonb_typeof(h.value)='array' then h.value else '[]'::jsonb end) with ordinality e(entry,ord)
  where public.traffic_search_truthy(s.body->'Name')
 ), raw as (
  select h.shop_id,h.shop,h.date_open,h.entry_ord,h.entry-'Деталі' entry,d.detail,d.detail_ord,a.act_id,a.date_off,
   public.sto_read_object_v1(to_jsonb(a.data)) act_body,
   n.sclad_id stock_id,to_jsonb(n) stock_row,public.sto_read_object_v1(to_jsonb(n)->'data') stock_body
  from history h
  cross join lateral jsonb_array_elements(case when jsonb_typeof(h.entry->'Деталі')='array' then h.entry->'Деталі' else '[]'::jsonb end) with ordinality d(detail,detail_ord)
  left join public.acts a on a.act_id::text=h.entry->>'Акт'
  left join public.sclad n on n.sclad_id::text=d.detail->>'sclad_id'
 ), values_normalized as (
  select *,coalesce(public.traffic_search_number(detail->'Кількість'),0) quantity,
   coalesce(public.traffic_search_number(detail->'Ціна'),0) price,
   case when stock_id is not null then coalesce(public.traffic_search_number(
    case when stock_body ? 'price' then stock_body->'price'
     when jsonb_typeof(stock_row->'data')='string' and stock_body<>'{}'::jsonb then '0'::jsonb
     else stock_row->'price' end),0) end purchase_price,
   public.traffic_search_number(coalesce(stock_body->'scladNomer',stock_row->'scladNomer')) warehouse,
   greatest(coalesce(public.traffic_search_number(act_body->'Знижка'),0),0) discount,
   case when act_id is not null then coalesce(date_off::text,'') else coalesce(entry->>'ДатаЗакриття','') end date_close,
   public.traffic_search_truthy(case when detail ? 'Розраховано' then detail->'Розраховано' else entry->'Розрахунок' end) is_paid,
   coalesce(case when detail ? 'Розраховано' then detail->>'Розраховано' else entry->>'Розрахунок' end,'') payment_date,
   coalesce(detail->>'Найменування','') item,coalesce(detail->>'Каталог','') catalog
  from raw
 ), calculated as (
  select *,quantity*price total,
   case when purchase_price is not null then price*(case when discount>0 then 1-discount/100 else 1 end)*quantity-purchase_price*quantity end margin,
   case coalesce(p_filter->>'dateMode','open') when 'close' then date_close when 'paid' then payment_date else date_open end target_date
  from values_normalized
 ), matches as materialized (
  select *,public.traffic_shop_date(target_date) sort_date from calculated
  where (coalesce(p_filter->>'dateMode','open')='open' or target_date<>'')
   and (coalesce(p_filter->>'from','')='' and coalesce(p_filter->>'to','')='' or
    public.traffic_shop_date(target_date)<>'' and
    (coalesce(p_filter->>'from','')='' or public.traffic_shop_date(target_date)>=p_filter->>'from') and
    (coalesce(p_filter->>'to','')='' or public.traffic_shop_date(target_date)<=p_filter->>'to'))
   and (coalesce(p_filter->>'item','')='' or strpos(lower(item),lower(p_filter->>'item'))>0)
   and (coalesce(p_filter->>'catalog','')='' or strpos(lower(catalog),lower(p_filter->>'catalog'))>0 or
    regexp_replace(lower(normalize(p_filter->>'catalog',NFKC)),'[^[:alnum:]]','','g')<>'' and
    strpos(regexp_replace(lower(normalize(catalog,NFKC)),'[^[:alnum:]]','','g'),regexp_replace(lower(normalize(p_filter->>'catalog',NFKC)),'[^[:alnum:]]','','g'))>0)
   and (coalesce(p_filter->>'status','all')='all' or (p_filter->>'status'='closed')=(date_close<>''))
   and (coalesce(p_filter->>'payment','all')='all' or (p_filter->>'payment'='paid')=is_paid)
 ), filtered as materialized (
  select * from matches where p_filter->>'warehouse' is null or warehouse=public.traffic_search_number(p_filter->'warehouse')
 ), page as materialized (
  select * from filtered order by sort_date desc,shop_id,date_open,entry_ord,detail_ord offset p_offset limit p_limit
 ), page_entries as (
  select distinct p.shop_id,p.shop,p.date_open,p.entry_ord,h.entry from page p
  join history h on h.shop_id=p.shop_id and h.date_open=p.date_open and h.entry_ord=p.entry_ord
 ), page_days as (
  select shop_id,shop,date_open,jsonb_agg(entry order by entry_ord) entries from page_entries group by shop_id,shop,date_open
 ), page_shops as (
  select shop_id,jsonb_build_object('Name',shop,'Історія',jsonb_object_agg(date_open,entries)) data from page_days group by shop_id,shop
 )
 select jsonb_build_object(
  'items',coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
   'rowId',concat(shop_id,':',date_open,':',entry_ord,':',detail_ord),'shopId',shop_id,
   'entryOrdinal',entry_ord,'detailOrdinal',detail_ord,'recordId',detail->>'recordId',
   'paymentFingerprint',encode(sha256(convert_to((detail-'Розраховано')::text,'UTF8')),'hex'),
   'dateOpen',date_open,'dateClose',date_close,'act',entry->>'Акт','automobile',coalesce(entry->>'Автомобіль',''),
   'shop',shop,'item',item,'catalog',catalog,'quantity',quantity,'price',price,'purchasePrice',purchase_price,
   'total',total,'margin',margin,'discountPercent',discount,'isPaid',is_paid,'paymentDate',payment_date,
   'sclad_id',stock_id,'scladNomer',warehouse,'isClosed',date_close<>'',
   'zapchastystName',(select public.sto_read_object_v1(to_jsonb(s.data))->>'Name' from public.slyusars s
    where s.slyusar_id::text=coalesce(stock_body->>'xto_zamovuv',stock_row->>'xto_zamovuv'))
  )) order by sort_date desc,shop_id,date_open,entry_ord,detail_ord) from page),'[]'::jsonb),
  'shops',coalesce((select jsonb_agg(to_jsonb(s) order by shop_id) from page_shops s),'[]'::jsonb),
  'totalCount',(select count(*) from filtered),
  'totals',(select jsonb_build_object('sale',coalesce(sum(total),0),'purchase',coalesce(sum(coalesce(purchase_price,0)*quantity),0),'margin',coalesce(sum(margin),0)) from filtered),
  'warehouses',coalesce((select jsonb_agg(w order by w) from (select distinct warehouse w from matches where warehouse<>0) x),'[]'::jsonb)
 ) into result;
 return result;
end $$;

create or replace function public.traffic_stock_accounting_page(
 p_filter jsonb,p_cursor jsonb default null,p_limit integer default 40,
 p_include_summary boolean default true,p_expected_revision text default null
) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare result jsonb; facets jsonb; filter_hash text:=md5(p_filter::text);
begin
 if p_limit is null or p_limit<1 or p_limit>200 or p_include_summary is null then raise exception 'Invalid stock accounting page';end if;
 if p_cursor is not null and (jsonb_typeof(p_cursor) is distinct from 'object' or p_cursor->>'filter' is distinct from filter_hash
   or coalesce(p_cursor->>'id','')!~'^[1-9][0-9]*$' or coalesce(p_cursor->>'day','')!~'^\d{4}-\d{2}-\d{2}$'
   or p_expected_revision is null) then raise exception 'Invalid stock accounting cursor';end if;
 with filtered as materialized (select * from public.traffic_stock_accounting_rows(p_filter)),
 stamp as (select md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint),'')) version from filtered),
 candidates as (
  select * from filtered where p_cursor is null or (sort_day,(row_data->>'sclad_id')::bigint)<(p_cursor->>'day',(p_cursor->>'id')::bigint)
  order by sort_day desc,(row_data->>'sclad_id')::bigint desc limit p_limit+1
 ), page as (select * from candidates order by sort_day desc,(row_data->>'sclad_id')::bigint desc limit p_limit)
 select jsonb_build_object('items',coalesce((select jsonb_agg(row_data||jsonb_build_object('paymentFingerprint',public.traffic_stock_payment_fingerprint(row_data))
   order by sort_day desc,(row_data->>'sclad_id')::bigint desc) from page),'[]'),
  'has_more',(select count(*)>p_limit from candidates),
  'next_cursor',(select jsonb_build_object('day',sort_day,'id',row_data->'sclad_id','filter',filter_hash)
   from page order by sort_day,(row_data->>'sclad_id')::bigint limit 1),'revision',(select version from stamp))
  ||case when p_include_summary then jsonb_build_object('summary',
   (select jsonb_build_object('totalCount',count(*),'totalAmount',coalesce(sum(amount),0),
    'remainingAmount',coalesce(sum(remaining_amount),0),'payableCount',count(*) filter(where eligible),
    'payableAmount',coalesce(sum(amount) filter(where eligible),0),
    'payableBaseline',md5(coalesce(string_agg(row_data::text,E'\n' order by (row_data->>'sclad_id')::bigint) filter(where eligible),''))) from filtered)) else '{}'::jsonb end
 into result;
 if p_expected_revision is not null and result->>'revision' is distinct from p_expected_revision then raise exception 'ACCOUNTING_REPORT_STALE';end if;
 if p_include_summary then
  with base as (select row_data from public.traffic_stock_accounting_rows(jsonb_build_object(
   'from',p_filter->'from','to',p_filter->'to','dateMode',p_filter->'dateMode','exclude',coalesce(p_filter->'exclude','[]')))),
  ids as (select distinct (row_data->>'xto_zamovuv')::bigint id from base where coalesce(row_data->>'xto_zamovuv','')~'^[1-9][0-9]*$')
  select jsonb_build_object('warehouses',coalesce((select jsonb_agg(id order by id) from (select distinct (row_data->>'scladNomer')::integer id
   from base where coalesce(row_data->>'scladNomer','')~'^[1-9][0-9]*$') w),'[]'),
   'requesters',coalesce((select jsonb_agg(jsonb_build_object('id',ids.id,'name',coalesce(public.traffic_json_object(s.data::jsonb)->>'Name','ID: '||ids.id)) order by ids.id)
    from ids left join public.slyusars s on s.slyusar_id=ids.id),'[]')) into facets;
  result:=result||jsonb_build_object('facets',facets);
 end if;
 return result;
end $$;


create or replace function public.write_stock_payment_rows(p_changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare change jsonb; current_row public.sclad%rowtype; converted public.sclad%rowtype; desired jsonb; actual jsonb; result jsonb:='[]'; n integer;
begin
 if jsonb_typeof(p_changes) is distinct from 'array' or jsonb_array_length(p_changes)<1 or jsonb_array_length(p_changes)>2000 then raise exception 'Некоректний пакет розрахунків';end if;
 if exists(select 1 from jsonb_array_elements(p_changes) x where coalesce(x->>'id','')!~'^[1-9][0-9]*$' or coalesce(x->>'fingerprint','')!~'^[a-f0-9]{64}$' or not(x ? 'expected') or not(x ? 'desired'))
 or exists(select 1 from jsonb_array_elements(p_changes) x group by x->>'id' having count(*)>1) then raise exception 'Некоректні або повторні позиції';end if;
 for change in select value from jsonb_array_elements(p_changes) order by (value->>'id')::bigint loop
  desired:=change->'desired';
  if desired<>'null'::jsonb and (jsonb_typeof(desired)<>'string' or coalesce(change->>'desired','')!~'^\d{4}-\d{2}-\d{2}$') then raise exception 'Некоректна дата оплати';end if;
  if desired<>'null'::jsonb then perform (change->>'desired')::date;end if;
  select * into current_row from public.sclad where sclad_id=(change->>'id')::bigint for update;
  if not found then raise exception 'Позицію видалено або вона недоступна' using errcode='40001';end if;
  if nullif(current_row.povernennya::text,'') is not null then raise exception 'Повернену позицію не можна розрахувати' using errcode='40001';end if;
  if public.traffic_stock_payment_fingerprint(to_jsonb(current_row)) is distinct from change->>'fingerprint' then raise exception 'Позицію змінено. Оновіть звіт і перевірте суму.' using errcode='40001';end if;
  actual:=coalesce(to_jsonb(current_row)->'rosraxovano','null'::jsonb);
  converted:=jsonb_populate_record(null::public.sclad,jsonb_build_object('rosraxovano',desired));
  if actual is distinct from change->'expected' and actual is distinct from to_jsonb(converted)->'rosraxovano' then raise exception 'Оплату вже змінено' using errcode='40001';end if;
  if actual is distinct from to_jsonb(converted)->'rosraxovano' then
   update public.sclad set rosraxovano=converted.rosraxovano where sclad_id=current_row.sclad_id;
   get diagnostics n=row_count;if n<>1 then raise exception 'Запис оплати заборонено' using errcode='42501';end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('id',current_row.sclad_id,'paidAt',desired,'fingerprint',change->'fingerprint'));
 end loop;
 return result;
end $$;

create or replace function public.write_shop_detail_payments(p_changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare change jsonb; shop_id_value bigint; current_row public.shops%rowtype; converted public.shops%rowtype; original jsonb; body jsonb; bucket jsonb; entry jsonb; detail jsonb; desired jsonb; actual jsonb; result jsonb:='[]'; entry_index integer; detail_index integer; n integer; day_key text;
begin
 if jsonb_typeof(p_changes) is distinct from 'array' or jsonb_array_length(p_changes)<1 or jsonb_array_length(p_changes)>2000 then raise exception 'Некоректний пакет розрахунків';end if;
 if exists(select 1 from jsonb_array_elements(p_changes) x where coalesce(x->>'shopId','')!~'^[1-9][0-9]*$' or coalesce(x->>'entryOrdinal','')!~'^[1-9][0-9]*$' or coalesce(x->>'detailOrdinal','')!~'^[1-9][0-9]*$' or coalesce(x->>'fingerprint','')!~'^[a-f0-9]{64}$' or nullif(x->>'date','') is null or nullif(x->>'act','') is null or not(x ? 'expected') or not(x ? 'desired'))
 or exists(select 1 from jsonb_array_elements(p_changes) x group by x->>'shopId',x->>'date',x->>'entryOrdinal',x->>'detailOrdinal' having count(*)>1) then raise exception 'Некоректні або повторні позиції';end if;
 for shop_id_value in select distinct (value->>'shopId')::bigint from jsonb_array_elements(p_changes) order by 1 loop
  select * into current_row from public.shops where shop_id=shop_id_value for update;
  if not found then raise exception 'Магазин недоступний' using errcode='40001';end if;
  original:=to_jsonb(current_row.data);body:=public.sto_read_object_v1(original);
  for change in select value from jsonb_array_elements(p_changes) where (value->>'shopId')::bigint=shop_id_value loop
   day_key:=change->>'date';entry_index:=(change->>'entryOrdinal')::integer-1;detail_index:=(change->>'detailOrdinal')::integer-1;desired:=change->'desired';
   if desired<>'null'::jsonb and (jsonb_typeof(desired)<>'string' or coalesce(change->>'desired','')!~'^\d{4}-\d{2}-\d{2}$') then raise exception 'Некоректна дата оплати';end if;
   if desired<>'null'::jsonb then perform (change->>'desired')::date;end if;
   bucket:=body#>array['Історія',day_key];entry:=bucket->entry_index;detail:=entry#>array['Деталі',detail_index::text];
   if jsonb_typeof(bucket) is distinct from 'array' or jsonb_typeof(detail) is distinct from 'object' or entry->>'Акт' is distinct from change->>'act' then raise exception 'Позицію переміщено або видалено' using errcode='40001';end if;
   if encode(sha256(convert_to((detail-'Розраховано')::text,'UTF8')),'hex') is distinct from change->>'fingerprint' then raise exception 'Деталь змінено. Перевірте суму перед оплатою.' using errcode='40001';end if;
   actual:=coalesce(case when detail ? 'Розраховано' then detail->'Розраховано' else entry->'Розрахунок' end,'null'::jsonb);
   if actual='""'::jsonb then actual:='null';end if;
   if actual is distinct from change->'expected' and actual is distinct from desired then raise exception 'Оплату деталі вже змінено' using errcode='40001';end if;
   -- Explicit null overrides a legacy whole-act settlement without touching siblings.
   if actual is distinct from desired then body:=jsonb_set(body,array['Історія',day_key,entry_index::text,'Деталі',detail_index::text,'Розраховано'],desired);end if;
   result:=result||jsonb_build_array(jsonb_build_object('rowId',concat(shop_id_value,':',day_key,':',entry_index+1,':',detail_index+1),'paidAt',desired,'fingerprint',change->'fingerprint'));
  end loop;
  if body is distinct from public.sto_read_object_v1(original) then
   converted:=jsonb_populate_record(null::public.shops,jsonb_build_object('data',case when jsonb_typeof(original)='string' then to_jsonb(body::text) else body end));
   update public.shops set data=converted.data where shop_id=shop_id_value;
   get diagnostics n=row_count;if n<>1 then raise exception 'Запис оплати заборонено' using errcode='42501';end if;
  end if;
 end loop;
 return result;
end $$;
revoke all on function public.traffic_stock_payment_fingerprint(jsonb),public.write_stock_payment_rows(jsonb),public.write_shop_detail_payments(jsonb) from public;
grant execute on function public.traffic_stock_payment_fingerprint(jsonb),public.write_stock_payment_rows(jsonb),public.write_shop_detail_payments(jsonb) to anon,authenticated;


-- Preserve payment metadata while an act changes the non-payment part of one history entry.
create or replace function public.traffic_shop_entry_without_payments(p_entry jsonb)
returns jsonb language sql immutable security invoker set search_path=pg_catalog as $$
 select case when p_entry is null or p_entry='null' then p_entry else
 jsonb_set(p_entry-'Розрахунок','{Деталі}',coalesce((select jsonb_agg(value-'Розраховано' order by ord)
 from jsonb_array_elements(coalesce(p_entry->'Деталі','[]')) with ordinality d(value,ord)),'[]')) end
$$;
create or replace function public.traffic_shop_detail_legacy_identity(p_detail jsonb)
returns jsonb language sql immutable security invoker set search_path=pg_catalog as $$
 select jsonb_build_array(p_detail->>'sclad_id',p_detail->>'Каталог',p_detail->>'Найменування',p_detail->>'Рахунок')
$$;
create or replace function public.write_shop_history_fragments(p_shop_id bigint,p_changes jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare current_row public.shops%rowtype; converted public.shops%rowtype; original jsonb; body jsonb; change jsonb; bucket jsonb; entry jsonb; desired jsonb; old_detail jsonb; detail jsonb; details jsonb; matches integer; idx integer; n integer; day_key text; act_key text;
begin
 if p_shop_id is null or jsonb_typeof(p_changes) is distinct from 'array' or jsonb_array_length(p_changes)>100 then raise exception 'Некоректний пакет історії';end if;
 select * into current_row from public.shops where shop_id=p_shop_id for update;
 if not found then raise exception 'Магазин недоступний' using errcode='40001';end if;
 original:=to_jsonb(current_row.data);body:=public.sto_read_object_v1(original);
 for change in select value from jsonb_array_elements(p_changes) loop
  day_key:=change->>'date';act_key:=change->>'act';desired:=nullif(change->'desired','null'::jsonb);
  if nullif(day_key,'') is null or nullif(act_key,'') is null or not(change ? 'expected') or not(change ? 'desired') then raise exception 'Некоректна позиція історії';end if;
  bucket:=coalesce(body#>array['Історія',day_key],'[]'::jsonb);
  if jsonb_typeof(bucket)<>'array' then raise exception 'Некоректна історія';end if;
  select count(*),min(ord)::int-1 into matches,idx from jsonb_array_elements(bucket) with ordinality x(value,ord) where value->>'Акт'=act_key;
  if matches>1 then raise exception 'Акт дублюється в історії' using errcode='40001';end if;
  entry:=case when matches=1 then bucket->idx else null end;
  if public.traffic_shop_entry_without_payments(entry) is distinct from public.traffic_shop_entry_without_payments(nullif(change->'expected','null'::jsonb))
   and public.traffic_shop_entry_without_payments(entry) is distinct from public.traffic_shop_entry_without_payments(desired) then raise exception 'Історію акта змінено. Повторіть збереження.' using errcode='40001';end if;
  if desired is not null then
   if jsonb_typeof(desired) is distinct from 'object' or desired->>'Акт' is distinct from act_key or jsonb_typeof(desired->'Деталі') is distinct from 'array' then raise exception 'Некоректна історія акта';end if;
   if exists(select 1 from jsonb_array_elements(desired->'Деталі') d where nullif(d->>'recordId','') is not null group by d->>'recordId' having count(*)>1) then raise exception 'Повторний recordId деталі' using errcode='40001';end if;
   desired:=desired-'Розрахунок';if entry ? 'Розрахунок' then desired:=desired||jsonb_build_object('Розрахунок',entry->'Розрахунок');end if;
   details:='[]';
   for detail in select value from jsonb_array_elements(desired->'Деталі') loop
    old_detail:=null;
    if nullif(detail->>'recordId','') is not null then
     select count(*) into matches from jsonb_array_elements(coalesce(entry->'Деталі','[]')) x where x->>'recordId'=detail->>'recordId';
     if matches>1 then raise exception 'Повторний recordId деталі' using errcode='40001';end if;
     select value into old_detail from jsonb_array_elements(coalesce(entry->'Деталі','[]')) where value->>'recordId'=detail->>'recordId';
    else
     select count(*) into matches from jsonb_array_elements(coalesce(entry->'Деталі','[]')) x where x-'Розраховано'=detail-'Розраховано';
     if matches>1 then raise exception 'Неоднозначна деталь без recordId' using errcode='40001';end if;
     select value into old_detail from jsonb_array_elements(coalesce(entry->'Деталі','[]')) where value-'Розраховано'=detail-'Розраховано';
    end if;
    -- Older close/reopen code removed recordId. Recover only an unambiguous
    -- legacy product identity under the already checked financial baseline.
    if old_detail is null then
     select count(*) into matches from jsonb_array_elements(coalesce(entry->'Деталі','[]')) x
      where nullif(x->>'recordId','') is null and public.traffic_shop_detail_legacy_identity(x)=public.traffic_shop_detail_legacy_identity(detail);
     if matches>1 then raise exception 'Неоднозначна стара деталь без recordId' using errcode='40001';end if;
     if matches=1 then
      if (select count(*) from jsonb_array_elements(desired->'Деталі') x where public.traffic_shop_detail_legacy_identity(x)=public.traffic_shop_detail_legacy_identity(detail))<>1 then raise exception 'Неоднозначне зіставлення старої деталі' using errcode='40001';end if;
      select value into old_detail from jsonb_array_elements(entry->'Деталі') where nullif(value->>'recordId','') is null and public.traffic_shop_detail_legacy_identity(value)=public.traffic_shop_detail_legacy_identity(detail);
     end if;
    end if;
    detail:=detail-'Розраховано';
    if old_detail ? 'Розраховано' then detail:=detail||jsonb_build_object('Розраховано',old_detail->'Розраховано');
    elsif old_detail is null then detail:=detail||jsonb_build_object('Розраховано',null);end if;
    details:=details||jsonb_build_array(detail);
   end loop;
   -- A paid position cannot disappear through an unrelated act save.
   for old_detail in select value from jsonb_array_elements(coalesce(entry->'Деталі','[]')) loop
    if coalesce(case when old_detail ? 'Розраховано' then old_detail->>'Розраховано' else entry->>'Розрахунок' end,'')<>''
     and not exists(select 1 from jsonb_array_elements(details) d where
       nullif(old_detail->>'recordId','') is not null and d->>'recordId'=old_detail->>'recordId'
       or nullif(old_detail->>'recordId','') is null and public.traffic_shop_detail_legacy_identity(d)=public.traffic_shop_detail_legacy_identity(old_detail)) then raise exception 'Спочатку скасуйте розрахунок видаленої деталі' using errcode='40001';end if;
   end loop;
   desired:=jsonb_set(desired,'{Деталі}',details);
   if idx is null then bucket:=bucket||jsonb_build_array(desired);else bucket:=jsonb_set(bucket,array[idx::text],desired);end if;
  elsif entry is not null then
   if exists(select 1 from jsonb_array_elements(coalesce(entry->'Деталі','[]')) d where coalesce(case when d ? 'Розраховано' then d->>'Розраховано' else entry->>'Розрахунок' end,'')<>'') then raise exception 'Спочатку скасуйте розрахунок видалених деталей' using errcode='40001';end if;
   bucket:=bucket-idx;
  end if;
  if not(body ? 'Історія') then body:=jsonb_set(body,'{Історія}','{}');end if;
  body:=jsonb_set(body,array['Історія',day_key],bucket);
 end loop;
 if body is distinct from public.sto_read_object_v1(original) then
  converted:=jsonb_populate_record(null::public.shops,jsonb_build_object('data',case when jsonb_typeof(original)='string' then to_jsonb(body::text) else body end));
  update public.shops set data=converted.data where shop_id=p_shop_id;get diagnostics n=row_count;
  if n<>1 then raise exception 'Запис історії заборонено' using errcode='42501';end if;
 end if;
 return jsonb_build_object('id',p_shop_id,'status','saved');
end $$;

create or replace function public.write_shop_act_status(p_act_id bigint,p_date_key text,p_shop_names text[])
returns integer language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare shop_row public.shops%rowtype; converted public.shops%rowtype; original jsonb; body jsonb; bucket jsonb; entry jsonb; idx integer; n integer; changed integer:=0; closed_at jsonb;
begin
 if p_act_id is null or nullif(p_date_key,'') is null or cardinality(p_shop_names)>2000 then raise exception 'Некоректна історія акта';end if;
 select coalesce(to_jsonb(date_off),'null') into closed_at from public.acts where act_id=p_act_id;
 if not found then raise exception 'Акт недоступний' using errcode='40001';end if;
 for shop_row in select * from public.shops where public.sto_read_object_v1(to_jsonb(data))->>'Name'=any(p_shop_names) order by shop_id for update loop
  original:=to_jsonb(shop_row.data);body:=public.sto_read_object_v1(original);bucket:=body#>array['Історія',p_date_key];
  if jsonb_typeof(bucket) is distinct from 'array' then continue;end if;
  select count(*),min(ord)::int-1 into n,idx from jsonb_array_elements(bucket) with ordinality x(value,ord) where value->>'Акт'=p_act_id::text;
  if n>1 then raise exception 'Акт дублюється в історії';end if;if n=0 then continue;end if;
  entry:=bucket->idx;if coalesce(entry->'ДатаЗакриття','null')=closed_at then continue;end if;
  body:=jsonb_set(body,array['Історія',p_date_key,idx::text,'ДатаЗакриття'],closed_at);
  converted:=jsonb_populate_record(null::public.shops,jsonb_build_object('data',case when jsonb_typeof(original)='string' then to_jsonb(body::text) else body end));
  update public.shops set data=converted.data where shop_id=shop_row.shop_id;get diagnostics n=row_count;
  if n<>1 then raise exception 'Запис історії заборонено' using errcode='42501';end if;changed:=changed+1;
 end loop;return changed;
end $$;
revoke all on function public.traffic_shop_entry_without_payments(jsonb),public.traffic_shop_detail_legacy_identity(jsonb),public.write_shop_history_fragments(bigint,jsonb),public.write_shop_act_status(bigint,text,text[]) from public;
grant execute on function public.traffic_shop_entry_without_payments(jsonb),public.traffic_shop_detail_legacy_identity(jsonb),public.write_shop_history_fragments(bigint,jsonb),public.write_shop_act_status(bigint,text,text[]) to anon,authenticated;

-- Row-level tokens replace legacy whole-act history baselines in the accounting UI.
create or replace function public.traffic_shop_report_v3(p_filter jsonb default '{}'::jsonb,p_offset integer default 0,p_limit integer default 100)
returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$
 select jsonb_set(public.traffic_shop_report_page(p_filter,p_offset,p_limit),'{shops}','[]'::jsonb)
$$;
revoke all on function public.traffic_shop_report_v3(jsonb,integer,integer) from public;
grant execute on function public.traffic_shop_report_v3(jsonb,integer,integer) to anon,authenticated;

-- SOURCE: 20261021172813_accounting_profit_payment_scope.sql
-- Explicit loaded-row settlement. Caller RLS applies; no full history leaves the RPC.

create or replace function public.traffic_profit_payment_baseline(p_row jsonb)
returns text language sql immutable security invoker set search_path=pg_catalog as $$
 select md5((p_row-'isPaid'-'rosraxovanoDate'-'xto_rozraxuvav'-'clientLabel'-'carLabel'-'paymentBaseline'
  -case when (p_row->>'id')::bigint>0 then 'paymentDate' else '__payment_unused' end)::text)
$$;

create or replace function public.traffic_profit_accounting_rows(p_filter jsonb,p_cursor jsonb default null)
returns setof jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare mode text:=coalesce(p_filter->>'mode','open'); from_day date; to_day date;
 act_column text; expense_column text; act_type text; expense_type text; act_predicate text; expense_predicate text;
begin
 if jsonb_typeof(p_filter) is distinct from 'object' or mode not in ('open','close','paid') then raise exception 'Invalid profit filter'; end if;
 if coalesce(p_filter->>'from','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_filter->>'to','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Select a valid profit date range'; end if;
 from_day:=(p_filter->>'from')::date; to_day:=(p_filter->>'to')::date;
 if from_day>to_day then raise exception 'Invalid profit date range'; end if;
 if coalesce(p_filter->>'payment','2') not in ('0','1','2') or coalesce(p_filter->>'type','2') not in ('0','1','2')
  or coalesce(p_filter->>'status','2') not in ('0','1','2') or coalesce(p_filter->>'discount','2') not in ('0','1','2') then raise exception 'Invalid profit switches'; end if;
 if jsonb_typeof(coalesce(p_filter->'exclude_ids','[]'::jsonb))<>'array' then raise exception 'Invalid hidden profit IDs'; end if;
 if exists(select 1 from jsonb_array_elements_text(coalesce(p_filter->'exclude_ids','[]'::jsonb)) id where id !~ '^-?[0-9]+$') then raise exception 'Invalid hidden profit IDs'; end if;
 if p_cursor is not null and (jsonb_typeof(p_cursor) is distinct from 'object' or coalesce(p_cursor->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_cursor->>'id','') !~ '^-?[0-9]+$') then raise exception 'Invalid profit cursor'; end if;
 act_column:=case mode when 'open' then 'date_on' when 'close' then 'date_off' else 'rosraxovano' end;
 expense_column:=case mode when 'paid' then 'dataOff' else 'dataOnn' end;
 select case atttypid when 'timestamp'::regtype then 'timestamp' when 'timestamptz'::regtype then 'timestamptz' when 'date'::regtype then 'date' when 'text'::regtype then 'text' when 'varchar'::regtype then 'text' end into act_type
  from pg_attribute where attrelid='public.acts'::regclass and attname=act_column and attnum>0 and not attisdropped;
 select case atttypid when 'timestamp'::regtype then 'timestamp' when 'timestamptz'::regtype then 'timestamptz' when 'date'::regtype then 'date' when 'text'::regtype then 'text' when 'varchar'::regtype then 'text' end into expense_type
  from pg_attribute where attrelid='public.vutratu'::regclass and attname=expense_column and attnum>0 and not attisdropped;
 if act_type is null or expense_type is null then raise exception 'Unsupported accounting date column'; end if;
 act_predicate:=case when act_type='timestamptz' then format('a.%I >= ($1::timestamp at time zone ''Europe/Kyiv'') and a.%I < ($2::timestamp at time zone ''Europe/Kyiv'')',act_column,act_column)
  else format('a.%I >= $1::%s and a.%I < $2::%s',act_column,act_type,act_column,act_type) end;
 expense_predicate:=case when expense_type='timestamptz' then format('v.%I >= ($1::timestamp at time zone ''Europe/Kyiv'') and v.%I < ($2::timestamp at time zone ''Europe/Kyiv'')',expense_column,expense_column)
  else format('v.%I >= $1::%s and v.%I < $2::%s',expense_column,expense_type,expense_column,expense_type) end;
 return query execute format($query$
 with acts as materialized (
  select a.act_id,a.client_id,a.cars_id,a.date_on,a.date_off,a.rosraxovano,a.xto_rozraxuvav,a.avans,a."tupOplatu",
   public.sto_read_object_v1(to_jsonb(a.data)) d,public.traffic_profit_accounting_day(a.date_on::text) AS day
  from public.acts a where %s
   and ($3->'payment_ids' is null or a.act_id in (select -(x#>>'{}')::bigint from jsonb_array_elements($3->'payment_ids') x where (x#>>'{}')::bigint<0))
 ), visible_acts as materialized (
  select * from acts where d->'Заморожений' is distinct from 'true'::jsonb
   and ($4 is null or (day,-act_id)<($4->>'date',($4->>'id')::bigint))
 ), staff as materialized (
  select s.slyusar_id,public.sto_read_object_v1(to_jsonb(s.data)) d from public.slyusars s
  where exists(select 1 from visible_acts)
 ), salary_records as (
  select s.slyusar_id,h.key day_key,e.ord,public.traffic_profit_accounting_number(e.r->'Акт')::double precision act_id,
   public.traffic_profit_accounting_number(e.r->'ЗарплатаЗапчастин')::double precision parts,
   public.traffic_profit_accounting_number(e.r->'ЗарплатаРоботи')::double precision work,
   public.traffic_profit_accounting_number(e.r->'ЗарплатаЗапчастистів')::double precision buyer
  from staff s cross join lateral jsonb_each(case when jsonb_typeof(s.d->'Історія')='object' then s.d->'Історія' else '{}'::jsonb end) h
   cross join lateral jsonb_array_elements(case when jsonb_typeof(h.value)='array' then h.value else '[]'::jsonb end) with ordinality e(r,ord)
  where s.d->>'Доступ'='Приймальник'
 ), salaries as (
  select s.act_id,sum(s.parts order by s.slyusar_id,s.day_key,s.ord) parts,sum(s.work order by s.slyusar_id,s.day_key,s.ord) work,sum(s.buyer order by s.slyusar_id,s.day_key,s.ord) buyer from salary_records s
   join visible_acts a on a.act_id=s.act_id where s.parts>0 or s.work>0 or s.buyer>0 group by s.act_id
 ), operands as (
  select a.*,public.traffic_profit_accounting_round(public.traffic_profit_accounting_number(d->'Прибуток за деталі')::double precision-coalesce(s.parts,0)-coalesce(s.buyer,0)) parts_profit,
   public.traffic_profit_accounting_round(public.traffic_profit_accounting_number(d->'Прибуток за роботу')::double precision-coalesce(s.work,0)) work_profit,
   public.traffic_profit_accounting_number(d->'За деталі')::double precision full_parts,public.traffic_profit_accounting_number(d->'За роботу')::double precision full_work,
   public.traffic_profit_accounting_number(d->'Знижка')::double precision discount_percent
  from visible_acts a left join salaries s on s.act_id=a.act_id
 ), act_rows as (
  select jsonb_build_object('id',-act_id,'date',day,'sortStamp',public.traffic_profit_accounting_stamp(date_on::text),'paymentDate',public.traffic_profit_accounting_day(date_off::text),'rosraxovanoDate',rosraxovano,
   'category','Прибуток','actNumber',act_id,'description','-','notes','-','amount',parts_profit::double precision+work_profit::double precision,'detailsAmount',parts_profit,'workAmount',work_profit,
   'paymentMethod',coalesce(to_jsonb(avans),'0'::jsonb),'isPaid',nullif(rosraxovano::text,'') is not null,'createdBy','Система',
   'clientId',client_id,'carId',cars_id,'xto_rozraxuvav',xto_rozraxuvav,'fullDetailsAmount',full_parts,'fullWorkAmount',full_work,'fullAmount',full_parts+full_work,
   'tupOplatu',"tupOplatu",'discount',discount_percent,'discountAmount',case when discount_percent>0 then public.traffic_profit_accounting_round((full_parts+full_work)*discount_percent/100,0,true) else 0 end) r
  from operands
 ), expenses as (
  select jsonb_build_object('id',v.vutratu_id,'date',public.traffic_profit_accounting_day(v."dataOnn"::text),'sortStamp',public.traffic_profit_accounting_stamp(v."dataOnn"::text),'paymentDate',public.traffic_profit_accounting_day(v."dataOff"::text),
   'rosraxovanoDate',v."dataOff",'category',coalesce(v.kategoria,''),'description',v.opys_vytraty,'amount',v.suma,
   'paymentMethod',coalesce(v.sposob_oplaty,''),'notes',coalesce(v.prymitky,''),'isPaid',nullif(v."dataOff"::text,'') is not null,'createdBy',v.xto_zapusav,'xto_rozraxuvav',v.xto_zapusav) r
  from public.vutratu v where v.suma<0 and v.act is null and %s
   and ($3->'payment_ids' is null or v.vutratu_id in (select (x#>>'{}')::bigint from jsonb_array_elements($3->'payment_ids') x where (x#>>'{}')::bigint>0))
   and ($4 is null or (public.traffic_profit_accounting_day(v."dataOnn"::text),v.vutratu_id)<($4->>'date',($4->>'id')::bigint))
 ), combined as (select r from act_rows union all select r from expenses)
 select r from combined where
  not exists(select 1 from jsonb_array_elements_text(coalesce($3->'exclude_ids','[]'::jsonb)) hidden where hidden::bigint=(r->>'id')::bigint)
  and
  (nullif($3->>'category','') is null or r->>'category'=$3->>'category')
  and (nullif($3->>'paymentMethod','') is null or case when r->>'category'='Прибуток' then position($3->>'paymentMethod' in coalesce(r->>'tupOplatu',''))>0 else r->>'paymentMethod'=$3->>'paymentMethod' end)
  and (coalesce($3->>'payment','2')='2' or (r->>'isPaid')::boolean=(($3->>'payment')='0'))
  and (coalesce($3->>'type','2')='2' or ((r->>'amount')::numeric>=0)=(($3->>'type')='0'))
  and (r->>'category'<>'Прибуток' or coalesce($3->>'status','2')='2' or (nullif(r->>'paymentDate','') is not null)=(($3->>'status')='0'))
  and (coalesce($3->>'discount','2')='2' or (($3->>'discount')='1' and coalesce((r->>'discountAmount')::numeric,0)>0)
   or (($3->>'discount')='0' and ((r->>'amount')::numeric<0 or coalesce((r->>'discountAmount')::numeric,0)<=0)))
 $query$,act_predicate,expense_predicate) using from_day::text,(to_day+1)::text,p_filter,p_cursor;
end $$;

-- p_rows is the immutable set already downloaded and confirmed by this client.
-- A fixed desired timestamp makes an uncertain same-value retry harmless.
create or replace function public.traffic_profit_payment_rows(p_rows jsonb,p_paid_at text,p_actor text)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare ids jsonb; captured bigint[]; q jsonb; r jsonb; actual jsonb; row_id bigint;
 expected_stamp text; desired_stamp text; requested_stamp text; current_stamp text; result jsonb:='[]'; changed bigint;
 act_paid_type oid; expense_paid_type oid; paid_type oid;
begin
 if jsonb_typeof(p_rows) is distinct from 'array' or jsonb_array_length(p_rows)<1 or jsonb_array_length(p_rows)>1000
  or nullif(btrim(p_actor),'') is null or length(p_actor)>300 then raise exception 'Invalid payment selection'; end if;
 if exists(select 1 from jsonb_array_elements(p_rows) x where jsonb_typeof(x)<>'object'
  or coalesce(x->>'id','') !~ '^-?[1-9][0-9]*$' or coalesce(x->>'baseline','') !~ '^[0-9a-f]{32}$'
  or not(x?'expected_paid') or not(x?'expected_actor')) then raise exception 'Invalid payment baseline'; end if;
 select array_agg((x->>'id')::bigint order by (x->>'id')::bigint),jsonb_agg((x->>'id')::bigint) into captured,ids from jsonb_array_elements(p_rows) x;
 if cardinality(captured)<>(select count(distinct x) from unnest(captured) x) then raise exception 'Duplicate payment selection'; end if;
 requested_stamp:=public.traffic_profit_accounting_stamp(p_paid_at);
 if p_paid_at is not null and requested_stamp is null then raise exception 'Invalid payment timestamp'; end if;
 if requested_stamp is null and exists(select 1 from unnest(captured) x where x>0) then raise exception 'Expense payment cancellation is not supported'; end if;
 select atttypid into act_paid_type from pg_attribute where attrelid='public.acts'::regclass and attname='rosraxovano' and not attisdropped;
 select atttypid into expense_paid_type from pg_attribute where attrelid='public.vutratu'::regclass and attname='dataOff' and not attisdropped;
 if act_paid_type not in ('timestamp'::regtype,'timestamptz'::regtype,'text'::regtype,'varchar'::regtype,'date'::regtype)
  or expense_paid_type not in ('timestamp'::regtype,'timestamptz'::regtype,'text'::regtype,'varchar'::regtype,'date'::regtype) then raise exception 'Unsupported payment timestamp column'; end if;
 perform act_id from public.acts where act_id=any(array(select -selected_id from unnest(captured) selected_id where selected_id<0)) order by act_id for update;
 perform vutratu_id from public.vutratu where vutratu_id=any(captured) order by vutratu_id for update;
 -- Primary-key restrictions are applied before financial expansion. No unseen row can be paid.
 select coalesce(jsonb_object_agg(selected_row->>'id',selected_row),'{}') into actual
 from public.traffic_profit_accounting_rows(jsonb_build_object('from','0001-01-01','to','9998-12-31',
  'mode','open','payment','2','type','2','status','2','discount','2','payment_ids',ids)) selected_row;
 for q in select value from jsonb_array_elements(p_rows) loop
  row_id:=(q->>'id')::bigint; r:=actual->(q->>'id');
  paid_type:=case when row_id<0 then act_paid_type else expense_paid_type end;
  desired_stamp:=case when paid_type='date'::regtype then public.traffic_profit_accounting_stamp(requested_stamp::timestamp::date::text) else requested_stamp end;
  if r is null or public.traffic_profit_payment_baseline(r) is distinct from q->>'baseline' then
   raise exception using errcode='P0001',message='ACCOUNTING_PAYMENT_STALE: сума або запис змінилися. Оновіть звіт.';
  end if;
  current_stamp:=public.traffic_profit_accounting_stamp(r->>'rosraxovanoDate');
  expected_stamp:=public.traffic_profit_accounting_stamp(q->>'expected_paid');
  if nullif(btrim(q->>'expected_paid'),'') is not null and expected_stamp is null then raise exception 'Invalid expected payment timestamp'; end if;
  if current_stamp is not distinct from desired_stamp and (desired_stamp is null or row_id>0 or r->>'xto_rozraxuvav'=p_actor) then
   null; -- Already has this exact requested state, e.g. a lost response followed by retry.
  elsif current_stamp is distinct from expected_stamp or (row_id<0 and (r->>'xto_rozraxuvav') is distinct from (q->>'expected_actor')) then
   raise exception using errcode='P0001',message='ACCOUNTING_PAYMENT_STALE: розрахунок уже змінено іншим користувачем.';
  else
   if row_id<0 and paid_type='timestamptz'::regtype then
    update public.acts set rosraxovano=requested_stamp::timestamp at time zone 'Europe/Kyiv',xto_rozraxuvav=case when desired_stamp is null then null else p_actor end where act_id=-row_id;
   elsif row_id<0 then
    update public.acts set rosraxovano=requested_stamp::timestamp,xto_rozraxuvav=case when desired_stamp is null then null else p_actor end where act_id=-row_id;
   elsif paid_type='timestamptz'::regtype then
    update public.vutratu set "dataOff"=requested_stamp::timestamp at time zone 'Europe/Kyiv' where vutratu_id=row_id;
   else
    update public.vutratu set "dataOff"=requested_stamp::timestamp where vutratu_id=row_id;
   end if;
   get diagnostics changed=row_count;
   if changed<>1 then raise exception using errcode='42501',message='Payment update was not permitted'; end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('id',row_id,'paid_at',desired_stamp,'actor',case when desired_stamp is null then null when row_id<0 then p_actor else r->>'xto_rozraxuvav' end));
 end loop;
 return jsonb_build_object('updated_count',jsonb_array_length(result),'rows',result);
end $$;

create or replace function public.traffic_profit_accounting_page(p_filter jsonb,p_cursor jsonb default null,p_limit integer default 30,p_summary boolean default true,p_expected_revision text default null)
returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare revision text; result jsonb;
begin
 if p_limit is null or p_limit<1 or p_limit>100 then raise exception 'Invalid profit page size'; end if;
 if p_cursor is not null and (coalesce(p_cursor->>'date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(p_cursor->>'id','') !~ '^-?[0-9]+$' or nullif(p_cursor->>'stamp','') is null) then raise exception 'Invalid profit cursor'; end if;
 if p_cursor is not null and p_expected_revision is null then raise exception 'A profit cursor requires its revision'; end if;
 if p_summary and p_cursor is not null then raise exception 'Summary is only available on the first page'; end if;
 with report as materialized (select r from public.traffic_profit_accounting_rows(p_filter) r),
 fingerprint as (select md5(coalesce(string_agg(md5(r::text),',' order by (r->>'id')::bigint),'')) value from report),
 candidates as (select r from report where p_cursor is null or (r->>'date',(r->>'id')::bigint>0,r->>'sortStamp',abs((r->>'id')::bigint))<(p_cursor->>'date',(p_cursor->>'id')::bigint>0,p_cursor->>'stamp',abs((p_cursor->>'id')::bigint))
  order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc limit p_limit+1),
 page as (select r from candidates order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc limit p_limit),
 labelled as (
  select p.r || jsonb_build_object('paymentBaseline',public.traffic_profit_payment_baseline(p.r)) || case when coalesce((p_filter->>'include_client')::boolean,false) and p.r->>'category'='Прибуток' and c.d is not null then
   jsonb_build_object('clientLabel',jsonb_build_object('ПІБ',c.d->'ПІБ','Телефон',c.d->'Телефон','Джерело',c.d->'Джерело','Додаткові',c.d->'Додаткові')) else '{}'::jsonb end
   || case when coalesce((p_filter->>'include_car')::boolean,false) and p.r->>'category'='Прибуток' and a.d is not null then
   jsonb_build_object('carLabel',jsonb_build_object('Авто',a.d->'Авто','Номер авто',a.d->'Номер авто','Обʼєм',a.d->'Обʼєм','КодДВЗ',a.d->'КодДВЗ','Пальне',a.d->'Пальне')) else '{}'::jsonb end r
  from page p left join lateral (select public.sto_read_object_v1(to_jsonb(data)) d from public.clients where client_id=(p.r->>'clientId')::bigint and coalesce((p_filter->>'include_client')::boolean,false)) c on true
   left join lateral (select public.sto_read_object_v1(to_jsonb(data)) d from public.cars where cars_id=(p.r->>'carId')::bigint and coalesce((p_filter->>'include_car')::boolean,false)) a on true
 ), totals as (
  select count(*) count,coalesce(sum((r->>'amount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc),0) amount,
   coalesce(sum((r->>'amount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'<>'Прибуток'),0) negative,
   coalesce(sum(greatest(public.traffic_profit_accounting_number(r->'paymentMethod')::double precision,0) order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is null),0) advances,
   coalesce(sum((r->>'detailsAmount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "detailsProfit",
   coalesce(sum((r->>'workAmount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "workProfit",
   coalesce(sum((r->>'fullDetailsAmount')::double precision-case when (r->>'discountAmount')::double precision>0 and (r->>'fullAmount')::double precision>0 then (r->>'fullDetailsAmount')::double precision*((r->>'discountAmount')::double precision/(r->>'fullAmount')::double precision) else 0::double precision end order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "cashDetails",
   coalesce(sum((r->>'fullWorkAmount')::double precision-case when (r->>'discountAmount')::double precision>0 and (r->>'fullAmount')::double precision>0 then (r->>'fullWorkAmount')::double precision*((r->>'discountAmount')::double precision/(r->>'fullAmount')::double precision) else 0::double precision end order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) "cashWork",
   coalesce(sum((r->>'discountAmount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where r->>'category'='Прибуток' and nullif(r->>'paymentDate','') is not null),0) discount,
   count(*) filter(where not (r->>'isPaid')::boolean) "eligibleCount",
   coalesce(sum((r->>'amount')::double precision order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) filter(where not (r->>'isPaid')::boolean),0) "eligibleAmount",
   md5(coalesce(string_agg(r::text,'|' order by (r->>'id')::bigint) filter(where not (r->>'isPaid')::boolean),'')) "eligibleBaseline"
  from report where p_summary
 )
 select jsonb_build_object('formula_version',1,'revision',(select value from fingerprint),'rows',coalesce((select jsonb_agg(r order by r->>'date' desc,((r->>'id')::bigint>0) desc,r->>'sortStamp' desc,abs((r->>'id')::bigint) desc) from labelled),'[]'::jsonb),
  'has_more',(select count(*)>p_limit from candidates),'next_cursor',(select jsonb_build_object('date',r->>'date','id',(r->>'id')::bigint,'stamp',r->>'sortStamp') from page order by r->>'date',((r->>'id')::bigint>0),r->>'sortStamp',abs((r->>'id')::bigint) limit 1))
  ||case when p_summary then jsonb_build_object('summary',(select to_jsonb(t) from totals t)) else '{}'::jsonb end into result;
 revision:=result->>'revision';
 if p_expected_revision is not null and p_expected_revision is distinct from revision then raise exception using errcode='P0001',message='ACCOUNTING_REPORT_STALE'; end if;
 return result;
end $$;


